MREST=MREST.concat([{"id":5862,"bg":"Кой два от изброените фактори са с най-голямо значение за определяне на дистанцията при движение зад друго ППС?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътя","ok":true,"i":null,"es":"el estado de la vía"},{"t":"скоростта на движение","ok":true,"i":null,"es":"la velocidad"},{"t":"видът на движещото се отпред ППС","ok":false,"i":null,"es":"el tipo de vehículo de delante"},{"t":"видът на превозвания товар","ok":false,"i":null,"es":"el tipo de carga transportada"}],"f":3,"es":"¿Qué dos factores son más importantes para determinar la distancia de seguridad? (2 correctas)","explain":"Los dos factores clave de la distancia de seguridad son la VELOCIDAD (a más velocidad, más metros de reacción y frenada) y el ESTADO DE LA VÍA (mojado o hielo multiplican la frenada). El tipo de vehículo o su carga no son los determinantes."},{"id":5897,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58097.png","v":null,"a":[{"t":"длъжен съм да намаля скоростта","ok":true,"i":null,"es":"estoy obligado a reducir la velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"трябва да премина в лентата за насрещно движение, за да заобиколя децата","ok":false,"i":null,"es":"debo pasar al carril contrario para rodear a los niños"},{"t":"длъжен съм да подам звуков сигнал","ok":false,"i":null,"es":"estoy obligado a tocar el claxon"}],"f":3,"es":"En esta situación: (2 correctas)","explain":"ESTOY OBLIGADO A REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana. Dos NIÑOS están de pie en la calzada, en tu carril, junto a la línea central. De frente viene un coche rojo. En la acera derecha hay más peatones.\n\nNIÑOS EN LA CALZADA = REDUCIR Y PREPARARSE. No sabes si van a seguir cruzando, quedarse quietos o volver atrás.\n\n«PASO AL CARRIL CONTRARIO PARA RODEAR A LOS NIÑOS» es el cebo: por ahí viene un coche y los niños pueden moverse hacia ese lado.\n\n«ESTOY OBLIGADO A TOCAR EL CLAXON» es falso: no hay tal obligación, y puede asustarlos.\n\nCLAVE: con niños en la calzada, ni claxon ni esquivas: reducir y estar listo para parar. Ver Leyes → «Niños en la vía»."},{"id":5911,"bg":"При движение в мъгла, непосредствено зад друго превозно средство, водачът може да намали вероятността за произшествие като:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намали скоростта","ok":true,"i":null,"es":"reduce la velocidad"},{"t":"увеличи дистанцията","ok":true,"i":null,"es":"aumenta la distancia"},{"t":"се придържа близо до движещото се пред него превозно средство","ok":false,"i":null,"es":"se pega al vehículo de delante"},{"t":"използва дълги светлини вместо къси светлини","ok":false,"i":null,"es":"usa luces largas en vez de cortas"}],"f":3,"es":"Circulando en niebla justo detrás de otro vehículo, el conductor puede reducir la probabilidad de colisión si: (2 correctas)","explain":"En niebla: reduce la velocidad y AUMENTA la distancia (frenada más larga, visibilidad corta). Pegarse al de delante es lo contrario de lo necesario, y las largas en niebla deslumbran al reflejarse: se usan las cortas o antiniebla."},{"id":5913,"bg":"При преминаване през локви по платното за движение водачът е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи със скорост, с която да предпази пешеходците от изпръскване","ok":true,"i":null,"es":"circular a velocidad que no salpique a los peatones"},{"t":"да подаде сигнал, за да предупреди пешеходците да се пазят от изпръскване","ok":false,"i":null,"es":"señalizar con el claxon para advertir a los peatones"}],"f":3,"es":"Al pasar por charcos en la calzada, el conductor está obligado a:","explain":"Al pasar por charcos debes moderar la velocidad para no salpicar a los peatones: es una obligación legal de respeto. El claxon no soluciona nada y su uso en ciudad está restringido."},{"id":11689,"bg":"Когато няма други ограничения, водачът на мотопед при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":3,"es":"Sin otras restricciones, el conductor de un ciclomotor en zona urbana no debe superar:","explain":"45 km/h: es el máximo de los ciclomotores en cualquier vía, por su propia limitación constructiva. No sube en ciudad ni fuera de ella."},{"id":11691,"bg":"Когато няма други ограничения, водачът на мотопед при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":3,"es":"Sin otras restricciones, el conductor de un ciclomotor fuera de población no debe superar:","explain":"45 km/h también fuera de población: el límite del ciclomotor es constructivo, no depende del tipo de vía. Nunca puede circular a 60 o 70."},{"id":11696,"bg":"Когато няма други ограничения, водачът на автомобил от категория В при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":3,"es":"Sin otras restricciones, el conductor de turismo categoría B en zona urbana no debe superar:","explain":"50 km/h: límite general urbano para turismos categoría B, salvo señal que indique otro valor."},{"id":11706,"bg":"Разрешено ли е след този пътен знак да се движите със скорост 40 km/h?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57515.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Está permitido circular a 40 km/h después de esta señal?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. A la derecha, una señal circular AZUL con «50» TACHADA por una barra roja: FIN DE LA VELOCIDAD MÍNIMA OBLIGATORIA.\n\nYA NO HAY MÍNIMO. Después de esta señal no estás obligado a ir al menos a 50 km/h, así que circular a 40 km/h está permitido.\n\n«NO» es el cebo de quien no distingue entre el mínimo (azul) y el fin del mínimo (azul tachado).\n\nCLAVE: azul tachado = se acaba la obligación de velocidad mínima. Compárala con la 5830. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6221,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69470.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"}],"f":3,"es":"En esta situación tiene prioridad:","explain":"EL COCHE AZUL. Una sola correcta.\n\nQUÉ VES. Una vía de varios carriles. El coche AZUL circula por su carril. Por la DERECHA, desde un carril de acceso, se incorpora un coche ROJO con el intermitente izquierdo.\n\nCEDE EL QUE ENTRA. El rojo se incorpora a la calzada por la que ya circula el azul: la preferencia es del que ya está.\n\n«EL ROJO» es el cebo de quien aplica la regla de la derecha: una incorporación desde un acceso no es un cruce de vías iguales.\n\nCLAVE: es la misma escena que la 6226. Antes de aplicar la regla de la derecha, comprueba que sea un cruce. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":6235,"bg":"При тази ситуация водачът на лекия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69735.png","v":null,"a":[{"t":"трябва да пропусне товарния автомобил, защото навлиза в заеманата от него пътна лента","ok":true,"i":null,"es":"debe dejar pasar al camión porque entra en su carril"},{"t":"е с предимство при заобикалянето, защото е подал сигнал за маневрата","ok":false,"i":null,"es":"tiene prioridad porque señalizó la maniobra"},{"t":"е с предимство защото е по-близо до препятствието","ok":false,"i":null,"es":"tiene prioridad porque está más cerca del obstáculo"}],"f":3,"es":"En esta situación el conductor del turismo:","explain":"DEBE DEJAR PASAR AL CAMIÓN PORQUE ENTRA EN SU CARRIL. Una sola correcta.\n\nQUÉ VES. Carretera de doble sentido. En el carril del turismo AZUL hay un OBSTÁCULO (un montón de tierra). El azul lleva el intermitente IZQUIERDO para rodearlo. De frente viene un CAMIÓN rojo por su carril.\n\nEL OBSTÁCULO ESTÁ EN TU CARRIL: CEDES TÚ. Para rodearlo, el azul tiene que meterse en el carril del camión. El que tiene el obstáculo en su lado cede al que viene de frente.\n\n«TIENE PRIORIDAD PORQUE SEÑALIZÓ» es el cebo: el intermitente avisa, no da derechos.\n\n«TIENE PRIORIDAD PORQUE ESTÁ MÁS CERCA DEL OBSTÁCULO» es otro cebo: la distancia no cambia nada.\n\nCLAVE: obstáculo en tu carril + alguien de frente = esperas. Compárala con la 11997 (vídeo) y la 6236. Ver Leyes → «Carril: dónde debes circular»."},{"id":6299,"bg":"При тази ситуация трябва да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70548.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":3,"es":"En esta situación debo dejar pasar al coche azul. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Vas a girar a la IZQUIERDA (intermitente y flecha). El semáforo da VERDE (flechas de izquierda/recto y de derecha). De frente viene un coche AZUL con el intermitente, que gira a SU derecha, hacia la misma calle a la que vas tú.\n\nCON EL VERDE PARA LOS DOS, EL QUE GIRA A LA IZQUIERDA CEDE AL QUE VIENE DE FRENTE (siga recto o gire a su derecha). El semáforo os deja pasar a la vez; entre vosotros, el que cruza la trayectoria del otro espera.\n\n«INCORRECTO» es el cebo de quien piensa que, como el azul también gira, ya no hay que cederle.\n\nCLAVE: mismo destino desde lados opuestos = el que gira a la derecha pasa primero. Ver Leyes → «Giro a la izquierda»."},{"id":6379,"bg":"При разминаване на два автомобила задължението за осигуряване на необходимата странична дистанция е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на двамата водачи","ok":true,"i":null,"es":"de ambos conductores"},{"t":"на водача на автомобила с по-големи габарити","ok":false,"i":null,"es":"del conductor del vehículo más grande"},{"t":"на водача на автомобила, който се движи с по-висока скорост","ok":false,"i":null,"es":"del que va más rápido"},{"t":"на водача на автомобила с по-голяма обща маса","ok":false,"i":null,"es":"del de mayor masa total"}],"f":3,"es":"La obligación de garantizar la distancia lateral necesaria al cruzarse es:","explain":"Al cruzarse (разминаване), la distancia lateral es responsabilidad de AMBOS conductores: los dos ejecutan la maniobra simultáneamente. En el adelantamiento, en cambio, responde solo el que adelanta."},{"id":6396,"bg":"Кое от изброените ППС е разрешено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"мотоциклет без кош","ok":true,"i":null,"es":"moto sin sidecar"},{"t":"мотопед","ok":true,"i":null,"es":"ciclomotor"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"съчленен автобус","ok":false,"i":null,"es":"autobús articulado"}],"f":3,"es":"¿Qué vehículo está PERMITIDO adelantar después de esta señal? (2 correctas)","explain":"LA MOTO SIN SIDECAR Y EL CICLOMOTOR. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR.\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\n«TRACTOR» y «AUTOBÚS ARTICULADO» son vehículos de motor: no puedes adelantarlos bajo esta señal.\n\nCLAVE: las excepciones son las dos ruedas estrechas con motor (moto sin sidecar y ciclomotor). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6402,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса до 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"},{"t":"трактори","ok":false,"i":null,"es":"tractores"}],"f":3,"es":"Después de esta señal, los conductores de camiones con MMA ≤3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS MOTOS SIN SIDECAR Y LOS CICLOMOTORES. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR (para todos los conductores, incluidos los de camiones de hasta 3,5 t).\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\n«AUTOBUSES» y «TRACTORES» son vehículos de motor: no se pueden adelantar bajo esta señal.\n\nCLAVE: la señal general se aplica a todos los conductores, conduzcan lo que conduzcan. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6407,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71540.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":3,"es":"¿Está permitido continuar el adelantamiento en esta situación?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO: estás adelantando. Delante va un TRACTOR rojo. A la derecha, la señal de PROHIBIDO ADELANTAR.\n\nEL TRACTOR ES UN VEHÍCULO DE MOTOR, y la señal prohíbe adelantar a los vehículos de motor (salvo motos sin sidecar y ciclomotores). Aunque vaya despacio, no puedes adelantarlo aquí.\n\n«SÍ» es el cebo de quien piensa que un vehículo lento se puede adelantar siempre.\n\nCLAVE: la lentitud no es una excepción; la excepción son las motos sin sidecar y los ciclomotores. Compárala con la 6398. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6410,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71672.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":3,"es":"¿Está permitido el adelantamiento en esta situación?","explain":"NO.\n\nQUÉ VES. Carretera fuera de población. Llevas el intermitente IZQUIERDO y la flecha muestra que quieres adelantar a un coche ROJO. A la derecha, la señal de FIN DE LA LIMITACIÓN de 60 km/h. En el centro de la calzada hay una LÍNEA DOBLE, y la línea de tu lado parece CONTINUA.\n\nLA LÍNEA CONTINUA NO SE CRUZA. Con una línea doble, manda la que está de tu lado: si es continua, no puedes pasar al otro carril para adelantar.\n\n«SÍ» es el cebo: el fin de la limitación de velocidad no tiene nada que ver con la prohibición de adelantar.\n\nCLAVE: fin de limitación de velocidad ≠ permiso para adelantar; mira las marcas del suelo. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6705,"bg":"Ако през нощта, при започване на изпреварване, водачът на превозното средство бъде заслепен, той трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да прекрати изпреварването и се върне в дясната лента","ok":true,"i":null,"es":"abandonar el adelantamiento y volver al carril derecho"},{"t":"да продължи изпреварването, като се приближи до изпреварваното превозно средство","ok":false,"i":null,"es":"continuar acercándose al vehículo adelantado"},{"t":"да продължи изпреварването, като включи дългите светлини","ok":false,"i":null,"es":"continuar con las largas activadas"},{"t":"да прекрати изпреварването, като спре незабавно в лентата в която се движи","ok":false,"i":null,"es":"abandonar y parar inmediatamente en su carril"}],"f":3,"es":"Si de noche al iniciar el adelantamiento el conductor queda deslumbrado, debe:","explain":"Si te deslumbran al iniciar el adelantamiento: abandona la maniobra y vuelve al carril derecho. Continuar a ciegas es suicida y parar en seco en tu carril crea peligro para el que te sigue."},{"id":11872,"bg":"След този пътен знак забраната да изпреварват се отнася за водачите на товарни автомобили с допустима максимална маса над:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828545.png","v":null,"a":[{"t":"1,5 t","ok":false,"i":null,"es":"1.5 t"},{"t":"3,5 t","ok":true,"i":null,"es":"3.5 t"},{"t":"5,5 t","ok":false,"i":null,"es":"5.5 t"},{"t":"7,5 t","ok":false,"i":null,"es":"7.5 t"}],"f":3,"es":"Después de esta señal la prohibición de adelantar para camiones aplica a los de MMA superior a:","explain":"3,5 t. Una sola correcta.\n\nLA SEÑAL. Círculo de borde ROJO con un CAMIÓN rojo y un coche negro: PROHIBIDO ADELANTAR PARA LOS CAMIONES.\n\nA QUIÉN AFECTA. A los camiones con masa máxima autorizada superior a 3,5 t. Los turismos y las furgonetas ligeras no están afectados por esta señal.\n\n«1,5 t», «5,5 t» y «7,5 t» son cifras inventadas para confundir.\n\nCLAVE: en las señales de camiones, la frontera es 3,5 t. Compárala con la 6401. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11890,"bg":"Завиването в обратна посока на мост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено, когато широчината на платното за движение е над 12 метра","ok":false,"i":null,"es":"permitido cuando la anchura supera 12 metros"},{"t":"разрешено, когато видимостта е над 50 метра","ok":false,"i":null,"es":"permitido con visibilidad superior a 50 metros"},{"t":"разрешено, без ограничение","ok":false,"i":null,"es":"permitido sin restricciones"}],"f":3,"es":"El cambio de sentido en puente está:","explain":"Prohibido: en puente nunca se cambia de sentido, sin importar la anchura ni la visibilidad. No hay excepciones legales para esta maniobra en puentes."},{"id":12008,"bg":"При тази ситуация не трябва да предприема изпреварване, поради?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":30,"a":[{"t":"състоянието на пътната настилка","ok":false,"i":null,"es":"el estado del pavimento"},{"t":"ограничената видимост","ok":true,"i":null,"es":"la visibilidad limitada"},{"t":"наличието на превозни средства от насрещното движение","ok":true,"i":null,"es":"la presencia de vehículos en sentido contrario"}],"f":3,"es":"En esta situación no debo adelantar por: (2 correctas)"},{"id":12032,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":18,"a":[{"t":"изпреварвам велосипедиста преди той да заобиколи товарния автомобил","ok":false,"i":null,"es":"adelanto al ciclista antes de que rodee el camión"},{"t":"изпреварвам велосипедиста, след като той премине през завоя","ok":true,"i":null,"es":"adelanto al ciclista DESPUÉS de que pase el giro"},{"t":"изпреварвам велосипедиста веднага, след като заобиколи товарния автомобил (преди да премине през завоя)","ok":false,"i":null,"es":"adelanto al ciclista justo al salir del giro"}],"f":3,"es":"¿Cuál es la actuación correcta en esta situación?"},{"id":12039,"bg":"Какъв е правилният начин на действие?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":31,"a":[{"t":"продължавам изпреварването","ok":true,"i":null,"es":"continúo el adelantamiento"},{"t":"прекратявам изпреварването и се връщам в дясната лента","ok":false,"i":null,"es":"abandono el adelantamiento y vuelvo al carril derecho"},{"t":"намалявам скоростта, но продължавам изпреварването","ok":false,"i":null,"es":"reduzco pero continúo"}],"f":3,"es":"¿Cuál es la actuación correcta?"},{"id":12042,"bg":"Защо трябва да прекратите изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":34,"a":[{"t":"защото тракторът е подал сигнал за завой наляво","ok":true,"i":null,"es":"el tractor señalizó girar a la izquierda"},{"t":"защото в този участък изпреварването е забранено","ok":false,"i":null,"es":"en este tramo el adelantamiento está prohibido"},{"t":"защото в лентата за насрещно движение приближава автомобил","ok":true,"i":null,"es":"en el carril contrario se aproxima un vehículo"}],"f":3,"es":"¿Por qué debes abandonar el adelantamiento? (2 correctas)"},{"id":12047,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":39,"a":[{"t":"трябва да намаля скоростта и да продължа движението си в заеманата лента","ok":true,"i":null,"es":"reduzco y continúo en mi carril"},{"t":"да премина в лявата лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"продължавам движението си в заеманата лента, без да намалявам скоростта","ok":false,"i":null,"es":"continúo sin reducir"}],"f":3,"es":"¿Qué debes hacer en esta situación?"},{"id":6526,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57381.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":3,"es":"En esta situación debo: (2 correctas)","explain":"CEDER EL PASO AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo, sin panel). Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche ROJO. Por la DERECHA, por la vía transversal, llega una furgoneta AZUL.\n\nAL ROJO LE CEDES: viene de frente por la misma vía preferente que tú, y el que gira a la izquierda cede al que viene de frente.\n\nAL AZUL LE PASAS TÚ: viene por la vía secundaria, así que te cede aunque esté a tu derecha.\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: el rombo te da preferencia sobre la secundaria, no sobre el que viene de frente por tu misma vía. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6572,"bg":"При тази ситуация пропускам червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67574.png","v":null,"a":[{"t":"се намира от дясната ми страна","ok":true,"i":null,"es":"está a mi derecha"},{"t":"пътят, по който се движа, няма продължение направо","ok":false,"i":null,"es":"el camino que llevo no tiene continuación recta"},{"t":"се движи по пътя, който продължава направо","ok":false,"i":null,"es":"circula por el camino que continúa recto"},{"t":"защото завива наляво","ok":false,"i":null,"es":"gira a la izquierda"}],"f":3,"explain":"PORQUE ESTÁ A MI DERECHA. Una sola correcta.\n\nQUÉ VES. Un cruce en T SIN SEÑALES. Llegas por la calle que se termina y vas a girar a la IZQUIERDA. Por la DERECHA, por la calle que sigue, llega una furgoneta ROJA con el intermitente.\n\nSIN SEÑALES, AUNQUE SEA UNA T, DECIDE LA DERECHA. El rojo te llega por la derecha: le cedes.\n\n«EL CAMINO QUE LLEVO NO TIENE CONTINUACIÓN RECTA» y «CIRCULA POR EL CAMINO QUE CONTINÚA RECTO» son los cebos: en Bulgaria la forma del cruce (una T) no da prioridad; hace falta una señal.\n\n«PORQUE GIRA A LA IZQUIERDA» no es razón para cederle a nadie.\n\nCLAVE: la vía que «continúa» no es preferente si no hay señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha».","es":"En esta situación cedo el paso al rojo porque:"},{"id":6590,"bg":"При тази ситуация мога да премина без да спирам, при условие, че пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56446.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"En esta situación puedo pasar sin detenerme si cedo al azul. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Tienes una señal de STOP. Vas RECTO. Por la IZQUIERDA, por la vía principal, llega un coche AZUL.\n\nCON STOP HAY QUE PARAR SIEMPRE. Ceder al azul es obligatorio, pero no basta: antes tienes que detenerte por completo, aunque veas que puedes pasar después de él.\n\n«CORRECTO» es el cebo: describe lo que harías con un ceda el paso, no con un STOP.\n\nCLAVE: STOP = parada total + ceder. Compárala con la 6588. Ver Leyes → «Vía con prioridad»."},{"id":5603,"bg":"При тази ситуация след като няма слизащи и качващи се пътници, задължени ли сте да спрете?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39569.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"En esta situación, si no hay pasajeros bajando ni subiendo, ¿está obligado a detenerse?","explain":"SÍ.\n\nQUÉ VES. Un TRANVÍA detenido en su parada (señal azul a la derecha), sin isleta. En este momento nadie sube ni baja.\n\nSIN ISLETA, EN LA PARADA DEL TRANVÍA te detienes a 1 m detrás de él mientras está parado, aunque en ese momento no veas a nadie cruzando: los pasajeros pueden bajar y cruzar tu carril en cualquier momento.\n\n«NO» es el cebo de quien cree que, sin pasajeros a la vista, puede pasar.\n\nCLAVE: compárala con la 5606."},{"id":5615,"bg":"При тази ситуация, за да улесня потеглящия от спирката автобус, трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39684.png","v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"при необходимост да спра","ok":true,"i":null,"es":"detenerme si es necesario"},{"t":"да премина в съседната пътна лента","ok":false,"i":null,"es":"pasar al carril contiguo"},{"t":"да премина по-бързо покрай автобуса","ok":false,"i":null,"es":"pasar más rápido junto al autobús"}],"f":3,"es":"En esta situación, para facilitar que el autobús arranque de la parada, debo: (2 correctas)","explain":"REDUCIR LA VELOCIDAD Y DETENERME SI ES NECESARIO. Dos correctas.\n\nQUÉ VES. Calle urbana. A la derecha, un AUTOBÚS en su parada con el intermitente IZQUIERDO, a punto de salir. Tú vienes por detrás.\n\nEN POBLACIÓN, CUANDO UN AUTOBÚS SEÑALIZA QUE SALE DE SU PARADA, los que vienen por detrás en ese carril tienen que reducir la velocidad y, si hace falta, detenerse para dejarle incorporarse.\n\n«PASAR AL CARRIL CONTIGUO» y «PASAR MÁS RÁPIDO» son los cebos: no le facilitan la salida, la complican.\n\nCLAVE: compárala con la 11623."},{"id":5691,"bg":"На водача на мотопед е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи в непосредствена близост до друго пътно превозно средство","ok":true,"i":null,"es":"circular muy cerca de otro vehículo"},{"t":"да управлява превозно средство по площите, предназначени само за пешеходци","ok":true,"i":null,"es":"conducir un vehículo por las zonas destinadas solo a peatones"},{"t":"да се движи по пътния банкет","ok":false,"i":null,"es":"circular por el arcén"},{"t":"да се движи с включени светлини през деня","ok":false,"i":null,"es":"circular con las luces encendidas durante el día"}],"f":3,"es":"Al conductor de un ciclomotor le está prohibido: (2 correctas)","explain":"Prohibido al ciclomotor: pegarse a otro vehículo y circular por zonas peatonales. El arcén derecho apto le está permitido y las luces de día son obligatorias: las dos opciones falsas son las de siempre en esta familia."},{"id":5694,"bg":"На водача на мотопед е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи успоредно до друго двуколесно пътно превозно средство","ok":true,"i":null,"es":"circular en paralelo a otro vehículo de dos ruedas"},{"t":"да се държи за друго пътно превозно средство с цел придвижване по пътя","ok":true,"i":null,"es":"agarrarse a otro vehículo para desplazarse por la vía"},{"t":"да се движи по пътния банкет","ok":false,"i":null,"es":"circular por el arcén"},{"t":"да се движи с включени светлини през деня","ok":false,"i":null,"es":"circular con las luces encendidas durante el día"}],"f":3,"es":"Al conductor de un ciclomotor le está prohibido: (2 correctas)","explain":"Prohibido al ciclomotor: circular en paralelo a otro de dos ruedas y agarrarse a otro vehículo para remolcarse. El arcén y las luces diurnas son las opciones permitidas/obligatorias que esta serie recicla como distractores."},{"id":5695,"bg":"По кой от изброените начини може да бъде обозначен повреденият автомобил при теглене през деня?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с поставен отзад светлоотразителен триъгълник","ok":true,"i":null,"es":"con un triángulo reflectante colocado detrás"},{"t":"с включване на авариен сигнал","ok":true,"i":null,"es":"encendiendo las luces de emergencia"},{"t":"с включване на късите светлини","ok":false,"i":null,"es":"encendiendo las luces cortas"},{"t":"с червена светлина","ok":false,"i":null,"es":"con luz ROJA"}],"f":3,"es":"¿De cuál de las formas indicadas puede señalizarse el automóvil averiado al ser remolcado de día? (2 correctas)","explain":"El remolcado se señaliza de DÍA con: triángulo reflectante detrás o luces de emergencia encendidas. Las cortas no avisan de nada anómalo y la luz roja es señalización nocturna."},{"id":5697,"bg":"По кой от изброените начини може да бъде обозначен повреден автомобил с неизправна осветителна уредба при теглене през нощта?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с поставена отзад червена светлина и включен авариен сигнал","ok":true,"i":null,"es":"con una luz roja colocada detrás y las luces de emergencia encendidas"},{"t":"с поставени отзад червена светлина и светлоотразителен триъгълник","ok":true,"i":null,"es":"con una luz roja y un triángulo reflectante colocados detrás"},{"t":"с поставена отзад бяла светлина","ok":false,"i":null,"es":"con una luz blanca colocada detrás"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"}],"f":3,"es":"¿De cuál de las formas indicadas puede señalizarse un automóvil averiado con el alumbrado averiado al ser remolcado de noche? (2 correctas)","explain":"Remolcado de noche CON el alumbrado averiado: luz roja detrás + luces de emergencia, o luz roja + triángulo detrás. El rojo es el color trasero; una luz blanca detrás diría 'vengo de frente' y la bandera roja es señal diurna."},{"id":5702,"bg":"Каква трябва да бъде дължината на твърдата връзка при теглене на повредено МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от 2 до 4 м","ok":true,"i":null,"es":"de 2 a 4 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"от 4 до 6 м","ok":false,"i":null,"es":"de 4 a 6 m"}],"f":3,"es":"¿Cuál debe ser la longitud de la barra rígida al remolcar un vehículo averiado?","explain":"Barra rígida: de 2 a 4 m. Compárala con el cable flexible (4-6 m): la barra corta transmite control directo; el cable necesita margen de frenado. El par 2-4/4-6 cae constantemente en el examen."},{"id":5754,"bg":"Забранено е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"теглене на повреден автомобил през нощта","ok":false,"i":null,"es":"remolcar un automóvil averiado de noche"},{"t":"теглене на мотоциклети с кош","ok":true,"i":null,"es":"remolcar motocicletas con sidecar"},{"t":"използване на двуколесни МПС за теглене","ok":true,"i":null,"es":"usar vehículos de dos ruedas para remolcar"},{"t":"теглене с едно превозно средство на два повредени автомобила","ok":true,"i":null,"es":"remolcar con un solo vehículo dos automóviles averiados"}],"f":3,"es":"Está prohibido: (3 correctas)","explain":"Prohibido: remolcar motos CON sidecar, usar vehículos de dos ruedas para remolcar y remolcar dos averiados a la vez. Remolcar de noche está PERMITIDO (con la señalización nocturna correcta): esa es la falsa."},{"id":5756,"bg":"Забранено е теглене:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на двуколесни ППС","ok":true,"i":null,"es":"de vehículos de dos ruedas"},{"t":"на мотоциклети с кош","ok":true,"i":null,"es":"de motocicletas con sidecar"},{"t":"на повреден товарен автомобил","ok":false,"i":null,"es":"de un camión averiado"},{"t":"на повреден автомобил през нощта","ok":false,"i":null,"es":"de un automóvil averiado de noche"}],"f":3,"es":"Está prohibido el remolcado: (2 correctas)","explain":"El remolcado de vehículos de DOS RUEDAS y de motos con sidecar está prohibido: inestables como remolcados o remolcadores. Un camión averiado y el remolcado nocturno son perfectamente legales."},{"id":5760,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"превозване на пътници в тегленото моторно превозно средство","ok":true,"i":null,"es":"transportar pasajeros en el vehículo REMOLCADO"},{"t":"теглене при намалена видимост под 50 метра","ok":true,"i":null,"es":"remolcar con visibilidad inferior a 50 metros"},{"t":"теглещото МПС да е от категория, различна от тази на тегленото МПС","ok":false,"i":null,"es":"el vehículo remolcador ser de categoría diferente al remolcado"},{"t":"теглене, когато теглещият автомобил е с ремарке","ok":true,"i":null,"es":"remolcar cuando el automóvil que remolca lleva un remolque"}],"f":3,"es":"Al remolcar un automóvil averiado está prohibido: (3 correctas)","explain":"Prohibido: pasajeros en el remolcado, visibilidad inferior a 50 m y remolcar cuando el remolcador ya lleva un remolque. La categoría de los vehículos NO tiene que coincidir: ese distractor se repite en toda la familia."},{"id":5763,"bg":"Разрешено ли е да превозвате пътници в автомобил, когато той се използва за теглене на друг повреден автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Está permitido transportar pasajeros en un automóvil cuando se usa para remolcar otro automóvil averiado?","explain":"Sí: en el vehículo REMOLCADOR pueden ir pasajeros: conserva motor, frenos y control plenos. La prohibición es solo para el REMOLCADO: esa asimetría es exactamente lo que se pregunta."},{"id":5777,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"теглене при намалена видимост под 50 метра","ok":true,"i":null,"es":"remolcar con visibilidad inferior a 50 metros"},{"t":"теглене с гъвкава връзка по хлъзгав път","ok":true,"i":null,"es":"remolcar con cable flexible en carretera resbaladiza"},{"t":"теглене при ограничена видимост","ok":false,"i":null,"es":"remolcar con visibilidad limitada"},{"t":"теглене с твърда връзка по хлъзгав път","ok":false,"i":null,"es":"remolcar con barra rígida en carretera resbaladiza"}],"f":3,"es":"Al remolcar un vehículo averiado está PROHIBIDO: (2 correctas)","explain":"Prohibido remolcar: con visibilidad inferior a 50 m (reducida) y con cable flexible en firme resbaladizo. Con visibilidad LIMITADA (curvas) no está prohibido, y la barra rígida en resbaladizo es precisamente la opción permitida."},{"id":5785,"bg":"Тегленето на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при намалена видимост под 50 м","ok":true,"i":null,"es":"con visibilidad reducida por debajo de 50 m"},{"t":"когато теглещият автомобил е с ремарке","ok":true,"i":null,"es":"cuando el automóvil que remolca lleva un remolque"},{"t":"през нощта","ok":false,"i":null,"es":"de noche"},{"t":"на автомагистрала","ok":false,"i":null,"es":"en autopista"}],"f":3,"es":"El remolcado de un automóvil averiado está prohibido: (2 correctas)","explain":"Prohibido remolcar: bajo 50 m de visibilidad y cuando el remolcador ya lleva remolque. De noche se permite (con señalización) y en autopista también (con sus reglas: barra rígida 70 km/h, cable solo hasta la salida)."},{"id":5809,"bg":"При тази ситуация водачът на зеления автомобил задължен ли е да пропусне червения автомобил, ако той не е с включен специален светлинен и звуков сигнал?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29260.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":3,"es":"En esta situación, ¿está obligado el conductor del automóvil verde a ceder el paso al automóvil rojo, si este no lleva encendida la señal luminosa y acústica especial?","explain":"NO.\n\nQUÉ VES. Un cruce. El coche VERDE va por la vía con prioridad (rombo amarillo). Por la derecha llega un camión de BOMBEROS rojo.\n\nLA PREFERENCIA ESPECIAL SOLO EXISTE SI EL VEHÍCULO LLEVA ENCENDIDAS LAS SEÑALES LUMINOSA Y ACÚSTICA. Sin ellas, es un vehículo más y se aplican las reglas normales: el verde, por la vía con prioridad, pasa primero.\n\n«SÍ» es el cebo de quien cede a cualquier vehículo de emergencia, lleve o no las señales.\n\nCLAVE: compárala con la 5804. Ver Leyes → «Vía con prioridad»."},{"id":5811,"bg":"При тази ситуация водачът на жълтия автомобил трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29277.png","v":null,"a":[{"t":"да пропусне автомобила със специален режим на движение","ok":true,"i":null,"es":"ceder el paso al automóvil con régimen especial de circulación"},{"t":"да премине преди двата автомобила","ok":false,"i":null,"es":"pasar antes que los dos automóviles"},{"t":"да пропусне двата автомобила","ok":false,"i":null,"es":"ceder el paso a los dos automóviles"}],"f":3,"es":"En esta situación, el conductor del automóvil amarillo debe:","explain":"CEDER EL PASO AL AUTOMÓVIL CON RÉGIMEN ESPECIAL DE CIRCULACIÓN. Una sola correcta.\n\nQUÉ VES. Un cruce. El AMARILLO va por la vía con prioridad (rombo amarillo). Por la izquierda llega un camión de BOMBEROS con luces azules; por la derecha, un coche ROJO, los dos desde vías con ceda el paso.\n\nUN VEHÍCULO EN RÉGIMEN ESPECIAL (con las señales luminosas y acústicas encendidas) pasa por delante de las reglas de prioridad, de las señales y del semáforo: se le cede siempre.\n\nAL ROJO NO LE CEDES: viene por una vía sin prioridad y es él quien tiene que cederte.\n\n«PASAR ANTES QUE LOS DOS» olvida a los bomberos. «CEDER A LOS DOS» le da al rojo una preferencia que no tiene.\n\nCLAVE: compárala con la 5805 y la 5804. Ver Leyes → «Quién manda sobre quién»."},{"id":5823,"bg":"На водача на МПС със специален режим на движение е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не се съобразява с организацията на движението, относно посока на движение и завиване в определени направления","ok":true,"i":null,"es":"no respetar la organización del tráfico en cuanto a sentido de circulación y giros en determinadas direcciones"},{"t":"да паркира на места, където има забрана за паркиране","ok":true,"i":null,"es":"estacionar en lugares donde está prohibido estacionar"},{"t":"да спира за престой на места, където престоят е забранен","ok":true,"i":null,"es":"detenerse para una parada en lugares donde la parada está prohibida"},{"t":"да не управлява по безопасен начин","ok":false,"i":null,"es":"no conducir de forma segura"}],"f":3,"es":"Al conductor de un vehículo con régimen especial de circulación le está permitido: (3 correctas)","explain":"El régimen especial permite: saltarse la organización del tráfico (sentidos, giros), estacionar y parar donde está prohibido: todo al servicio de la emergencia. Lo que NUNCA se le permite es conducir de forma insegura: la prioridad no anula la prudencia."},{"id":5828,"bg":"На водача на МПС със специален режим на движение","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"е разрешено да преминава при забраняващ сигнал на светофара","ok":true,"i":null,"es":"tiene permitido pasar con la señal prohibitiva del semáforo"},{"t":"е разрешено да надвишава разрешената максимална скорост на движение","ok":true,"i":null,"es":"tiene permitido superar la velocidad máxima autorizada"},{"t":"е разрешено да не се съобразява с организацията на движението, относно посока на движение и завиване в определени направления","ok":true,"i":null,"es":"tiene permitido no respetar la organización del tráfico en cuanto a sentido de circulación y giros en determinadas direcciones"},{"t":"е забранено да преминава, без да спира, при наличие на пътен знак, който изисква това","ok":false,"i":null,"es":"tiene prohibido pasar sin detenerse cuando hay una señal que lo exige"}],"f":3,"es":"Al conductor de un vehículo con régimen especial de circulación (3 correctas)","explain":"Puede: pasar en rojo, superar la velocidad y no respetar sentidos y giros. La opción falsa lo dice al revés: también tiene PERMITIDO pasar sin detenerse ante una señal que lo exige: el régimen especial cubre precisamente eso."},{"id":6681,"bg":"При теглене през деня на повредено МПС, кой от изброените начини е най-ефикасен за неговото обозначаване?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"включване на авариен сигнал","ok":true,"i":null,"es":"encender las luces de emergencia"},{"t":"със светлоотразителен триъгълник","ok":false,"i":null,"es":"con un triángulo reflectante"},{"t":"включване на къси светлини","ok":false,"i":null,"es":"encender las luces cortas"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"}],"f":3,"es":"Al remolcar de día un vehículo averiado, ¿cuál de las formas indicadas es la más eficaz para señalizarlo?","explain":"De día, lo MÁS eficaz para el remolcado son las luces de emergencia: se ven en movimiento y desde lejos. El triángulo es para vehículos DETENIDOS (colocado en la vía), las cortas no avisan de anomalía y la bandera roja señaliza cargas, no convoyes."},{"id":11627,"bg":"Моторни превозни средства със специален режим на движение са автомобилите и мотоциклетите, които при движението си подават:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"светлинен сигнал с проблясваща синя и/или червена светлина и специален звуков сигнал","ok":true,"i":null,"es":"señal luminosa de luz azul y/o roja parpadeante Y señal acústica especial"},{"t":"светлинен сигнал с проблясваща синя и/или червена светлина","ok":false,"i":null,"es":"solo señal luminosa de luz azul y/o roja parpadeante"},{"t":"специален звуков сигнал","ok":false,"i":null,"es":"solo señal acústica especial"},{"t":"светлинен сигнал с жълта пробляскваща светлина","ok":false,"i":null,"es":"señal luminosa de luz amarilla parpadeante"}],"f":3,"es":"Los vehículos de motor con régimen especial de circulación son los que usan:","explain":"Régimen especial = luz azul y/o roja parpadeante Y señal acústica especial: las dos juntas. Solo luces o solo sirena no constituyen el régimen, y la luz amarilla identifica a los vehículos-obstáculo, no a los prioritarios."},{"id":5614,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на мост","ok":true,"i":null,"es":"en puente"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"непосредствено след пешеходна пътека","ok":false,"i":null,"es":"inmediatamente después de un paso de peatones"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":3,"es":"La detención (parada) está prohibida: (2 correctas)","explain":"Parada prohibida en PUENTE y en TÚNEL: espacios estrechos sin escape donde un vehículo parado bloquea y sorprende. Después del paso de peatones está permitido (la prohibición es antes), y la pendiente por sí sola no prohíbe."},{"id":5616,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в стеснен участък от пътя","ok":true,"i":null,"es":"en tramo estrecho de la vía"},{"t":"в участък с ограничена видимост","ok":true,"i":null,"es":"en tramo con visibilidad limitada"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de sentido único"},{"t":"на участък от пътя, който е в ремонт","ok":false,"i":null,"es":"en un tramo de la vía en obras"}],"f":3,"es":"La detención (parada) está prohibida: (2 correctas)","explain":"Parada prohibida en tramos ESTRECHOS y con visibilidad LIMITADA: donde no cabes o no te ven a tiempo. La vía de sentido único y las obras no prohíben la parada por sí mismas."},{"id":5625,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в стеснен участък от пътя","ok":true,"i":null,"es":"en tramo estrecho de la vía"},{"t":"на платното за движение, където разстоянието между ППС и пътната маркировка, забранена за пресичане, е по-малко от 3 метра","ok":true,"i":null,"es":"en calzada donde la distancia al marcaje que prohíbe el adelantamiento sería menos de 3m"},{"t":"на неосветен участък от пътя","ok":false,"i":null,"es":"en un tramo de la vía sin iluminación"},{"t":"при намалена видимост под 50 м","ok":false,"i":null,"es":"con visibilidad reducida por debajo de 50 m"}],"f":3,"es":"La detención (parada) está prohibida: (2 correctas)","explain":"Parada prohibida: en tramo estrecho y donde dejarías menos de 3 m hasta la marca que prohíbe cruzar (forzarías a pisarla). La falta de iluminación y la visibilidad reducida no figuran en esta prohibición: no confundir con las reglas de señalización."},{"id":5640,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"в подлез","ok":true,"i":null,"es":"en un paso subterráneo"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":3,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Estacionar prohibido en túnel, paso subterráneo y paso elevado: los tres espacios confinados de la misma familia. La pendiente, una vez más, no es causa de prohibición: es el distractor recurrente de esta serie."},{"id":11894,"bg":"Паркирането на ППС е забранено на кръстовище и на разстояние от него, по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 метра преди кръстовище","ok":true,"i":null,"es":"5 metros ANTES de la intersección"},{"t":"5 метра след кръстовище","ok":true,"i":null,"es":"5 metros DESPUÉS de la intersección"},{"t":"10 метра преди кръстовище","ok":false,"i":null,"es":"10 metros antes"},{"t":"10 метра след кръстовище","ok":false,"i":null,"es":"10 metros después"}],"f":3,"es":"El aparcamiento está prohibido en intersección y a una distancia inferior a: (2 correctas)","explain":"Aparcar prohibido en la intersección y a menos de 5 m ANTES y DESPUÉS: igual que la parada breve. El cruce exige visibilidad a ambos lados: los 10 m de las opciones falsas son el distractor numérico."},{"id":5667,"bg":"При движение през нощта по неосветен път скоростта се избира в зависимост и от дължината на участъка, осветен от фаровете.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":3,"es":"Al circular de noche por una vía sin iluminación, la velocidad se elige también en función de la longitud del tramo iluminado por los faros.","explain":"Correcto: de noche sin iluminación, tu velocidad debe permitir detenerte DENTRO del tramo que iluminan tus faros: más allá de esa luz no sabes qué hay. Es el principio de 'conducir a la vista'."},{"id":5685,"bg":"При разминаване през нощта превключването от дълги на къси светлини е задължително, когато:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"разстоянието между превозните средства е не по-малко от 150 м","ok":true,"i":null,"es":"la distancia entre vehículos es no menos de 150 m"},{"t":"насрещният водач подаде сигнал чрез превключването на светлините","ok":true,"i":null,"es":"el conductor contrario señaliza con sus luces"},{"t":"разстоянието между превозните средства е не по-повече от 50 м","ok":false,"i":null,"es":"la distancia es no más de 50 m"}],"f":3,"es":"De noche, cambiar de largas a cortas al cruzarse es OBLIGATORIO cuando: (2 correctas)","explain":"Cambio a cortas obligatorio: a 150 m o menos del que viene de frente, y SIEMPRE que el otro te avise con sus luces (te está diciendo que lo deslumbras, sea cual sea la distancia). Los '50 m' son una cifra falsa: demasiado tarde."},{"id":5688,"bg":"Как ще постъпите при заслепяване от светлините на насрещно движещото се превозно средство?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"ще намаля скоростта","ok":true,"i":null,"es":"reduciré la velocidad"},{"t":"ще се движа с готовност за спиране","ok":true,"i":null,"es":"circularé preparado para detenerme"},{"t":"ще продължа движението, като включа дългите светлини","ok":false,"i":null,"es":"continuaré la marcha encendiendo las luces largas"},{"t":"ще сигнализирам със звуков сигнал","ok":false,"i":null,"es":"avisaré con una señal acústica"}],"f":3,"es":"¿Cómo actuará si le deslumbran las luces del vehículo que viene de frente? (2 correctas)","explain":"Deslumbrado: reduce la velocidad y prepárate para parar: durante los segundos de recuperación conduces casi a ciegas. Responder con tus largas duplica el problema y el claxon no devuelve la visión."},{"id":5693,"bg":"На кои колела на автомобила се поставят при необходимост веригите за сняг?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"веригите за сняг се поставят винаги на предните колела","ok":false,"i":null,"es":"las cadenas van siempre en las ruedas delanteras"},{"t":"на колелата, които не се задвижват от двигателя","ok":false,"i":null,"es":"en las ruedas que NO son motrices"},{"t":"на колелата, които се задвижват от двигателя","ok":true,"i":null,"es":"en las ruedas MOTRICES (las que impulsa el motor)"},{"t":"веригите за сняг се поставят винаги на задните колела","ok":false,"i":null,"es":"las cadenas van siempre en las ruedas traseras"}],"f":3,"es":"¿En qué ruedas se colocan las cadenas de nieve?","explain":"En las ruedas MOTRICES: las cadenas dan tracción, y la tracción está donde el motor empuja. En un tracción delantera van delante, en un propulsión van detrás: no hay regla fija de eje, la regla es 'las que impulsa el motor'."},{"id":5707,"bg":"Какво влияние оказва върху движението на превозното средство силният страничен вятър?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"може да го отклони от посоката му на движение","ok":true,"i":null,"es":"puede desviarlo de su dirección de marcha"},{"t":"не му влияе","ok":false,"i":null,"es":"no le afecta"},{"t":"намалява разхода на гориво","ok":false,"i":null,"es":"reduce el consumo de combustible"}],"f":3,"es":"¿Qué influencia tiene sobre la marcha del vehículo el viento lateral fuerte?","explain":"El viento lateral fuerte puede DESVIARTE de la trayectoria: empuja al vehículo (más cuanto más alto y ligero). Se contrarresta con las manos firmes y reduciendo: jamás es neutro ni 'ahorra combustible'."},{"id":6686,"bg":"Този знак сигнализира за:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29110.png","v":null,"a":[{"t":"задължително движение с вериги за сняг най-малко на две от двигателните колела","ok":true,"i":null,"es":"circulación obligatoria con cadenas de nieve al menos en dos de las ruedas motrices"},{"t":"хлъзгав участък от пътя","ok":false,"i":null,"es":"tramo de vía deslizante"},{"t":"забрана за движение с неподходящи за сезона гуми","ok":false,"i":null,"es":"prohibición de circular con neumáticos inadecuados para la temporada"}],"f":3,"es":"Esta señal indica:","explain":"CIRCULACIÓN OBLIGATORIA CON CADENAS DE NIEVE AL MENOS EN DOS RUEDAS MOTRICES. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con un NEUMÁTICO con cadenas.\n\nCÍRCULO AZUL = OBLIGACIÓN: a partir de ahí hay que llevar cadenas montadas, al menos en dos ruedas motrices.\n\n«TRAMO DESLIZANTE» es un triángulo con un coche derrapando. «PROHIBIDO CON NEUMÁTICOS INADECUADOS» no es el significado de esta señal.\n\nCLAVE: azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6708,"bg":"Разрешено ли е допълнителните светлини за мъгла да се използват при снеговалеж?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само при значително намалена видимост","ok":true,"i":null,"es":"sí, pero solo con visibilidad considerablemente reducida"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Está permitido usar las luces antiniebla adicionales cuando nieva?","explain":"Con nieve sí, pero SOLO si la visibilidad está considerablemente reducida: la misma regla que con lluvia. Las antiniebla no son luces de invierno: son luces de emergencia visual."},{"id":11874,"bg":"Разрешено ли е използването на гуми с шипове при движение по пътищата, отворени за обществено ползване?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не е разрешено","ok":true,"i":null,"es":"no está permitido"},{"t":"да, винаги при сняг и зимни условия","ok":false,"i":null,"es":"sí, siempre con nieve y condiciones invernales"},{"t":"да, но само когато пътните условия изискват това","ok":false,"i":null,"es":"sí, pero solo cuando las condiciones de la vía lo exigen"},{"t":"не е разрешено, само за автомобили с обща маса над 3,5 t","ok":false,"i":null,"es":"no está permitido, solo para automóviles de masa total superior a 3,5 t"}],"f":3,"es":"¿Está permitido usar neumáticos con clavos al circular por vías abiertas al uso público?","explain":"Los neumáticos con clavos están prohibidos en las vías públicas búlgaras: destrozan el asfalto. Ni la nieve ni las 'condiciones que lo exijan' los legalizan: para el hielo están las cadenas (cuando se exigen) y los de invierno."},{"id":5728,"bg":"Поддържането на табелите с регистрационните номера на превозното средство чисти и видими е задължение на:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"водача","ok":true,"i":null,"es":"el conductor"},{"t":"собственика на МПС","ok":false,"i":null,"es":"el propietario del vehículo"},{"t":"пътниците","ok":false,"i":null,"es":"los pasajeros"}],"f":3,"es":"Mantener las placas de matrícula del vehículo limpias y visibles es obligación de:","explain":"Del CONDUCTOR: quien conduce responde de que las placas estén limpias y legibles en ese momento. La propiedad no importa: el control es sobre quien está al volante."},{"id":5741,"bg":"Как трябва да постъпите ако се налага да управлявате МПС, а приемате лекарство, за което не знаете дали е съвместимо с управлението?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"трябва да се запозная с описанието на лекарството в листовката за пациента","ok":true,"i":null,"es":"debo leer la descripción del medicamento en el prospecto"},{"t":"може да приема лекарството и да управлявам ако се чувствам добре","ok":false,"i":null,"es":"puedo tomar el medicamento y conducir si me encuentro bien"},{"t":"мога да се доверя на съвет от приятел или роднина и да управлявам","ok":false,"i":null,"es":"puedo fiarme del consejo de un amigo o familiar y conducir"},{"t":"преди да приема лекарството, трябва да се консултирам с лекар или фармацевт","ok":true,"i":null,"es":"antes de tomar el medicamento, debo consultar a un médico o farmacéutico"}],"f":3,"es":"¿Cómo debe actuar si necesita conducir pero toma un medicamento del que no sabe si es compatible con la conducción? (2 correctas)","explain":"Medicamento de compatibilidad desconocida: lee el prospecto y consulta a médico o farmacéutico ANTES de tomarlo. 'Me encuentro bien' y 'me lo dijo un amigo' no son criterios: muchos fármacos merman sin que se note."},{"id":6110,"bg":"При управление на автомобила опасност от загуба на концентрация има при:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"използване на мобилен телефон","ok":true,"i":null,"es":"usar el teléfono móvil"},{"t":"използване на чистачките на предното стъкло","ok":false,"i":null,"es":"usar los limpiaparabrisas"},{"t":"гледане в страничното огледало","ok":false,"i":null,"es":"mirar por el espejo lateral"}],"f":3,"es":"Al conducir el automóvil, existe peligro de pérdida de concentración al:","explain":"El teléfono móvil: aparta la vista, la mano y la mente a la vez: es la triple distracción. Los limpiaparabrisas y el retrovisor son parte de la conducción: usarlos ES conducir."},{"id":6113,"bg":"Употребата дори и на малко количество алкохол:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"повишава риска за ПТП","ok":true,"i":null,"es":"aumenta el riesgo de accidente"},{"t":"влошава възможността за правилна оценка на скоростта","ok":true,"i":null,"es":"empeora la capacidad de evaluar correctamente la velocidad"},{"t":"действа успокояващо на водача","ok":false,"i":null,"es":"tiene un efecto calmante sobre el conductor"},{"t":"прави водача по-предпазлив при управлението на автомобила","ok":false,"i":null,"es":"hace al conductor más prudente al conducir"}],"f":3,"es":"El consumo incluso de una pequeña cantidad de alcohol: (2 correctas)","explain":"Incluso poco alcohol: aumenta el riesgo de accidente y empeora la evaluación de la velocidad (propia y ajena). El 'efecto calmante' y la 'mayor prudencia' son los autoengaños clásicos que la estadística desmiente."},{"id":6118,"bg":"Какво влияние оказва алкохолът върху поведението на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава координацията на движенията","ok":true,"i":null,"es":"empeora la coordinación"},{"t":"увеличава времето за реакция","ok":true,"i":null,"es":"aumenta el tiempo de reacción"},{"t":"подобрява координацията","ok":false,"i":null,"es":"mejora la coordinación"},{"t":"намалява времето за реакция","ok":false,"i":null,"es":"reduce el tiempo de reacción"}],"f":3,"es":"¿Qué efecto tiene el alcohol en el conductor? (2 correctas)","explain":"El alcohol: empeora la coordinación y AUMENTA el tiempo de reacción: motricidad torpe y respuesta tardía. Las opciones espejo (mejora/reduce) son los mitos exactos que el examen quiere que taches sin dudar."},{"id":6134,"bg":"В кои от случаите водачът трябва да управлява с по-голяма концентрация на вниманието?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"при интензивно движение в дъждовно време","ok":true,"i":null,"es":"con tráfico intenso en tiempo lluvioso"},{"t":"при поява на силен страничен вятър","ok":true,"i":null,"es":"cuando aparece viento lateral fuerte"},{"t":"при снеговалеж","ok":true,"i":null,"es":"cuando nieva"},{"t":"при движение по сух път","ok":false,"i":null,"es":"al circular por una vía seca"}],"f":3,"es":"¿En qué casos debe conducir el conductor con mayor concentración de la atención? (3 correctas)","explain":"Máxima concentración cuando las condiciones se complican: tráfico intenso con lluvia, viento lateral fuerte, nevada. La vía seca y despejada es el escenario base: exige atención normal, no reforzada."},{"id":6138,"bg":"При движение през нощта след преминаване през осветен тунел кои водачи по-бързо привикват с тъмнината?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"по-младите","ok":true,"i":null,"es":"los más jóvenes"},{"t":"по-възрастните","ok":false,"i":null,"es":"los mayores"},{"t":"при всички водачи времето за привикване с тъмнината е еднакво","ok":false,"i":null,"es":"en todos los conductores el tiempo de adaptación a la oscuridad es igual"}],"f":3,"es":"Al circular de noche, después de pasar por un túnel iluminado, ¿qué conductores se adaptan más rápido a la oscuridad?","explain":"Los más JÓVENES: la adaptación a la oscuridad se ralentiza con la edad (el ojo pierde flexibilidad). Por eso los conductores mayores sufren más el paso túnel-noche y los deslumbramientos."},{"id":6142,"bg":"Доброто физическо състояние:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"стимулира мисловната активност","ok":true,"i":null,"es":"estimula la actividad mental"},{"t":"способства за повишаване на концентрацията при управление на МПС","ok":true,"i":null,"es":"contribuye a aumentar la concentración al conducir"},{"t":"няма въздействие върху мисловната активност","ok":false,"i":null,"es":"no tiene efecto sobre la actividad mental"},{"t":"намалява способността за концентрация","ok":false,"i":null,"es":"reduce la capacidad de concentración"}],"f":3,"es":"El buen estado físico: (2 correctas)","explain":"El buen estado físico estimula la actividad mental y mejora la concentración al volante: cuerpo y atención van juntos. Las opciones que lo niegan o lo invierten contradicen la fisiología básica."},{"id":11641,"bg":"Кои от изброените признаци показват умора на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"затруднения в ориентирането в пътната обстановка","ok":true,"i":null,"es":"dificultades para orientarse en la situación del tráfico"},{"t":"продължително търкане на очите","ok":true,"i":null,"es":"frotarse los ojos continuamente"},{"t":"съкращаване на времето за взимане на правилни решения","ok":false,"i":null,"es":"el acortamiento del tiempo para tomar decisiones correctas"},{"t":"полагане на усилие, за да се поддържат очите отворени","ok":true,"i":null,"es":"hacer esfuerzo para mantener los ojos abiertos"}],"f":3,"es":"¿Cuáles de los signos indicados muestran fatiga del conductor? (3 correctas)","explain":"Fatiga: dificultad para orientarse, frotarse los ojos continuamente y esforzarse por mantenerlos abiertos: el cuerpo pidiendo sueño a gritos. El 'acortamiento del tiempo de decisión' sería una mejora: justo lo que la fatiga no da."},{"id":5508,"bg":"В кой от случаите е разрешено водачът да държи мобилния телефон с ръка докато разговаря?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато е спрял автомобила на безопасно място","ok":true,"i":null,"es":"cuando ha detenido el automóvil en un lugar seguro"},{"t":"когато трябва да се свърже с телефонния номер за спешни и аварийни обаждания","ok":false,"i":null,"es":"cuando debe llamar al número de emergencias"},{"t":"когато движението по пътя не е интензивно","ok":false,"i":null,"es":"cuando el tráfico en la vía no es intenso"},{"t":"когато се движи с ниска скорост","ok":false,"i":null,"es":"cuando circula a baja velocidad"}],"f":3,"es":"¿En qué caso está permitido que el conductor sujete el teléfono móvil con la mano mientras habla?","explain":"Solo con el coche DETENIDO en lugar seguro puedes sujetar el móvil con la mano. Ni la emergencia, ni el tráfico ligero ni la baja velocidad lo permiten en marcha: para eso existe el manos libres."},{"id":5509,"bg":"При коя от изброените неизправности е разрешено да се придвижите до място за нейното отстраняване?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"неизправен е скоростомерът","ok":true,"i":null,"es":"el velocímetro está averiado"},{"t":"не светят пътепоказателите през деня","ok":true,"i":null,"es":"los intermitentes no funcionan durante el día"},{"t":"нарушена е херметичността на охладителната уредба","ok":true,"i":null,"es":"el sistema de refrigeración ha perdido estanqueidad"},{"t":"липсва или е повреден елемент за закрепване на джантата към главината на колелото","ok":false,"i":null,"es":"falta o está dañado un elemento de fijación de la llanta al buje de la rueda"}],"f":3,"es":"¿Con cuál de las averías indicadas está permitido desplazarse hasta un lugar donde repararla? (3 correctas)","explain":"Se permite llegar al taller con: velocímetro averiado, intermitentes sin funcionar DE DÍA (señalizas con la mano) o refrigeración sin estanqueidad (vigilando la temperatura). Con un elemento de fijación de la rueda dañado NO: la rueda puede salirse en marcha."},{"id":5532,"bg":"Разрешено ли е движението на състав от ППС, когато ремаркето е с неизправна спирачна уредба?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":3,"es":"¿Está permitida la circulación de un conjunto de vehículos cuando el remolque tiene el sistema de frenos averiado?","explain":"No: el conjunto no circula con los frenos del remolque averiados. El remolque sin frenos empuja al tractor en cada frenada y el conjunto se vuelve incontrolable, sobre todo en bajada."},{"id":5998,"bg":"Задължително изискване е превозваният товар да не закрива:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"сигналните устройства на автомобила","ok":true,"i":null,"es":"los dispositivos de señalización del automóvil"},{"t":"огледалата за виждане назад","ok":true,"i":null,"es":"los espejos retrovisores"},{"t":"осветлението вътре в автомобила","ok":false,"i":null,"es":"la iluminación interior del automóvil"},{"t":"приспособленията, с които е осигурен срещу падане","ok":false,"i":null,"es":"los dispositivos con los que está asegurado contra caídas"}],"f":3,"es":"Es un requisito obligatorio que la carga transportada no oculte: (2 correctas)","explain":"La carga no debe ocultar: los dispositivos de señalización (luces, intermitentes, placas) ni los retrovisores: lo que te deja ver y ser visto. La iluminación interior y los amarres de la propia carga no son objeto de esta norma."},{"id":5999,"bg":"В кой от посочените случаи безопасността на движението изисква превозваният товар да бъде задължително покрит?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато товарът отразява светлината и може да заслепи други участници в движението","ok":true,"i":null,"es":"cuando la carga refleja la luz y puede deslumbrar a otros usuarios de la vía"},{"t":"когато товарът може да бъде разпилян","ok":true,"i":null,"es":"cuando la carga puede esparcirse"},{"t":"когато вали дъжд или сняг","ok":false,"i":null,"es":"cuando llueve o nieva"},{"t":"когато товарът не е укрепен","ok":false,"i":null,"es":"cuando la carga no está sujeta"}],"f":3,"es":"¿En cuál de los casos indicados la seguridad del tráfico exige que la carga transportada esté obligatoriamente cubierta? (2 correctas)","explain":"La carga debe cubrirse cuando REFLEJA la luz (deslumbraría) y cuando puede ESPARCIRSE (arena, grava: convertiría la vía en una lluvia de proyectiles). La lluvia protege a la carga, no al tráfico, y la carga suelta no se cubre: se SUJETA."},{"id":6007,"bg":"По кой от изброените начини може да се обозначи товар, който излиза отпред на най-издадената част на превозното средство с повече от 1 м?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен флаг при движение през деня","ok":true,"i":null,"es":"con bandera ROJA de día"},{"t":"с бял светлоотразител при движение през нощта","ok":true,"i":null,"es":"con reflectante BLANCO de noche"},{"t":"с бяла светлина при движение през нощта","ok":true,"i":null,"es":"con luz BLANCA de noche"},{"t":"с червена светлина при движение през деня","ok":false,"i":null,"es":"con luz ROJA de día"}],"f":3,"es":"¿De cuál de las formas indicadas puede señalizarse la carga que sobresale más de 1 m por DELANTE de la parte más saliente del vehículo? (3 correctas)","explain":"Carga saliente por DELANTE (+1 m): bandera roja de día, y de noche reflectante blanco o luz blanca: el blanco es el color del frente. La 'luz roja de día' es doblemente falsa: color trasero y momento equivocado."},{"id":6010,"bg":"При движение през нощта по кой от изброените начини може да се обозначи товар, който излиза с повече от 1 м отзад на най-издадената част на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен светлоотразител","ok":true,"i":null,"es":"con reflectante ROJO"},{"t":"с червена светлина","ok":true,"i":null,"es":"con luz ROJA"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"},{"t":"с бяла светлина","ok":false,"i":null,"es":"con luz BLANCA"}],"f":3,"es":"De noche, ¿cómo puede señalizarse la carga que sobresale más de 1m por DETRÁS? (2 correctas)","explain":"Por DETRÁS (+1 m) de noche: reflectante ROJO o luz ROJA: el rojo es el color trasero. La bandera roja es la señal DIURNA y la luz blanca detrás diría 'frente': el par delante-blanco/detrás-rojo resuelve toda esta familia."},{"id":11643,"bg":"Намаляването на прозрачността на стъклата на задните странични врати на автомобил е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"разрешено, ако автомобилът има от двете страни огледала за виждане назад","ok":true,"i":null,"es":"permitido, si el automóvil tiene espejos retrovisores a ambos lados"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"}],"f":3,"es":"Reducir la transparencia de los cristales de las puertas laterales traseras de un automóvil está:","explain":"Oscurecer los cristales traseros laterales está permitido SI hay retrovisores exteriores a ambos lados: la visión trasera queda cubierta por los espejos. Ni prohibición absoluta ni permiso incondicional."},{"id":11735,"bg":"При превоз на товари допуска ли се масата на ППС да надвишава допустимата максимална маса, отразена в свидетелството за регистрация?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, при превоз в населено място","ok":false,"i":null,"es":"sí, en transportes dentro de poblado"},{"t":"да, при превоз на разстояние до 10 km","ok":false,"i":null,"es":"sí, en transportes de hasta 10 km de distancia"},{"t":"да, ако това превишение е до 25%","ok":false,"i":null,"es":"sí, si el exceso no supera el 25%"}],"f":3,"es":"Al transportar cargas, ¿se permite que la masa del vehículo supere la masa máxima autorizada que figura en el permiso de circulación?","explain":"No: la masa máxima autorizada del permiso de circulación es un techo absoluto: sin excepciones por distancia, por ciudad ni por porcentaje. El exceso de peso destroza frenos, neumáticos y puentes por igual en 1 km que en 100."},{"id":11736,"bg":"Кога водачът е длъжен да използва обезопасителния колан?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"винаги, независимо от това по какъв път се движи","ok":true,"i":null,"es":"siempre, independientemente de la vía por la que circule"},{"t":"само при движение по път извън населено място","ok":false,"i":null,"es":"solo al circular por una vía fuera de poblado"},{"t":"само при движение по път в населено място","ok":false,"i":null,"es":"solo al circular por una vía dentro de poblado"},{"t":"само при движение със скорост над 50 km/h","ok":false,"i":null,"es":"solo al circular a más de 50 km/h"}],"f":3,"es":"¿Cuándo está obligado el conductor a usar el cinturón de seguridad?","explain":"Siempre: el cinturón es obligatorio en cualquier vía y a cualquier velocidad. Los umbrales de las opciones falsas (solo fuera, solo dentro, +50 km/h) no existen: un impacto urbano a 50 ya es potencialmente mortal sin cinturón."},{"id":11853,"bg":"Превозването на дете под 12 години на предната седалка на лек автомобил е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"разрешено, при условие че за него е поставена допълнителна специална седалка","ok":true,"i":null,"es":"permitido, a condición de que se haya instalado un asiento especial adicional"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено, при условие че го държи възрастен човек","ok":false,"i":null,"es":"permitido, a condición de que lo sujete un adulto"},{"t":"разрешено, ако детето е с височина над 120 cm","ok":false,"i":null,"es":"permitido, si el niño mide más de 120 cm"}],"f":3,"es":"Transportar a un niño menor de 12 años en el asiento delantero de un turismo está:","explain":"Menor de 12 delante: permitido SOLO con asiento/sistema de retención infantil instalado. Los brazos de un adulto son una catapulta en un impacto, y la estatura no sustituye al sistema homologado en esta norma."},{"id":5466,"bg":"Извършва ли нарушение водач, който предоставя управлението на МПС на лице, намиращо се под въздействие на алкохол?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Comete infracción el conductor que cede la conducción del vehículo a una persona bajo los efectos del alcohol?","explain":"Sí: ceder el volante a alguien bajo los efectos del alcohol es infracción TUYA. Respondes de a quién entregas el vehículo, igual que si careciera de permiso."},{"id":5467,"bg":"Извършва ли нарушение водач, който извън населено място не сигнализира автомобил, принудително спрял на платното за движение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":false,"i":null,"es":"no"},{"t":"да","ok":true,"i":null,"es":"sí"}],"f":3,"es":"¿Comete infracción el conductor que, fuera de poblado, no señaliza un automóvil detenido forzosamente en la calzada?","explain":"Sí: fuera de poblado, el vehículo detenido forzosamente en la calzada DEBE señalizarse (triángulo, luces de emergencia). No hacerlo es infracción: el tráfico llega a 90 km/h y necesita el aviso."},{"id":5468,"bg":"Извършва ли нарушение водач, който не сигнализира по установения ред принудително спряло на платното за движение МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, освен ако в резултат на това е настъпило ПТП","ok":false,"i":null,"es":"no, salvo que como consecuencia se haya producido un accidente"},{"t":"да, но само ако с това е създадена опасност за движението","ok":false,"i":null,"es":"sí, pero solo si con ello se ha creado un peligro para el tráfico"},{"t":"да, във всички случаи, независимо от последиците","ok":true,"i":null,"es":"sí, en todos los casos, independientemente de las consecuencias"}],"f":3,"es":"¿Comete infracción el conductor que no señaliza según el procedimiento establecido un vehículo detenido forzosamente en la calzada?","explain":"Sí, en todos los casos: no señalizar el vehículo detenido forzosamente es infracción por sí misma, haya o no consecuencias. La norma sanciona el riesgo creado, no espera al accidente."},{"id":5476,"bg":"Водач, който не носи със себе си необходимите документи, се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с глоба","ok":true,"i":null,"es":"con multa"},{"t":"с проверочен изпит","ok":false,"i":null,"es":"con un examen de verificación"},{"t":"с лишаване от право да управлява МПС","ok":false,"i":null,"es":"con la privación del derecho a conducir"}],"f":3,"es":"El conductor que no lleva consigo los documentos necesarios se sanciona:","explain":"Con multa: no llevar los documentos es una infracción documental leve: sanción económica. Ni examen ni privación del permiso: esas medidas son para infracciones de conducta o aptitud."},{"id":5496,"bg":"Контролните органи преместват паркирано пътно превозно средство без знанието на неговия собственик, когато превозното средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"прави невъзможно преминаването на другите участници в движението","ok":true,"i":null,"es":"hace imposible el paso de los demás usuarios de la vía"},{"t":"създава опасност за другите участници в движението","ok":true,"i":null,"es":"crea peligro para los demás usuarios de la vía"},{"t":"е без табели с регистрационен номер, поставени на определените за това места","ok":true,"i":null,"es":"no lleva las placas de matrícula colocadas en los lugares previstos"},{"t":"винаги, когато е паркирано в нарушение на правилата за движение","ok":false,"i":null,"es":"siempre que esté estacionado infringiendo las normas de circulación"}],"f":3,"es":"Las autoridades de control retiran un vehículo estacionado sin conocimiento de su propietario cuando el vehículo: (3 correctas)","explain":"Retiran el vehículo estacionado sin conocimiento del propietario cuando: imposibilita el paso, crea peligro o no lleva las placas en su sitio. 'Siempre que infrinja' es falso: la infracción simple se multa, la retirada exige esos supuestos graves."},{"id":5503,"bg":"Водач, на когото са отнети всички контролни точки:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"губи правоспособността си за управление на МПС","ok":true,"i":null,"es":"pierde su habilitación para conducir vehículos de motor"},{"t":"е задължен да върне свидетелството си за управление в МВР","ok":true,"i":null,"es":"está obligado a devolver su permiso de conducción al MVR (Ministerio del Interior)"},{"t":"може да задържи свидетелството си, ако веднага се яви на изпит","ok":false,"i":null,"es":"puede conservar su permiso si se presenta inmediatamente a examen"},{"t":"е задължен само да уведоми контролните органи на МВР","ok":false,"i":null,"es":"solo está obligado a avisar a las autoridades de control del MVR"}],"f":3,"es":"El conductor al que se le han retirado todos los puntos de control: (2 correctas)","explain":"Sin puntos de control: pierdes la habilitación para conducir y debes DEVOLVER el permiso al MVR. No hay 'examen exprés salvador' ni basta con avisar: se vuelve a empezar el proceso de obtención."},{"id":11385,"bg":"При административни нарушения, установени в момента на извършването им, се съставя акт вместо фиш, когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"водачът не е съгласен, че е извършил нарушението посочено от контролния орган","ok":true,"i":null,"es":"el conductor no está de acuerdo con haber cometido la infracción indicada por el agente"},{"t":"водачът не е съгласен с размера на наложената му глоба","ok":true,"i":null,"es":"el conductor no está de acuerdo con el importe de la multa impuesta"},{"t":"водачът отказва да подпише фиша","ok":true,"i":null,"es":"el conductor se niega a firmar el boletín"},{"t":"винаги, когато размерът на наложената му глоба е над 20 лв.","ok":false,"i":null,"es":"siempre que el importe de la multa impuesta supere los 20 leva"}],"f":3,"es":"En infracciones administrativas detectadas en el momento de cometerse, se levanta acta en lugar de boletín cuando: (3 correctas)","explain":"Se levanta acta (en vez de boletín) cuando el conductor: niega la infracción, discute el importe o se niega a firmar: cualquier desacuerdo activa el procedimiento formal con derecho a defensa. El umbral de '20 leva' no existe."},{"id":11391,"bg":"Извършва ли нарушение водач, който управлява МПС, на което върху регистрационния номер са поставени някакви материали или вещества?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Comete infracción el conductor que conduce un vehículo con materiales o sustancias colocados sobre la matrícula?","explain":"Sí: llevar materiales o sustancias sobre la matrícula (spray, plástico, barro deliberado) es infracción: la placa debe ser legible siempre, también para las cámaras."},{"id":11646,"bg":"Когато пътник в лек автомобил не изпълнява задължението за използване на предпазен колан, наказание се налага:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"на пътника без колан и на водача на автомобила","ok":true,"i":null,"es":"el pasajero sin cinturón Y el conductor"},{"t":"само на пътника без колан","ok":false,"i":null,"es":"solo el pasajero"},{"t":"само на водача на автомобила","ok":false,"i":null,"es":"solo el conductor"}],"f":3,"es":"Cuando un pasajero en turismo no lleva cinturón, la sanción recae sobre:","explain":"Pagan AMBOS: el pasajero sin cinturón (su infracción) y el conductor (responsable de que todos lo lleven). La doble sanción refleja la doble responsabilidad a bordo."},{"id":11690,"bg":"Контролните органи прекратяват регистрацията на пътно превозно средство на собственик, който като водач на моторното превозно средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"откаже да му бъде извършена проверка с техническо средство за установяване употребата на алкохол","ok":true,"i":null,"es":"se niegue al control con dispositivo técnico para detectar el consumo de alcohol"},{"t":"не изпълни предписанието за медицинско изследване за употреба на наркотични вещества","ok":true,"i":null,"es":"no cumpla la orden de someterse a un examen médico de consumo de drogas"},{"t":"превиши максимално разрешената скорост в населено място над 50 km/h","ok":false,"i":null,"es":"supere la velocidad máxima permitida en poblado en más de 50 km/h"},{"t":"участва в нерегламентирани състезания по пътищата, отворени за обществено ползване","ok":false,"i":null,"es":"participe en carreras ilegales en vías abiertas al uso público"}],"f":3,"es":"Las autoridades de control dan de baja la matriculación del vehículo del propietario que, como conductor del vehículo de motor: (2 correctas)","explain":"Baja de matriculación al propietario-conductor que: se niega al control de alcoholemia o incumple la orden de examen de drogas: las negativas se castigan como positivos, hasta el vehículo. El exceso de velocidad y las carreras tienen otras sanciones (durísimas, pero no esta)."},{"id":11738,"bg":"Водач, който превиши разрешената максимална скорост за движение извън населено място с над 50 km/h, се наказва с лишаване от право да управлява МПС:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато нарушението е системно","ok":true,"i":null,"es":"cuando la infracción es sistemática (reiterada)"},{"t":"във всички случаи","ok":false,"i":null,"es":"en todos los casos"}],"f":3,"es":"El conductor que supere la velocidad máxima permitida fuera de poblado en más de 50 km/h se sanciona con la privación del derecho a conducir:","explain":"Fuera de poblado, superar en más de 50 km/h: la privación del permiso llega cuando la infracción es SISTEMÁTICA (reiterada). Compara con el caso urbano, donde la privación es directa: la ciudad se protege más."},{"id":5302,"bg":"Водачите от коя възрастова група попадат най-често в пътнотранспортни произшествия?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"от 18 до 24 години","ok":true,"i":null,"es":"de 18 a 24 años"},{"t":"от 24 до 36 години","ok":false,"i":null,"es":"de 24 a 36 años"},{"t":"от 36 до 45 години","ok":false,"i":null,"es":"de 36 a 45 años"},{"t":"от 56 до 65 години","ok":false,"i":null,"es":"de 56 a 65 años"}],"f":3,"es":"¿Qué grupo de edad tiene mayor tasa de accidentes de tráfico?","explain":"De 18 a 24 años: los conductores más jóvenes concentran la mayor tasa de accidentes: poca experiencia, más asunción de riesgos. Es el dato estadístico que fundamenta las restricciones a noveles."},{"id":5310,"bg":"Данните от статистиката показват, че най-тежки (с най-много пострадали хора) са пътнотранспортни произшествия които настъпват:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"през деня","ok":false,"i":null,"es":"durante el día"},{"t":"при сумрак и тъмнина","ok":true,"i":null,"es":"al anochecer y de noche"},{"t":"на изкуствено осветление","ok":false,"i":null,"es":"con iluminación artificial"}],"f":3,"es":"Los datos estadísticos muestran que los accidentes más graves (con más heridos) son los que ocurren:","explain":"Al anochecer y de noche: menos visibilidad, más fatiga y alcohol: los accidentes nocturnos son MÁS GRAVES aunque haya menos tráfico. De día hay más accidentes en número; de noche, más severidad."},{"id":5311,"bg":"В случай на произшествие, правилно е поведението на водача, когато той:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"запазва спокойствие","ok":true,"i":null,"es":"mantener la calma"},{"t":"не изпада в паника","ok":true,"i":null,"es":"no dejarse llevar por el pánico"},{"t":"не предприема нищо до идването на помощните екипи","ok":false,"i":null,"es":"no hacer nada hasta la llegada de los equipos de socorro"},{"t":"се справя с възникналите проблеми винаги сам","ok":false,"i":null,"es":"resolver los problemas siempre solo"}],"f":3,"es":"En caso de accidente, el comportamiento del conductor es correcto cuando: (2 correctas)","explain":"Ante un accidente: calma y sin pánico: es lo que permite actuar bien. 'No hacer nada hasta que lleguen los equipos' abandona a los heridos, y 'resolverlo siempre solo' rechaza la ayuda disponible: ambos extremos son incorrectos."},{"id":5344,"bg":"Разрешено ли е отстраняването на неизправности по превозно средство, участвало в ПТП преди пристигането на представител на МВР?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":3,"es":"¿Está permitido reparar averías de un vehículo implicado en un accidente antes de la llegada de un representante del MVR?","explain":"No: las averías y daños del vehículo implicado no se reparan antes de que llegue el representante del MVR: alterarías las evidencias que documentan cómo ocurrió el accidente."},{"id":11425,"bg":"Кои от изброените действия трябва да се предприемат при пристигане на мястото на ПТП, ако при произшествието има пострадали хора?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да се осигури безопасността на участниците в движението","ok":true,"i":null,"es":"garantizar la seguridad de los usuarios de la vía"},{"t":"да се окаже помощ на пострадалите","ok":true,"i":null,"es":"prestar ayuda a los heridos"},{"t":"да уведоми органите на МВР или администрацията на общината, на чиято територия е станало","ok":true,"i":null,"es":"avisar a la policía (MVR) o a la administración del municipio en cuyo territorio ha ocurrido"},{"t":"да запише данните на участниците в произшествието","ok":false,"i":null,"es":"anotar los datos de los implicados en el accidente"}],"f":3,"es":"¿Cuáles de las acciones indicadas deben emprenderse al llegar al lugar de un accidente, si hay personas heridas? (3 correctas)","explain":"Con heridos: asegurar la vía, ayudar a los heridos y avisar a la policía o al municipio. Anotar los datos de los implicados es gestión del seguro entre las partes: no es tu deber como tercero que llega."},{"id":6047,"bg":"Когато потегля и се включва в движението от лявата част на пътя и подава сигнал с ръка, водачът на двуколесното ППС сигнализира чрез:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27847.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27848.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27849.png","es":""}],"f":3,"es":"Cuando arranca e se incorpora al tráfico desde la parte izquierda de la carretera y da señal con el brazo, el conductor del vehículo de dos ruedas señaliza con:","explain":"LA PRIMERA: BRAZO DERECHO EXTENDIDO EN HORIZONTAL. Una sola correcta.\n\nQUÉ VES. Tres fotos de un motorista visto desde atrás: 1) brazo DERECHO extendido en horizontal; 2) brazo levantado hacia arriba; 3) brazo IZQUIERDO extendido en horizontal.\n\nSALIR DESDE EL LADO IZQUIERDO DE LA VÍA ES DESPLAZARSE A LA DERECHA. El conductor de dos ruedas puede usar el brazo de cada lado: extiende el derecho.\n\n«EL BRAZO LEVANTADO» indica que va a frenar o detenerse.\n\n«EL BRAZO IZQUIERDO» indica desplazamiento a la IZQUIERDA.\n\nCLAVE: compárala con la 6046 (desde el borde derecho = brazo izquierdo)."},{"id":5237,"bg":"Кой знак означава “Край на пътя с предимство”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19965.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19966.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19967.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19968.png","es":""}],"f":3,"es":"¿Qué señal significa 'Fin de vía con prioridad'?","explain":"LA PRIMERA: EL ROMBO AMARILLO TACHADO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) ROMBO amarillo tachado con rayas negras; 2) cuadrado azul con una flecha ROJA hacia abajo y una blanca hacia arriba; 3) círculo blanco con rayas negras oblicuas; 4) círculo con borde rojo con una flecha NEGRA hacia abajo y una ROJA hacia arriba.\n\nEL ROMBO TACHADO pone fin a la vía con prioridad: a partir de ahí vuelve a regir la regla general (normalmente, la de la derecha).\n\n«EL CÍRCULO CON RAYAS NEGRAS» es el fin de todas las PROHIBICIONES, no de la prioridad.\n\n«EL CUADRADO AZUL» te da preferencia frente a los que vienen de frente en un paso estrecho. «EL CÍRCULO ROJO CON FLECHAS» es lo contrario: cedes tú a los de frente.\n\nCLAVE: el fin de una señal se marca tachando esa misma señal. Ver Leyes → «Vía con prioridad»."},{"id":5967,"bg":"Кой от пътните знаци забранява навлизането след него на ППС в двете посоки?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/47099.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334703.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/47101.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/47102.png","es":""}],"f":3,"es":"¿Cuál de las señales prohíbe la entrada de vehículos en ambos sentidos?","explain":"LA PRIMERA: CÍRCULO BLANCO VACÍO CON BORDE ROJO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) círculo BLANCO sin dibujo; 2) círculo ROJO con barra blanca; 3) círculo con la silueta de un coche; 4) círculo con «МИТНИЦА / DOUANE» y una barra.\n\nLA BARRA BLANCA Y EL CÍRCULO VACÍO, QUE SE CONFUNDEN:\n• círculo ROJO con BARRA BLANCA = prohibida la entrada en ESE sentido (dirección prohibida);\n• círculo BLANCO VACÍO con borde rojo = prohibida la circulación en LOS DOS sentidos.\n\n«EL COCHE» prohíbe solo a los vehículos de motor (salvo motos sin sidecar y ciclomotores). «LA ADUANA» prohíbe pasar sin detenerse.\n\nCLAVE: vacío = nadie, en ningún sentido. Compárala con la 5971 y la 12077. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5242,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21012.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21149.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334673.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21015.png","es":""}],"f":3,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa? (2 correctas)","explain":"LA PRIMERA Y LA CUARTA: LOS TRIÁNGULOS CON UNA LÍNEA QUE SE DOBLA. Dos correctas.\n\nQUÉ VES. Cuatro triángulos: 1) línea que sube y se dobla a la IZQUIERDA; 2) signo de exclamación; 3) trazo grueso con un trazo fino a la derecha; 4) línea que sube y se dobla a la DERECHA.\n\nLA LÍNEA QUE SE DOBLA ES LA CARRETERA: curva peligrosa a la izquierda (1) y a la derecha (4).\n\n«LA EXCLAMACIÓN» es «otros peligros». «EL TRAZO GRUESO CON FINO» es un cruce con una vía sin prioridad: el trazo fino no es una curva, es otra calle.\n\nCLAVE: compárala con la 5243 y la 5246. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5286,"bg":"Кой от пътните знаци предупреждава за приближаване към железопътен прелез без бариери?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334679.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27348.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27349.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21411.png","es":""}],"f":3,"es":"¿Cuál de las señales advierte de la proximidad de un paso a nivel sin barreras?","explain":"LA PRIMERA: TRIÁNGULO CON UNA LOCOMOTORA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) triángulo con una LOCOMOTORA; 2) triángulo con una VALLA (barrera); 3) cruz de San Andrés DOBLE; 4) signo de exclamación.\n\nLOCOMOTORA = PASO A NIVEL SIN BARRERAS. Como nada te detiene, la señal te enseña el tren.\n\n«LA VALLA» es el paso a nivel CON barreras.\n\n«LA CRUZ DOBLE» se pone en el mismo paso a nivel sin barreras cuando hay dos o más vías; no es un aviso de proximidad.\n\nCLAVE: compárala con la 5289. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6045,"bg":"Когато се подава с ръка, сигналът за отклоняване вляво е:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27757.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27758.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27759.png","es":""}],"f":3,"es":"Cuando se da con el brazo, la señal para desviarse a la izquierda es:","explain":"LA PRIMERA: BRAZO IZQUIERDO EXTENDIDO EN HORIZONTAL. Una sola correcta.\n\nQUÉ VES. Tres fotos de un coche visto desde atrás con el conductor sacando el brazo IZQUIERDO: 1) brazo extendido en horizontal; 2) y 3) brazo levantado (con el antebrazo hacia arriba).\n\nBRAZO EN HORIZONTAL = ME DESPLAZO A LA IZQUIERDA.\n\nLOS BRAZOS LEVANTADOS significan otra cosa: el antebrazo doblado hacia arriba indica desplazamiento a la DERECHA, y el brazo recto hacia arriba, que va a frenar.\n\nCLAVE: compárala con la 6044 y la 6043 (las otras dos señales de brazo del coche)."},{"id":5964,"bg":"Кой от пътните знаци забранява навлизането на пътни превозни средства срещу него?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334703.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46872.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46285.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46874.png","es":""}],"f":3,"es":"¿Cuál de las señales prohíbe la entrada de vehículos en su sentido?","explain":"LA PRIMERA: CÍRCULO ROJO CON BARRA BLANCA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) círculo ROJO con barra BLANCA; 2) cuadrado azul con una T con el extremo rojo (calle sin salida); 3) círculo con flecha NEGRA hacia abajo y ROJA hacia arriba (cede a los que vienen de frente); 4) círculo con dos coches, uno rojo (prohibido adelantar).\n\nLA BARRA BLANCA SOBRE ROJO es la dirección prohibida: no entras en ese sentido.\n\n«LA T AZUL» es el cebo: avisa de que la calle no tiene salida, pero puedes entrar.\n\nCLAVE: compárala con la 5963. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":9848,"bg":"Кой от пътните знаци сигнализира за допълнителна пътна лента за бавнодвижещи се ППС?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043915.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043916.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043917.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043918.png","es":""}],"f":3,"es":"¿Cuál de las señales señaliza un carril adicional para vehículos lentos?","explain":"LA PRIMERA: CARRILES CON UNO NUEVO A LA DERECHA Y UN «40». Una sola correcta.\n\nQUÉ VES. Cuatro cuadrados azules: 1) carriles en los que se abre uno nuevo a la DERECHA, con un círculo «40» en el carril de al lado; 2) carriles que se separan en dos direcciones; 3) tres flechas, la tercera nace de la segunda (comienza un carril); 4) tres carriles con una señal de prohibido camiones en uno de ellos.\n\nEL CARRIL QUE SE ABRE + EL NÚMERO = CARRIL PARA LENTOS: el que no pueda mantener 40 km/h pasa al nuevo carril de la derecha.\n\n«LA TERCERA» es el cebo fino: un carril que empieza, sin decir para quién.\n\n«LA CUARTA» indica una prohibición por carriles, no un carril para lentos.\n\nCLAVE: compárala con la 11683. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5255,"bg":"Кой от пътните знаци предупреждава за опасност от хлъзгане?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21410.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21411.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334665.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","es":""}],"f":3,"es":"¿Cuál de las señales advierte de peligro de deslizamiento?","explain":"LA PRIMERA: TRIÁNGULO CON UN COCHE DERRAPANDO. Una sola correcta.\n\nQUÉ VES. Cuatro triángulos: 1) coche con huellas en ZIGZAG detrás; 2) signo de exclamación; 3) línea en zigzag (curvas sucesivas, la primera a la izquierda); 4) coche INCLINADO sobre el borde de la calzada.\n\nLAS HUELLAS EN ZIGZAG son el derrape: calzada deslizante.\n\n«EL COCHE INCLINADO» es el cebo fino: es el arcén peligroso (compárala con la 5194).\n\n«LA LÍNEA EN ZIGZAG» sin coche son curvas, no deslizamiento.\n\nCLAVE: coche derrapando = deslizante; coche inclinado = arcén. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11819,"bg":"С кой от опознавателните знаци се обозначават товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334741.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23095.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334744.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334743.png","es":""}],"f":3,"es":"¿Con cuál de los signos distintivos se identifican los camiones con masa máxima admisible superior a 3500 kg y longitud superior a 7 metros? (2 correctas)","explain":"Placa reflectante trasera obligatoria para camiones largos y pesados."},{"id":5291,"bg":"Кой от пътните знаци указва, че железопътният прелез е с два или повече коловоза?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334681.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27525.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334680.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27527.png","es":""}],"f":3,"es":"¿Cuál de las señales indica que el paso a nivel tiene dos o más vías?","explain":"LA PRIMERA: CRUZ DE SAN ANDRÉS DOBLE. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) dos cruces rojas y blancas, una encima de otra; 2) poste blanco con DOS franjas rojas oblicuas; 3) triángulo con una valla (barrera); 4) cruz de San Andrés SIMPLE.\n\nLA CRUZ DOBLE indica que el paso a nivel sin barreras tiene DOS O MÁS vías.\n\n«LA CRUZ SIMPLE» es el cebo directo: una sola vía (compárala con la 5293).\n\n«EL POSTE CON DOS FRANJAS» es la baliza que indica que faltan unos 160 m hasta el paso a nivel.\n\nCLAVE: una cruz = una vía; cruz doble = varias vías. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5263,"bg":"Кой от пътните знаци предупреждава за кръстовище с път без предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"23811"},{"t":"","ok":false,"es":"","i":"24642"},{"t":"","ok":true,"es":"","i":"23809"},{"t":"","ok":false,"es":"","i":"21411"}],"f":3,"es":"¿Cuál de las señales advierte de intersección con vía sin prioridad? (2 correctas)","explain":"LA PRIMERA Y LA TERCERA: LOS TRIÁNGULOS CON TRAZO GRUESO Y TRAZO FINO. Dos correctas.\n\nQUÉ VES. Cuatro triángulos: 1) trazo grueso con trazo fino a la IZQUIERDA; 2) un semáforo; 3) trazo grueso con trazos finos a AMBOS lados; 4) signo de exclamación.\n\nCÓMO SE LEEN LAS SEÑALES DE CRUCE (triángulos con trazos):\n• trazo GRUESO = tu vía, la que tiene prioridad;\n• trazo FINO = la vía sin prioridad que llega al cruce (por un lado, por el otro o por ambos);\n• una X (dos trazos iguales cruzados) = cruce de vías iguales, sin prioridad para nadie.\n\nLAS DOS CON TRAZO FINO avisan de un cruce con una vía sin prioridad (por la izquierda o por ambos lados).\n\n«EL SEMÁFORO» avisa de un cruce regulado por semáforo. «LA EXCLAMACIÓN» es «otros peligros».\n\nCLAVE: compárala con la 5260. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5280,"bg":"Кой от пътните знаци предупреждава за приближаване към пешеходната пътека?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334677.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27189.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27190.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27191.png","es":""}],"f":3,"es":"¿Cuál de las señales advierte de la proximidad de un paso de peatones?","explain":"LA PRIMERA: TRIÁNGULO CON UN PEATÓN SOBRE EL PASO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) TRIÁNGULO con un peatón sobre las franjas de un paso; 2) CUADRADO AZUL con un triángulo blanco y un peatón sobre el paso; 3) cuadrado azul con dos peatones (zona peatonal); 4) círculo azul con un peatón (vía solo para peatones).\n\nEL TRIÁNGULO AVISA DE QUE TE ACERCAS al paso de peatones.\n\n«EL CUADRADO AZUL CON EL PASO» es el cebo fino: marca el lugar EXACTO del paso, no su proximidad (compárala con la 5283).\n\n«ZONA PEATONAL» y «VÍA SOLO PARA PEATONES» no son pasos.\n\nCLAVE: triangular = se acerca; cuadrada azul = aquí está. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5517,"bg":"С кой от опознавателните знаци се обозначава ремаркетата?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23516.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23455.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23518.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23519.png","es":""}],"f":3,"es":"¿Con cuál de los signos distintivos se identifican los remolques? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA: LAS PLACAS AMARILLAS CON BORDE ROJO. Dos correctas.\n\nQUÉ VES. Cuatro traseras: 1) dos placas VERTICALES amarillas con borde rojo; 2) dos placas HORIZONTALES amarillas con borde rojo; 3) dos placas verticales de FRANJAS diagonales; 4) una placa horizontal de FRANJAS diagonales.\n\nLAS PLACAS TRASERAS QUE SE CONFUNDEN:\n• AMARILLAS CON BORDE ROJO (lisas) = REMOLQUES y SEMIRREMOLQUES, de cualquier masa y número de ejes.\n• FRANJAS DIAGONALES ROJAS Y AMARILLAS = CAMIONES de más de 3,5 t y más de 7 m.\n\nLAS DOS PRIMERAS son de remolque (vertical u horizontal da igual). LAS DE FRANJAS son de camión.\n\nCLAVE: el color manda, no la colocación. Compárala con la 5518."},{"id":5382,"bg":"С кой от знаците се обозначава автомобил, който превозва организирана група деца?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22455.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22456.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22457.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22458.png","es":""}],"f":3,"es":"¿Con cuál de los signos se identifica un automóvil que transporta un grupo organizado de niños?","explain":"LA PRIMERA: CUADRADO NARANJA CON DOS NIÑOS. Una sola correcta.\n\nQUÉ VES. Cuatro distintivos: 1) cuadrado NARANJA con dos niños caminando; 2) TRIÁNGULO con dos niños; 3) paleta «STOP / ДЕЦА»; 4) triángulo con un signo de exclamación.\n\nEL CUADRADO NARANJA LO LLEVA EL VEHÍCULO que transporta a un grupo organizado de niños.\n\n«EL TRIÁNGULO CON NIÑOS» es el cebo fino: es una señal de la carretera que avisa de un lugar con niños, no la lleva ningún vehículo.\n\n«LA PALETA STOP» la usa la persona que ayuda a cruzar a los niños (compárala con la 6065).\n\nCLAVE: compárala con la 5381 y la 5383. Ver Leyes → «Niños en la vía»."},{"id":5272,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"334675"},{"t":"","ok":true,"es":"","i":"334676"},{"t":"","ok":true,"es":"","i":"334673"},{"t":"","ok":false,"es":"","i":"21411"}],"f":3,"es":"¿Cuál de las señales advierte de la proximidad de una intersección? (3 correctas)","explain":"LA PRIMERA, LA SEGUNDA Y LA TERCERA: LA X, LA ROTONDA Y EL TRAZO GRUESO CON FINO. Tres correctas.\n\nQUÉ VES. Cuatro triángulos: 1) una X; 2) tres flechas en círculo; 3) trazo grueso con trazo fino a la derecha; 4) signo de exclamación.\n\nLAS TRES PRIMERAS SON CRUCES: de vías iguales (X), con circulación giratoria (rotonda) y con una vía sin prioridad (trazo fino).\n\n«LA EXCLAMACIÓN» es el cebo: avisa de «otros peligros», sin decir cuál.\n\nCLAVE: compárala con la 5271. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5446,"bg":"Налягането на въздуха в автомобилните гуми се измерва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при “загрята” от движението гума","ok":false,"i":null,"es":"con el neumático \"caliente\" por la marcha"},{"t":"при студена гума","ok":true,"i":null,"es":"con el neumático frío"},{"t":"независимо от температурното състояние на гумата","ok":false,"i":null,"es":"independientemente de la temperatura del neumático"}],"f":2,"es":"La presión de aire de los neumáticos se mide:","explain":"Con el neumático FRÍO: la marcha calienta el aire y sube la presión (lectura falsa alta). Los valores del fabricante están dados en frío: medir en caliente te dejaría con presión real baja."},{"id":6160,"bg":"Как работи антиблокиращата спирачна система (ABS)?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при аварийно/рязко спиране не позволява на колелата да блокират","ok":true,"i":null,"es":"en una frenada de emergencia/brusca no permite que las ruedas se bloqueen"},{"t":"усилва налягането в привода (хидравличен или пневматичен) към спирачните механизми","ok":false,"i":null,"es":"amplifica la presión en la transmisión (hidráulica o neumática) hacia los mecanismos de freno"},{"t":"усилва натиска на педала на спирачката","ok":false,"i":null,"es":"amplifica la fuerza sobre el pedal de freno"}],"f":2,"es":"¿Cómo funciona el sistema antibloqueo de frenos (ABS)?","explain":"El ABS impide que las ruedas se BLOQUEEN en la frenada brusca: modula la presión muchas veces por segundo. No amplifica la presión ni la fuerza del pedal (eso es el servofreno): regula, no potencia."},{"id":6161,"bg":"Антиблокиращата спирачна система (ABS) не позволява на колелата да блокират при рязко спиране.","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":2,"es":"El sistema antibloqueo de frenos (ABS) no permite que las ruedas se bloqueen en una frenada brusca.","explain":"Correcto: esa es exactamente la función del ABS: sin bloqueo, el neumático mantiene adherencia y el volante sigue dirigiendo durante la frenada de emergencia."},{"id":6164,"bg":"Ако при работещ двигател индикаторът на провобуксуващата система (ASR) свети постоянно, това означава че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/30115.png","v":null,"a":[{"t":"има технически проблем в системата","ok":true,"i":null,"es":"hay un problema técnico en el sistema"},{"t":"спирачните накладки са износени","ok":false,"i":null,"es":"las pastillas de freno están desgastadas"},{"t":"системата е готова за използване","ok":false,"i":null,"es":"el sistema está listo para su uso"}],"f":2,"es":"Si con el motor en marcha el indicador del sistema antipatinaje (ASR) está encendido permanentemente, significa que:","explain":"HAY UN PROBLEMA TÉCNICO EN EL SISTEMA. Una sola correcta.\n\nQUÉ VES. Un testigo AMARILLO con «ASR» dentro de un círculo entre paréntesis: control de tracción (antipatinaje).\n\nENCENDIDO DE FORMA FIJA con el motor en marcha = el sistema tiene una avería (o está desconectado).\n\n«PASTILLAS GASTADAS» tiene otro testigo. «LISTO PARA USAR» sería que se apague tras arrancar.\n\nCLAVE: compárala con la 11655 (el ABS)."},{"id":5439,"bg":"Трябва ли водачът да следи нивото на маслото в картера на двигателя.","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"¿Debe el conductor vigilar el nivel de aceite del cárter del motor?","explain":"Sí: vigilar el nivel de aceite del cárter es obligación básica del conductor: sin lubricación el motor se gripa en minutos. Se comprueba con la varilla, en frío y en llano."},{"id":5438,"bg":"При хидравлична охладителна уредба като охлаждаща течност може да се използва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"вода","ok":true,"i":null,"es":"agua"},{"t":"нискозамръзваща течност /антифриз/","ok":true,"i":null,"es":"líquido anticongelante"},{"t":"смес от вода и спирачна течност","ok":false,"i":null,"es":"mezcla de agua y líquido de frenos"},{"t":"разредена със спирт нискозамръзваща течност /антифриз/","ok":false,"i":null,"es":"anticongelante diluido con alcohol"}],"f":2,"es":"En sistemas de refrigeración hidráulica puede usarse como líquido: (2 correctas)","explain":"En el sistema de refrigeración: agua o líquido anticongelante (lo correcto es anticongelante; el agua vale como solución de emergencia y en verano). Jamás líquido de frenos ni anticongelante 'rebajado' con alcohol: químicamente destructivos."},{"id":6101,"bg":"За предпазване от нараняване от въртящи се части проверки на нивото на течностите в автомобила се извършват:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при неработещ двигател","ok":true,"i":null,"es":"con el motor apagado"},{"t":"при работещ двигател, но изключени предавки","ok":false,"i":null,"es":"con el motor en marcha, pero sin marcha engranada"},{"t":"при работещ двигател и неработеща вентилаторна перка","ok":false,"i":null,"es":"con el motor en marcha y el ventilador sin funcionar"}],"f":2,"es":"Para protegerse de lesiones por piezas giratorias, las comprobaciones del nivel de los líquidos del automóvil se realizan:","explain":"Con el motor APAGADO: el ventilador puede arrancar solo incluso con el motor parado en caliente, y las correas y poleas giratorias atrapan manos y ropa. Motor apagado y, mejor, frío: es la regla de oro del vano motor."},{"id":6155,"bg":"По какъв начин водачите на МПС могат да допринесат за намаляване на вредните емисии отделяни от автомобилите?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"чрез икономично управление","ok":true,"i":null,"es":"mediante una conducción económica"},{"t":"чрез поддържане на автомобила чист","ok":false,"i":null,"es":"manteniendo el automóvil limpio"},{"t":"водачите не могат да влияят на количеството на вредните емисии","ok":false,"i":null,"es":"los conductores no pueden influir en la cantidad de emisiones contaminantes"},{"t":"чрез движение с висока скорост","ok":false,"i":null,"es":"circulando a alta velocidad"}],"f":2,"es":"¿De qué forma pueden los conductores contribuir a reducir las emisiones contaminantes de los automóviles?","explain":"Conducción ECONÓMICA: anticipar, mantener velocidad uniforme, no acelerar ni frenar bruscamente: menos combustible, menos emisiones. La limpieza no cambia los gases y la alta velocidad los dispara."},{"id":5145,"bg":"Участници в движението са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"водачите","ok":true,"i":null,"es":"los conductores"},{"t":"пешеходците","ok":true,"i":null,"es":"los peatones"},{"t":"пътните превозни средства","ok":false,"i":null,"es":"los vehículos"},{"t":"моторните превозни средства","ok":false,"i":null,"es":"los vehículos de motor"}],"f":2,"es":"Son participantes en el tráfico: (2 correctas)","explain":"Participantes: los conductores y los peatones: personas. Los vehículos y los vehículos de motor son objetos: el error conceptual que esta serie machaca una y otra vez."},{"id":5147,"bg":"Участници в движението са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пешеходците","ok":true,"i":null,"es":"los peatones"},{"t":"лицата, работещи на пътя","ok":true,"i":null,"es":"las personas que trabajan en la vía"},{"t":"пътните превозни средства","ok":false,"i":null,"es":"los vehículos"},{"t":"самоходните машини","ok":false,"i":null,"es":"las máquinas autopropulsadas"}],"f":2,"es":"Son participantes en el tráfico: (2 correctas)","explain":"Participantes: los peatones y las personas que trabajan en la vía (obreros, agentes): todas personas. Los vehículos y las máquinas autopropulsadas son cosas, no participantes."},{"id":5184,"bg":"Леки са автомобилите, предназначени за превоз на пътници с не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"8 места за сядане без мястото на водача","ok":true,"i":null,"es":"8 plazas sentadas sin contar al conductor"},{"t":"6 места за сядане без мястото на водача","ok":false,"i":null,"es":"6 plazas"},{"t":"10 места за сядане без мястото на водача","ok":false,"i":null,"es":"10 plazas"},{"t":"12 места за сядане без мястото на водача","ok":false,"i":null,"es":"12 plazas"}],"f":2,"es":"Son turismos los automóviles destinados al transporte de pasajeros con no más de:","explain":"Turismo: hasta 8 plazas sentadas SIN contar al conductor (8+1). Con 9 o más plazas de pasajeros el vehículo pasa a ser autobús (categoría D)."},{"id":5201,"bg":"Състав от пътни превозни средства са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"автомобил с ремарке","ok":true,"i":null,"es":"automóvil con remolque"},{"t":"автомобил с полуремарке","ok":true,"i":null,"es":"automóvil con semirremolque"},{"t":"автомобил, който тегли друг повреден автомобил","ok":true,"i":null,"es":"automóvil que remolca a otro automóvil averiado"},{"t":"автомобилите с допълнително монтирани съоръжения","ok":false,"i":null,"es":"los automóviles con equipos adicionales instalados"}],"f":2,"es":"Un tren de vehículos de carretera está formado por: (3 correctas)","explain":"Tren de carretera: automóvil con remolque, con semirremolque o remolcando a otro averiado: unidades unidas circulando como conjunto. Un coche con equipos adicionales instalados sigue siendo un solo vehículo."},{"id":5221,"bg":"Кои от изброените правила се прилагат при движение в населено място?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"ако няма други ограничения, се спазва ограничението на скоростта в населено място","ok":true,"i":null,"es":"si no hay otras restricciones, se respeta el límite de velocidad de poblado"},{"t":"допуска се паркиране на платното за движение","ok":true,"i":null,"es":"se permite estacionar en la calzada"},{"t":"няма ограничения за използване на звуков сигнал","ok":false,"i":null,"es":"no hay restricciones para el uso de la señal acústica"},{"t":"водачът не е длъжен да ползва обезопасителен колан","ok":false,"i":null,"es":"el conductor no está obligado a usar el cinturón de seguridad"}],"f":2,"es":"¿Cuáles de las normas se aplican al circular en población? (2 correctas)","explain":"En poblado: rige el límite urbano (50 salvo señal) y se permite estacionar en la calzada. El claxon SÍ está restringido (solo emergencia) y el cinturón SIEMPRE es obligatorio: las dos opciones permisivas son falsas."},{"id":5228,"bg":"Платното за движение включва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните ленти","ok":true,"i":null,"es":"los carriles"},{"t":"тротоарите","ok":false,"i":null,"es":"las aceras"},{"t":"пътните банкети","ok":false,"i":null,"es":"los arcenes"},{"t":"островите на платното за движение","ok":false,"i":null,"es":"las isletas de la calzada"}],"f":2,"es":"La calzada incluye:","explain":"La calzada incluye solo los CARRILES: es la parte destinada a la circulación de vehículos. Aceras, arcenes e isletas quedan fuera: pertenecen a la plataforma o al firme, no a la calzada."},{"id":5230,"bg":"&quot;Пътното платно&quot; включва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните банкети","ok":true,"i":null,"es":"los arcenes"},{"t":"отводнителните канавки","ok":false,"i":null,"es":"las cunetas de drenaje"},{"t":"платното за движение","ok":true,"i":null,"es":"la calzada"},{"t":"островите на платното за движение","ok":true,"i":null,"es":"las isletas de la calzada"}],"f":2,"es":"El 'firme' incluye: (3 correctas)","explain":"El firme incluye la calzada, los arcenes y las isletas: toda la superficie construida. Las cunetas de drenaje quedan fuera: son elementos de evacuación de agua, no superficie de circulación."},{"id":5241,"bg":"“Граница на платното за движение” е линията, очертана или не, с пътна маркировка, която отделя:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"платното за движение от другите конструктивни елементи на пътното платно","ok":true,"i":null,"es":"la calzada de los demás elementos constructivos de la plataforma vial"},{"t":"пътните платна едно от друго","ok":false,"i":null,"es":"las calzadas entre sí"},{"t":"пътните ленти една от друга","ok":false,"i":null,"es":"los carriles entre sí"}],"f":2,"es":"'Límite de calzada' es la línea que separa:","explain":"El límite de calzada separa la calzada de los DEMÁS elementos de la plataforma vial (arcenes, aceras). No separa calzadas entre sí (eso lo hace la mediana) ni carriles (eso lo hacen las líneas divisorias)."},{"id":5244,"bg":"Линията, с която се очертава “ВUS”-лентата, е граница на платното за движение.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20243.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":2,"es":"La línea que delimita el carril BUS es un límite de la calzada. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Calle urbana con un carril a la derecha marcado «BUS» y separado del resto por una línea continua AMARILLA.\n\nSEGÚN EL BANCO, LA LÍNEA QUE DELIMITA EL CARRIL BUS es un límite de la calzada para el resto del tráfico: los demás vehículos circulan por su lado y no la usan como si fuera un carril más.\n\n«INCORRECTO» es el cebo de quien la toma por una simple línea de separación de carriles, que se podría cruzar libremente.\n\nCLAVE: carril BUS = no es para ti; su línea marca hasta dónde llega tu calzada. Ver Leyes → «Carril: dónde debes circular»."},{"id":5247,"bg":"Разделителната ивица е надлъжна част от пътя, която:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20394.png","v":null,"a":[{"t":"разделя пътя на отделни платна за движение","ok":true,"i":null,"es":"separa la vía en CALZADAS separadas"},{"t":"разделя пътя на отделни ленти за движение","ok":false,"i":null,"es":"separa la vía en CARRILES"},{"t":"отделя платното за движение от другите елементи на пътя","ok":false,"i":null,"es":"separa la calzada de otros elementos de la vía"}],"f":2,"es":"La franja divisoria es la parte longitudinal de la vía que:","explain":"SEPARA LA VÍA EN CALZADAS SEPARADAS. Una sola correcta.\n\nQUÉ VES. Una AUTOPISTA (señal verde) con dos calzadas, una para cada sentido, separadas por una franja con hierba y una barrera metálica.\n\nLA FRANJA DIVISORIA (MEDIANA) divide la vía en DOS CALZADAS, una por sentido.\n\n«SEPARA EN CARRILES» es el cebo: los carriles se separan con líneas pintadas, dentro de la misma calzada.\n\n«SEPARA LA CALZADA DE OTROS ELEMENTOS» describe el arcén o la acera, no la mediana.\n\nCLAVE: mediana = entre calzadas; línea = entre carriles. Compárala con la 5409 (prohibido cruzar la mediana)."},{"id":5299,"bg":"Видимостта е намалена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"здрач","ok":true,"i":null,"es":"el crepúsculo"},{"t":"запрашеност","ok":true,"i":null,"es":"polvo en suspensión"},{"t":"задименост","ok":true,"i":null,"es":"humo (humareda)"},{"t":"препятствия, които пречат на видимостта","ok":false,"i":null,"es":"obstáculos que impiden la visibilidad"}],"f":2,"es":"La visibilidad esta reducida en: (3 correctas)","explain":"Visibilidad REDUCIDA: crepúsculo, polvo en suspensión, humo: condiciones del aire y la luz. Los obstáculos que tapan son visibilidad LIMITADA: el par de conceptos de siempre, esta vez preguntado desde el otro lado."},{"id":11866,"bg":"На водач с правоспособност за категория В е разрешено да управлява товарен автомобил, когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"допустимата максимална маса на автомобила не надвишава 3,5 t","ok":true,"i":null,"es":"la masa máxima autorizada no supera 3.5 t"},{"t":"товара на автомобила не надвишава 3,5 t","ok":false,"i":null,"es":"la masa con carga no supera 3.5 t"},{"t":"водачът има стаж над 5 години","ok":false,"i":null,"es":"el conductor tiene más de 5 años de experiencia"},{"t":"притежава правоспособност за категория Ткт","ok":false,"i":null,"es":"posee permiso categoría Tkt"}],"f":2,"es":"Al conductor con permiso categoría B le está permitido conducir un camión cuando:","explain":"El B permite camiones con masa máxima AUTORIZADA de hasta 3,5 t: el criterio es la cifra administrativa del permiso de circulación, no lo que pese cargado ese día. Ni la experiencia ni el permiso de tractor cambian la categoría exigida."},{"id":11606,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123580180.png","v":null,"a":[{"t":"опасен пътен банкет","ok":false,"i":null,"es":"arcén peligroso"},{"t":"опасност от хлъзгане","ok":false,"i":null,"es":"peligro de deslizamiento"},{"t":"настъпило пътнотранспортно произшествие","ok":true,"i":null,"es":"accidente de tráfico ocurrido"},{"t":"образувано задръстване","ok":false,"i":null,"es":"retención formada"}],"f":2,"es":"Esta señal advierte de:","explain":"ACCIDENTE DE TRÁFICO OCURRIDO. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con FONDO AMARILLO (temporal) y un COCHE VOLCADO.\n\nEL COCHE VOLCADO avisa de que más adelante ha habido un accidente: reduces y te preparas para encontrar vehículos parados o personas en la calzada.\n\n«ARCÉN PELIGROSO» es un coche inclinado sobre el borde. «DESLIZAMIENTO» es un coche derrapando. «RETENCIÓN» son varios coches en fila.\n\nCLAVE: compárala con la 11604 y la 11605 (las otras señales temporales amarillas). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5537,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"широчината му, включително товара, е 2,8 м","ok":true,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.8 m"},{"t":"височината му, включително товара, е 2,8 м","ok":false,"i":null,"es":"su ALTURA, incluyendo carga, es 2.8 m"},{"t":"дължината му, включително товара, е 12 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 12 m"}],"f":2,"es":"Un vehículo es 'fuera de gálibo' cuando:","explain":"Fuera de gálibo por ANCHURA: 2,8 m supera el límite de 2,55 m. La misma cifra en ALTURA (2,8 m) queda muy por debajo de los 4 m permitidos, y 12 m de longitud tampoco excede el límite: el par magnitud-límite es la clave."},{"id":5775,"bg":"При тази ситуация трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24454.png","v":null,"a":[{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да бъда внимателен към поведението на велосипедистите","ok":true,"i":null,"es":"estar atento al comportamiento de los ciclistas"},{"t":"при изпреварването да осигуря по-голяма странична дистанция","ok":true,"i":null,"es":"al adelantar, asegurar una mayor distancia lateral"},{"t":"да подам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"dar una señal acústica para llamar la atención de los ciclistas"}],"f":2,"es":"En esta situación debes: (3 correctas)","explain":"CIRCULAR LISTO PARA FRENAR, ESTAR ATENTO A LOS CICLISTAS Y, AL ADELANTAR, DEJAR MÁS DISTANCIA LATERAL. Tres correctas.\n\nQUÉ VES. La misma escena que la 5768: dos CICLISTAS van por delante, pegados a la derecha, y tú llevas el intermitente IZQUIERDO para adelantarlos.\n\nLOS CICLISTAS PUEDEN DESVIARSE O TAMBALEARSE. Vas preparado para frenar, vigilas lo que hacen y, al pasar, te separas de ellos todo lo posible.\n\n«DAR UNA SEÑAL ACÚSTICA» es el cebo: el claxon puede sobresaltarlos justo cuando estás a su lado.\n\nCLAVE: compárala con la 5768. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":5782,"bg":"При изпреварването на кое от изброените ППС трябва да се осигури по-голяма странична дистанция?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"велосипед","ok":true,"i":null,"es":"bicicleta"},{"t":"мотопед","ok":true,"i":null,"es":"ciclomotor"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"съчленен автобус","ok":false,"i":null,"es":"autobús articulado"}],"f":2,"es":"¿Al adelantar a cuál de los vehículos debes dar mayor distancia lateral? (2 correctas)","explain":"Mayor distancia lateral a la BICICLETA y al CICLOMOTOR: son inestables, pueden oscilar o caer, y no tienen carrocería. El tractor y el autobús articulado son grandes y estables: no necesitan margen extra por fragilidad."},{"id":5814,"bg":"Качването на дете до 12 години в автомобил, спрял на платното за движение, се извършва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"от страната на тротоара","ok":true,"i":null,"es":"el lado de la acera"},{"t":"от страната на пътния банкет","ok":true,"i":null,"es":"el lado del arcén"},{"t":"от която и да е страна на автомобила, когато детето е с възрастен придружител","ok":false,"i":null,"es":"cualquier lado si va con adulto"},{"t":"от страната на водача на МПС","ok":false,"i":null,"es":"el lado del conductor"}],"f":2,"es":"La subida de niños menores de 12 años a un vehículo parado en calzada se hace por: (2 correctas)","explain":"Los menores de 12 años suben por el lado de la ACERA o del ARCÉN: el lado protegido, igual que al bajar. 'Cualquier lado si va con adulto' es falso: el adulto no detiene al tráfico."},{"id":6030,"bg":"При тази ситуация:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26447.png","v":null,"a":[{"t":"продължавам движението с готовност за спиране","ok":true,"i":null,"es":"continúo la marcha preparado para detenerme"},{"t":"трябва да спра и да изчакам преминаването на пешеходеца","ok":false,"i":null,"es":"debo detenerme y esperar a que pase el peatón"}],"f":2,"es":"En esta situación:","explain":"CONTINÚO LA MARCHA PREPARADO PARA DETENERME. Una sola correcta.\n\nQUÉ VES. Calle urbana con un paso de peatones señalizado. En la acera IZQUIERDA, junto al paso, hay un hombre de pie y otras dos personas; nadie está cruzando.\n\nNADIE HA EMPEZADO A CRUZAR, así que no estás obligado a parar. Pero puede hacerlo en cualquier momento: sigues despacio y con el pie listo para frenar.\n\n«DEBO DETENERME Y ESPERAR» es el cebo: no hay ningún peatón cruzando ni entrando en el paso.\n\nCLAVE: peatón esperando junto al paso = atención y freno preparado; peatón en el paso = paras. Ver Leyes → «Paso de peatones»."},{"id":6032,"bg":"С кое от изброените действия при тази ситуация ще осигурите по-голяма безопасност за децата?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26564.png","v":null,"a":[{"t":"преминаване на възможно по-голямо разстояние от тях","ok":true,"i":null,"es":"pasar a la mayor distancia posible de ellos"},{"t":"движение с готовност за спиране","ok":true,"i":null,"es":"circular preparado para detenerse"},{"t":"намаляване на скоростта","ok":true,"i":null,"es":"reducción de velocidad"},{"t":"бързото преминаване покрай тях","ok":false,"i":null,"es":"pasar rápidamente junto a ellos"}],"f":2,"es":"¿Con cuál de las acciones enumeradas garantizarás en esta situación mayor seguridad a los niños? (3 correctas)","explain":"PASAR A LA MAYOR DISTANCIA POSIBLE, CIRCULAR PREPARADO PARA DETENERSE Y REDUCIR LA VELOCIDAD. Tres correctas.\n\nQUÉ VES. Calle urbana. En la zona de hierba a la derecha, junto al bordillo, varios NIÑOS juegan con un BALÓN, que está ya al borde de la calzada.\n\nUN BALÓN SUELTO CERCA DE LA CALZADA es la señal de que un niño puede salir corriendo tras él. Reduces, te apartas todo lo que puedas y vas con el freno preparado.\n\n«PASAR RÁPIDAMENTE JUNTO A ELLOS» es el cebo: menos tiempo expuesto, pero ninguna posibilidad de frenar si uno sale.\n\nCLAVE: balón cerca de la calzada = niño detrás. Ver Leyes → «Niños en la vía»."},{"id":6033,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26581.png","v":null,"a":[{"t":"предупреждава за опасност от внезапна поява на деца на платното за движение","ok":true,"i":null,"es":"advierte del peligro de aparición repentina de niños en la calzada"},{"t":"указва началото на пешеходна пътека","ok":false,"i":null,"es":"indica el inicio de un paso de peatones"},{"t":"забранява движението на деца по пътя","ok":false,"i":null,"es":"prohíbe la circulación de niños por la vía"},{"t":"обозначава точното място, където деца преминават през платното за движение","ok":false,"i":null,"es":"indica el lugar exacto donde los niños cruzan la calzada"}],"f":2,"es":"Esta señal:","explain":"ADVIERTE DEL PELIGRO DE APARICIÓN REPENTINA DE NIÑOS EN LA CALZADA. Una sola correcta.\n\nLA SEÑAL. TRIÁNGULO de peligro con dos NIÑOS corriendo con mochila.\n\nES UN TRIÁNGULO: AVISA de que cerca hay niños (colegio, parque) que pueden salir de repente a la calzada.\n\n«INICIO DE UN PASO DE PEATONES» y «LUGAR EXACTO DONDE CRUZAN» son cebos: esos se indican con las señales de paso de peatones.\n\n«PROHÍBE LA CIRCULACIÓN DE NIÑOS» sería un círculo rojo.\n\nCLAVE: compárala con la 5382 (el cuadrado naranja con niños va en un vehículo). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6050,"bg":"Когато водачът сигнализира за маневра с ръка, разрешено ли е да прекрати сигнала преди започване на маневрата?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"Cuando el conductor señaliza con el brazo, ¿puede interrumpir la señal antes de comenzar la maniobra?","explain":"Sí: la señal con el brazo puede interrumpirse antes de iniciar la maniobra: físicamente necesitas la mano para maniobrar. Es la diferencia con el intermitente, que se mantiene hasta completarla."},{"id":6057,"bg":"Сигналът за маневра, подаден със светлинен пътепоказател, трябва да бъде прекратен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"непосредствено след приключване на маневрата","ok":true,"i":null,"es":"inmediatamente DESPUÉS de completar la maniobra"},{"t":"непосредствено след започване на маневрата","ok":false,"i":null,"es":"inmediatamente al INICIO de la maniobra"},{"t":"по време на извършване на маневрата","ok":false,"i":null,"es":"DURANTE la ejecución de la maniobra"},{"t":"непосредствено преди приключване на маневрата","ok":false,"i":null,"es":"inmediatamente ANTES de completar la maniobra"}],"f":2,"es":"La señal de maniobra con intermitente luminoso debe cancelarse:","explain":"El intermitente se cancela inmediatamente DESPUÉS de completar la maniobra: debe estar activo durante TODA ella. Cancelarlo antes o al inicio deja a los demás sin la información justo cuando la necesitan."},{"id":6058,"bg":"Сигналът подаван от водача преди извършването на маневра осигурява ли му предимство?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":2,"es":"¿La señal del conductor antes de una maniobra le da prioridad?","explain":"No: señalizar informa, no da prioridad. El intermitente anuncia tu intención, pero la maniobra solo se ejecuta cuando es segura y respetando a quien tiene el paso: señalizar y cortar es infracción."},{"id":6060,"bg":"“Авариен сигнал” е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"едновременното включване на всички пътепоказатели","ok":true,"i":null,"es":"el encendido simultáneo de todos los intermitentes"},{"t":"превключването на дългите и късите светлини","ok":false,"i":null,"es":"la alternancia de luces largas y cortas (ráfagas)"},{"t":"последователното включване и изключване на всички светлини","ok":false,"i":null,"es":"el encendido y apagado sucesivo de todas las luces"},{"t":"едновременното включване и изключване на късите и габаритните светлини","ok":false,"i":null,"es":"el encendido y apagado simultáneo de las luces cortas y de posición"}],"f":2,"es":"La 'señal de emergencia' es:","explain":"La señal de emergencia es el encendido SIMULTÁNEO de todos los intermitentes (los cuatro a la vez). Las ráfagas de largas son otra señal (aviso), y las demás combinaciones no existen en el código."},{"id":6061,"bg":"Едновременното включване на всички пътепоказатели се използва за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"предупреждаване на участниците в движението за опасност на пътя","ok":true,"i":null,"es":"advertir a los usuarios de la vía de un peligro en la vía"},{"t":"обозначаване на МПС със специален режим на движение","ok":false,"i":null,"es":"identificar un vehículo con régimen especial de circulación"},{"t":"обозначаване на паркирано ППС","ok":false,"i":null,"es":"señalizar un vehículo estacionado"},{"t":"предупреждаване на другите участници в движението за предприемане на маневра","ok":false,"i":null,"es":"advertir a los demás usuarios de que se va a realizar una maniobra"}],"f":2,"es":"El encendido simultaneo de todos los intermitentes se usa para:","explain":"Los cuatro intermitentes a la vez advierten de un PELIGRO en la vía (avería, accidente, retención brusca). No identifican régimen especial (eso son luces azules/rojas), no señalizan estacionamiento normal ni anuncian maniobras."},{"id":6690,"bg":"При превоз на организирана група деца, автомобилът се обозначава с този опознавателен знак поставен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22861.png","v":null,"a":[{"t":"само отпред на автомобила","ok":false,"i":null,"es":"solo delante del automóvil"},{"t":"само отзад на автомобила","ok":false,"i":null,"es":"solo detrás del automóvil"},{"t":"отпред и отзад на автомобила","ok":true,"i":null,"es":"delante y detrás del automóvil"}],"f":2,"es":"Al transportar un grupo organizado de niños, el automóvil se señaliza con este distintivo colocado:","explain":"DELANTE Y DETRÁS DEL AUTOMÓVIL. Una sola correcta.\n\nQUÉ VES. El distintivo NARANJA con dos niños caminando, el de transporte de un grupo organizado de niños.\n\nEL VEHÍCULO LO LLEVA DELANTE Y DETRÁS, para que lo vean tanto los que vienen de frente como los que van detrás.\n\n«SOLO DELANTE» y «SOLO DETRÁS» son los cebos: dejan sin aviso a una de las dos direcciones.\n\nCLAVE: compárala con la 5381 y la 5382."},{"id":11678,"bg":"“Бавнодвижещо” се е пътно превозно средство, което не може да се движи със скорост, по-висока от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"30 km/h","ok":true,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"45 km/h","ok":false,"i":null,"es":"45 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":2,"es":"'Vehículo lento' es el vehículo de carretera que no puede circular a más de:","explain":"30 km/h: el 'vehículo lento' es el que por construcción no puede superar esa velocidad. Es la definición que activa sus obligaciones especiales (carril derecho, dejar pasar columnas)."},{"id":12021,"bg":"При тази ситуация трябва да спрете:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":6,"a":[{"t":"защото нямате достатъчна видимост към участъка, по който искате да продължите движението си","ok":true,"i":null,"es":"porque no tienes visibilidad suficiente del tramo por el que quieres continuar"},{"t":"за да изчакате потеглянето на белия автомобил","ok":false,"i":null,"es":"para esperar que el coche blanco arranque"},{"t":"за да осигурите предимство на велосипедиста","ok":true,"i":null,"es":"para ceder el paso al ciclista"}],"f":2,"es":"En esta situación debes parar: (2 correctas)","explain":"Estoy en un ceda el paso y un camión naranja cruza justo delante tapándome por completo la vista del tramo al que quiero incorporarme; además un ciclista llega al cruce por la derecha: PARO por dos razones — sin visibilidad no puedo evaluar si la vía está libre, y debo ceder el paso al ciclista. Esperar 'a que arranque el coche blanco' es irrelevante: el problema es lo que NO veo, no lo que está quieto."},{"id":5939,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41259.png","v":null,"a":[{"t":"че пътят води до кей или бряг","ok":true,"i":null,"es":"que el camino lleva a un muelle o ribera"},{"t":"за приближаване към подвижен мост","ok":false,"i":null,"es":"de la proximidad de un PUENTE MÓVIL"},{"t":"за приближаване към повреден мост","ok":false,"i":null,"es":"de la proximidad de un puente dañado"},{"t":"че пътят е затворен за движение","ok":false,"i":null,"es":"que la vía está cerrada"}],"f":2,"es":"Esta señal advierte:","explain":"QUE EL CAMINO LLEVA A UN MUELLE O RIBERA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un coche cayendo desde un borde al AGUA (líneas onduladas).\n\nAVISA DE QUE LA VÍA TERMINA EN UN MUELLE O EN LA ORILLA: si sigues, acabas en el agua.\n\n«PUENTE MÓVIL» se dibuja con un puente levadizo. «PUENTE DAÑADO» y «VÍA CERRADA» no son el significado de este dibujo.\n\nCLAVE: coche + agua = muelle u orilla. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5943,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41341.png","v":null,"a":[{"t":"за опасност от срутване на камъни на пътя","ok":true,"i":null,"es":"del peligro de desprendimiento de piedras en la vía"},{"t":"че е възможно да има паднали камъни на пътя","ok":true,"i":null,"es":"de que puede haber piedras caídas en la vía"},{"t":"че пътят отдясно е стеснен и е с разбита настилка","ok":false,"i":null,"es":"de que la vía se estrecha por la derecha y tiene el pavimento deteriorado"},{"t":"че отдясно на пътя се извършват строително-ремонтни работи","ok":false,"i":null,"es":"de que a la derecha de la vía se realizan obras de construcción"}],"f":2,"es":"Esta señal advierte: (2 correctas)","explain":"PELIGRO DE DESPRENDIMIENTO DE PIEDRAS Y POSIBLES PIEDRAS CAÍDAS EN LA VÍA. Dos correctas.\n\nLA SEÑAL. Triángulo de peligro con una LADERA a la derecha de la que caen piedras.\n\nAVISA DE DOS COSAS A LA VEZ: pueden caer piedras mientras pasas y puede haber piedras ya caídas en la calzada.\n\n«ESTRECHAMIENTO CON PAVIMENTO DETERIORADO» y «OBRAS A LA DERECHA» son cebos que leen la ladera como un borde roto o un montón de tierra de obra.\n\nCLAVE: piedras cayendo de una ladera = desprendimientos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5947,"bg":"Този пътен знак предупреждава водачите, че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42567.png","v":null,"a":[{"t":"е възможна поява на диви животни на пътя","ok":true,"i":null,"es":"puede haber ANIMALES SALVAJES en la vía"},{"t":"преминават покрай зоопарк","ok":false,"i":null,"es":"pasan cerca de un zoo"},{"t":"пътят навлиза в ловен участък","ok":false,"i":null,"es":"la vía entra en zona de caza"},{"t":"е възможна появата на домашни животни на пътя","ok":false,"i":null,"es":"puede haber animales domésticos en la vía"}],"f":2,"es":"Esta señal advierte a los conductores que:","explain":"PUEDE HABER ANIMALES SALVAJES EN LA VÍA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un CIERVO saltando.\n\nEL CIERVO = ANIMALES SALVAJES que cruzan, sobre todo al amanecer y al anochecer.\n\n«ANIMALES DOMÉSTICOS» se dibujan con una VACA (compárala con la 5946).\n\n«ZOO» y «ZONA DE CAZA» son cebos sin relación con esta señal.\n\nCLAVE: ciervo = salvajes; vaca = domésticos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5953,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42584.png","v":null,"a":[{"t":"&quot;Двупосочно движение&quot;","ok":true,"i":null,"es":"\"Circulación en ambos sentidos\""},{"t":"&quot;Пропусни насрещно движещите се автомобили&quot;","ok":false,"i":null,"es":"\"Cede el paso a los vehículos que vienen de frente\""},{"t":"&quot;Премини ако пътят е свободен&quot;","ok":false,"i":null,"es":"\"Pasa si la vía está libre\""},{"t":"&quot;Разминаването е забранено&quot;","ok":false,"i":null,"es":"\"El cruce con vehículos en sentido contrario está prohibido\""}],"f":2,"es":"El significado de esta señal es:","explain":"«CIRCULACIÓN EN AMBOS SENTIDOS». Una sola correcta.\n\nLA SEÑAL. TRIÁNGULO de peligro con dos flechas negras, una hacia arriba y otra hacia abajo.\n\nLAS SEÑALES DE FLECHAS ENFRENTADAS, QUE SE CONFUNDEN:\n• TRIÁNGULO con dos flechas negras = «Circulación en ambos sentidos» (aviso: se acaba la calzada de sentido único);\n• CÍRCULO con borde rojo, flecha NEGRA hacia abajo y ROJA hacia arriba = «Cede el paso a los que vienen de frente»;\n• CUADRADO AZUL, flecha ROJA hacia abajo y BLANCA hacia arriba = «Pasa si la vía está libre»: en un paso estrecho tienes preferencia, pero solo entras si no hay ya nadie dentro.\n\n«PROHIBIDO EL CRUCE CON LOS DE FRENTE» no es ninguna de estas señales.\n\nCLAVE: compárala con la 5954 y la 5960. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5970,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334704.png","v":null,"a":[{"t":"автомобили със специален режим на движение","ok":false,"i":null,"es":"automóviles con régimen especial de circulación"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":2,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"MOTOCICLETAS, CICLOMOTORES Y BICICLETAS. Tres correctas.\n\nLA SEÑAL. Círculo BLANCO con borde ROJO, sin dibujo: PROHIBIDA LA CIRCULACIÓN EN AMBOS SENTIDOS.\n\nSIN DIBUJO = PARA TODOS LOS VEHÍCULOS: motos, ciclomotores y también bicicletas.\n\n«AUTOMÓVILES CON RÉGIMEN ESPECIAL DE CIRCULACIÓN» es la excepción (ambulancias, bomberos, policía de servicio con sus señales).\n\nCLAVE: compárala con la 5971 y la 12077. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5980,"bg":"Този пътен знак забранява влизането на автомобили теглещи:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334708.png","v":null,"a":[{"t":"ремаркета с две и повече оси","ok":true,"i":null,"es":"remolques de dos o más ejes"},{"t":"полуремаркета","ok":false,"i":null,"es":"semirremolques"},{"t":"едноосни ремаркета","ok":false,"i":null,"es":"remolques de un eje"}],"f":2,"es":"Esta señal prohíbe la entrada a automóviles que remolcan:","explain":"REMOLQUES DE DOS O MÁS EJES. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un vehículo que remolca un REMOLQUE DE DOS EJES.\n\nLA SEÑAL PROHÍBE LO QUE DIBUJA: remolcar un remolque de dos o más ejes.\n\n«SEMIRREMOLQUES» y «REMOLQUES DE UN EJE» son los cebos: no los afecta (compárala con la 5981, la misma señal preguntada al revés).\n\nCLAVE: cuenta los ejes del remolque dibujado. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5988,"bg":"Този пътен знак забранява влизането на:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51911.png","v":null,"a":[{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":false,"i":null,"es":"bicicletas"},{"t":"самоходни машини","ok":false,"i":null,"es":"máquinas autopropulsadas"}],"f":2,"es":"Esta señal prohíbe la entrada a: (2 correctas)","explain":"MOTOCICLETAS Y CICLOMOTORES. Dos correctas.\n\nLA SEÑAL. Círculo con borde ROJO y una MOTOCICLETA.\n\nPROHÍBE LA ENTRADA A LAS MOTOCICLETAS y, con ellas, a los CICLOMOTORES.\n\n«BICICLETAS» es el cebo: no tienen motor. «MÁQUINAS AUTOPROPULSADAS» van con el tractor (5986).\n\nCLAVE: compárala con la 5987 (la misma señal). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5991,"bg":"Този пътен знак забранява:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51968.png","v":null,"a":[{"t":"влизането на изобразените ППС","ok":true,"i":null,"es":"la entrada de los vehículos representados"},{"t":"изпреварването на товарни автомобили от мотоциклети","ok":false,"i":null,"es":"el adelantamiento de camiones por motocicletas"},{"t":"влизането на ППС, с изключение на изобразените","ok":false,"i":null,"es":"la entrada de vehículos, excepto los representados"},{"t":"паркирането на товарни автомобили и мотоциклети","ok":false,"i":null,"es":"el estacionamiento de camiones y motocicletas"}],"f":2,"es":"Esta señal prohíbe:","explain":"LA ENTRADA DE LOS VEHÍCULOS REPRESENTADOS. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO tachado con una barra roja, con un CAMIÓN y una MOTOCICLETA.\n\nPROHÍBE LA ENTRADA A LO QUE ESTÁ DIBUJADO: camiones y motocicletas.\n\n«ADELANTAMIENTO DE CAMIONES POR MOTOS» es el cebo de quien lee los dos dibujos como una escena: las señales de adelantar tienen dos vehículos de frente, uno al lado del otro.\n\n«TODOS MENOS LOS REPRESENTADOS» le da la vuelta al significado. «ESTACIONAMIENTO» sería un círculo azul con borde rojo.\n\nCLAVE: compárala con la 6167 y la 6168. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6177,"bg":"Този пътен знак забранява влизането на ППС:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52837.png","v":null,"a":[{"t":"с широчина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"},{"t":"с дължина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"с височина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con altura, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго, на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"}],"f":2,"es":"Esta señal prohíbe la entrada de vehículos:","explain":"CON ANCHURA, INCLUIDA LA CARGA, SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO, «2,5 m» y dos puntas negras a la IZQUIERDA y a la DERECHA.\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«ALTURA» y «LONGITUD» tienen las puntas o el dibujo en otro sitio. «DISTANCIA ENTRE VEHÍCULOS» tiene dos coches y una cifra (6182).\n\nCLAVE: puntas a los lados = anchura. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6178,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52862.png","v":null,"a":[{"t":"широчината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"anchura del vehículo es superior a la indicada"},{"t":"широчината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"anchura del vehículo CON CARGA es superior a la indicada"},{"t":"дължината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"longitud de la carga es superior a la indicada"}],"f":2,"es":"Esta señal prohíbe la entrada de un vehículo cuya: (2 correctas)","explain":"LA ANCHURA DEL VEHÍCULO Y LA ANCHURA DEL VEHÍCULO CON CARGA SUPERIORES A LA INDICADA. Dos correctas.\n\nLA SEÑAL. La misma que la 6177: «2,5 m» con puntas a la IZQUIERDA y a la DERECHA.\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«LONGITUD DEL VEHÍCULO» y «LONGITUD DE LA CARGA» son los cebos: es otra señal.\n\nCLAVE: compárala con la 6176 (la misma pregunta con la altura). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6181,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53311.png","v":null,"a":[{"t":"дължината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"дължината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"longitud del vehículo CON CARGA es superior a la indicada"},{"t":"широчината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"anchura del vehículo es superior a la indicada"},{"t":"товарът е с широчина по-голяма от означената","ok":false,"i":null,"es":"anchura de la carga es superior a la indicada"}],"f":2,"es":"Esta señal prohíbe la entrada de un vehículo cuya: (2 correctas)","explain":"LA LONGITUD DEL VEHÍCULO Y LA LONGITUD DEL VEHÍCULO CON CARGA SUPERIORES A LA INDICADA. Dos correctas.\n\nLA SEÑAL. La misma que la 6180: un CAMIÓN con «← 10 m →».\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«ANCHURA DEL VEHÍCULO» y «ANCHURA DE LA CARGA» son los cebos: es la señal de las puntas a los lados.\n\nCLAVE: compárala con la 6176 y la 6178 (la misma pregunta con altura y anchura). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6183,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53509.png","v":null,"a":[{"t":"край на забраните, въведени с пътни знаци","ok":true,"i":null,"es":"fin de las prohibiciones impuestas por señales de tráfico"},{"t":"край на пътя с предимство","ok":false,"i":null,"es":"fin de la vía con prioridad"},{"t":"край на всички забрани","ok":false,"i":null,"es":"fin de todas las prohibiciones"}],"f":2,"es":"El significado de esta señal es:","explain":"FIN DE LAS PROHIBICIONES IMPUESTAS POR SEÑALES DE TRÁFICO. Una sola correcta.\n\nLA SEÑAL. Círculo BLANCO con borde negro y varias rayas negras oblicuas, sin ningún dibujo.\n\nPONE FIN A LAS PROHIBICIONES QUE HABÍAN PUESTO LAS SEÑALES (velocidad, adelantamiento…). Las prohibiciones de la propia ley siguen vigentes: los límites generales de velocidad, no adelantar en un paso de peatones, etc.\n\n«FIN DE TODAS LAS PROHIBICIONES» es el cebo fino: la palabra «todas» incluiría las de la ley, que no terminan con ninguna señal.\n\n«FIN DE LA VÍA CON PRIORIDAD» es el rombo amarillo tachado.\n\nCLAVE: las señales solo pueden quitar lo que pusieron las señales. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6208,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46701.png","v":null,"a":[{"t":"уширение на пътното платно","ok":true,"i":null,"es":"ensanchamiento de la plataforma vial"},{"t":"място за неограничено паркиране","ok":false,"i":null,"es":"lugar de estacionamiento sin límite de tiempo"},{"t":"спирка на превозни средства за обществен превоз на пътници","ok":false,"i":null,"es":"parada de vehículos de transporte público de pasajeros"},{"t":"пътна лента със съоръжение за аварийно спиране","ok":false,"i":null,"es":"carril con dispositivo de frenado de emergencia (lecho de frenado)"}],"f":2,"es":"Esta señal señaliza:","explain":"ENSANCHAMIENTO DE LA PLATAFORMA VIAL. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con la calzada dibujada: el borde derecho se abre hacia fuera y luego vuelve.\n\nES UN ENSANCHE junto a la calzada donde puedes apartarte para detenerte sin estorbar.\n\n«PARADA DE TRANSPORTE PÚBLICO» lleva un autobús o tranvía. «APARCAMIENTO SIN LÍMITE» lleva una «P». «LECHO DE FRENADO» es un carril de escape con grava, con su propia señal.\n\nCLAVE: borde que se abre y vuelve = ensanche. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6216,"bg":"Този пътен знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46817.png","v":null,"a":[{"t":"място за завиване в обратна посока","ok":true,"i":null,"es":"lugar para el cambio de sentido"},{"t":"задължителна посока за движение","ok":false,"i":null,"es":"dirección OBLIGATORIA"},{"t":"начин за заобикаляне на препятствие","ok":false,"i":null,"es":"modo de rodear un obstáculo"},{"t":"кръстовище с кръгово движение","ok":false,"i":null,"es":"intersección con circulación giratoria (glorieta)"}],"f":2,"es":"Esta señal indica:","explain":"LUGAR PARA EL CAMBIO DE SENTIDO. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una flecha blanca en forma de U (sube y vuelve hacia abajo).\n\nES INFORMATIVA: te indica un sitio habilitado para dar la vuelta.\n\n«DIRECCIÓN OBLIGATORIA» sería un círculo azul. «RODEAR UN OBSTÁCULO» es el círculo azul con flecha oblicua. «ROTONDA» son tres flechas en círculo.\n\nCLAVE: cuadrado azul = información. Ver Leyes → «Cambio de sentido o media vuelta». Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6224,"bg":"С допълнителната табела към този пътен знак се указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53909.png","v":null,"a":[{"t":"дължината на стеснения участък от платното за движение","ok":true,"i":null,"es":"la LONGITUD del tramo estrecho"},{"t":"разстоянието до стеснения участък от платното за движение","ok":false,"i":null,"es":"la DISTANCIA hasta el tramo estrecho"},{"t":"разстоянието до края на стеснения участък от платното за движение","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo estrecho"}],"f":2,"es":"La tablilla complementaria junto a esta señal indica:","explain":"LA LONGITUD DEL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Triángulo de ESTRECHAMIENTO por ambos lados con una placa debajo: «↑ 200 m ↑».\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA DISTANCIA HASTA EL TRAMO» sería la cifra sola (compárala con la 6218).\n\nCLAVE: flechas a los lados de la cifra = longitud. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6246,"bg":"За кои товарни автомобили се отнася знакът с допълнителната табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54164.png","v":null,"a":[{"t":"за всички товарни автомобили","ok":true,"i":null,"es":"para todos los camiones"},{"t":"само за тези с маса над 3,5 тона","ok":false,"i":null,"es":"solo para los de masa superior a 3,5 toneladas"},{"t":"само за тези с обща маса над 7,5 тона","ok":false,"i":null,"es":"solo para los de masa total superior a 7,5 toneladas"},{"t":"само за тези с допустима максимална маса над 12,5 тона","ok":false,"i":null,"es":"solo para los de masa máxima autorizada superior a 12,5 toneladas"}],"f":2,"es":"¿A qué camiones se refiere la señal con la tablilla adicional?","explain":"PARA TODOS LOS CAMIONES. Una sola correcta.\n\nQUÉ VES. Señal de PROHIBIDO GIRAR A LA IZQUIERDA con una placa debajo con un CAMIÓN, sin ninguna cifra.\n\nLA PLACA CON EL CAMIÓN, SIN NÚMERO, vale para todos los camiones, pesen lo que pesen. Si la prohibición fuera solo para los de cierta masa, la placa llevaría la cifra (por ejemplo, «> 3,5 t»).\n\n«SOLO MÁS DE 3,5 t», «MÁS DE 7,5 t» y «MÁS DE 12,5 t» inventan un límite que la placa no pone.\n\nCLAVE: compárala con la 6244 (la misma señal). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6248,"bg":"За кои автомобили се отнася знакът с допълнителната табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54221.png","v":null,"a":[{"t":"товарните","ok":true,"i":null,"es":"los camiones"},{"t":"леките","ok":false,"i":null,"es":"los turismos"},{"t":"автобусите","ok":false,"i":null,"es":"los autobuses"}],"f":2,"es":"¿A qué automóviles se refiere la señal con la tablilla adicional?","explain":"LOS CAMIONES. Una sola correcta.\n\nQUÉ VES. Señal de PROHIBIDO EL CAMBIO DE SENTIDO (flecha en U tachada) con una placa debajo con un CAMIÓN sin tachar.\n\nVEHÍCULO SIN TACHAR EN LA PLACA = LA SEÑAL VALE SOLO PARA ÉL. Los camiones no pueden dar la vuelta; los demás, sí.\n\n«LOS TURISMOS» y «LOS AUTOBUSES» no aparecen en la placa.\n\nCLAVE: compárala con la 6244 y la 6249. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6288,"bg":"На какво разстояние след знака, когато е поставен в населено място, се намира пешеходната пътека?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55888.png","v":null,"a":[{"t":"от 50 до 100 м","ok":true,"i":null,"es":"entre 50 y 100 m"},{"t":"от 100 до 150 м","ok":false,"i":null,"es":"entre 100 y 150 m"},{"t":"не повече от 50 м","ok":false,"i":null,"es":"no más de 50 m"},{"t":"непосредствено след знака","ok":false,"i":null,"es":"inmediatamente después"}],"f":2,"es":"¿A qué distancia después de la señal, colocada en zona urbana, está el paso de peatones?","explain":"ENTRE 50 Y 100 m. Una sola correcta.\n\nLA SEÑAL. Triángulo de PASO DE PEATONES, colocado EN población.\n\nEN POBLACIÓN, LAS SEÑALES DE PELIGRO van de 50 a 100 m antes del peligro (fuera de población, de 100 a 150 m).\n\n«100-150 m» es la distancia fuera de población. «NO MÁS DE 50 m» e «INMEDIATAMENTE DESPUÉS» no dejan tiempo para reaccionar.\n\nCLAVE: compárala con la 6287 y la 11888. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6303,"bg":"Когато над платното за движение е поставен пътен знак с допълнителната табела “Стрелка”, това означава, че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57156.png","v":null,"a":[{"t":"знакът се отнася само за пътната лента, над която е поставен","ok":true,"i":null,"es":"la señal se refiere solo al carril sobre el que está colocada"},{"t":"знакът не се отнася за пътната лента, над която е поставен","ok":false,"i":null,"es":"la señal NO se refiere al carril sobre el que está"},{"t":"знакът се отнася само за тези, които след него продължават движението си направо","ok":false,"i":null,"es":"la señal se refiere solo a los que continúan recto"},{"t":"знакът се отнася за цялата широчина на платното за движение","ok":false,"i":null,"es":"la señal se refiere a toda la anchura de la calzada"}],"f":2,"es":"Cuando sobre la calzada hay una señal con tablilla complementaria 'Flecha', esto significa:","explain":"LA SEÑAL SE REFIERE SOLO AL CARRIL SOBRE EL QUE ESTÁ COLOCADA. Una sola correcta.\n\nQUÉ VES. Calle de varios carriles. Colgada de un pórtico sobre el carril IZQUIERDO, una señal de PROHIBIDA LA ENTRADA A CAMIONES con una placa con una flecha hacia ABAJO.\n\nLA FLECHA HACIA ABAJO apunta al carril al que se aplica la señal. Los demás carriles no están afectados.\n\n«NO SE REFIERE A ESE CARRIL» le da la vuelta. «TODA LA ANCHURA» es lo que haría la señal sin la flecha. «SOLO A LOS QUE SIGUEN RECTO» inventa una condición.\n\nCLAVE: compárala con la 6306 y la 11869. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11681,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801979.png","v":null,"a":[{"t":"сигнализира близост до болница","ok":true,"i":null,"es":"señaliza la proximidad de un hospital"},{"t":"указва, че водачът трябва да вземе мерки за ограничаване на шума","ok":true,"i":null,"es":"indica que el conductor debe tomar medidas para limitar el ruido"},{"t":"указва, че може да се паркира от двете страни на пътя","ok":false,"i":null,"es":"indica que se puede estacionar a ambos lados de la vía"},{"t":"ограничава скоростта на движение до 40 km/h","ok":false,"i":null,"es":"limita la velocidad de circulación a 40 km/h"}],"f":2,"es":"Esta señal: (2 correctas)","explain":"SEÑALIZA LA PROXIMIDAD DE UN HOSPITAL E INDICA QUE EL CONDUCTOR DEBE TOMAR MEDIDAS PARA LIMITAR EL RUIDO. Dos correctas.\n\nLA SEÑAL. Cuadrado AZUL con una «H» blanca: HOSPITAL.\n\nLAS DOS COSAS VAN JUNTAS: hay un hospital cerca y, por eso, conduces sin hacer ruido (sin claxon, sin acelerones).\n\n«APARCAR A AMBOS LADOS» y «40 km/h» son cebos: la señal no dice nada de aparcar ni lleva número.\n\nCLAVE: compárala con la 11680 y la 11682. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11868,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828540.png","v":null,"a":[{"t":"„Забранено е влизането на товарни автомобили с допустима максимална маса над 7 t”","ok":true,"i":null,"es":"prohibida la entrada de camiones con masa autorizada superior a 7 t"},{"t":"„Забранено влизането на товарни автомобили с товароносимост над 7 t”","ok":false,"i":null,"es":"prohibida la entrada de camiones con capacidad de carga superior a 7 t"},{"t":"„Забранено влизането на товарни автомобили, на които товарът е над 7 t”","ok":false,"i":null,"es":"prohibida la entrada de camiones cuya carga supere 7 t"},{"t":"„Забранено влизането на товарни автомобили, на които натоварването на ос е над 7 t”","ok":false,"i":null,"es":"prohibida la entrada si la carga por eje supera 7 t"}],"f":2,"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE CAMIONES CON MASA MÁXIMA AUTORIZADA SUPERIOR A 7 t». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un CAMIÓN y «7 t» debajo.\n\nCAMIÓN + CIFRA = el límite es la MASA MÁXIMA AUTORIZADA del camión (la que figura en su documentación), no lo que lleva cargado en ese momento.\n\n«CAPACIDAD DE CARGA» y «CARGA SUPERIOR A 7 t» son cebos de vocabulario. «CARGA POR EJE» es la señal con el eje dibujado.\n\nCLAVE: compárala con la 5979 (la misma señal con 5 t). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11888,"bg":"На какво разстояние преди опасността се поставят предупредителните пътни знаци?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828562.png","v":null,"a":[{"t":"от 50 до 100 метра в населено място","ok":true,"i":null,"es":"de 50 a 100 metros dentro de poblado"},{"t":"от 100 до 150 метра извън населено място","ok":true,"i":null,"es":"de 100 a 150 metros fuera de poblado"},{"t":"на не повече от 50 метра","ok":false,"i":null,"es":"a no más de 50 metros"},{"t":"непосредствено преди опасността","ok":false,"i":null,"es":"inmediatamente antes del peligro"}],"f":2,"es":"¿A qué distancia antes del peligro se colocan las señales de advertencia? (2 correctas)","explain":"DE 50 A 100 m EN POBLADO Y DE 100 A 150 m FUERA DE POBLADO. Dos correctas.\n\nQUÉ VES. Una señal de peligro como ejemplo (paso de peatones).\n\nLAS SEÑALES DE PELIGRO SE COLOCAN ANTES DEL PELIGRO, a una distancia que te da tiempo a reaccionar:\n• en poblado (se va más despacio): de 50 a 100 m;\n• fuera de poblado (se va más rápido): de 100 a 150 m.\n\n«NO MÁS DE 50 m» e «INMEDIATAMENTE ANTES» son los cebos: no dejarían tiempo para frenar.\n\nCLAVE: si la distancia es otra, la señal lleva una placa con la cifra (compárala con la 6281)."},{"id":5865,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобразяват с атмосферните условия","ok":true,"i":null,"es":"las condiciones atmosféricas"},{"t":"трябва да се съобразяват с релефа на местността","ok":true,"i":null,"es":"el relieve del terreno"},{"t":"не са длъжни да се съобразяват със състоянието на пътя","ok":false,"i":null,"es":"no están obligados a considerar el estado de la vía"},{"t":"не са длъжни да се съобразяват със състоянието на превозното средство","ok":false,"i":null,"es":"no están obligados a considerar el estado del vehículo"}],"f":2,"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"La velocidad se elige considerando las condiciones atmosféricas y el relieve del terreno (y también el estado de la vía y del vehículo: por eso las opciones 'no están obligados' son siempre falsas en esta serie)."},{"id":5868,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не са длъжни да се съобразяват с атмосферните условия","ok":false,"i":null,"es":"no están obligados a considerar las condiciones atmosféricas"},{"t":"не са длъжни да се съобразяват с релефа на местността","ok":false,"i":null,"es":"no están obligados a considerar el relieve"},{"t":"трябва да се съобразяват с характера и интензивността на движението","ok":true,"i":null,"es":"la intensidad y el carácter del tráfico"},{"t":"трябва да се съобразяват с конкретните условия на видимост","ok":true,"i":null,"es":"las condiciones concretas de visibilidad"}],"f":2,"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"Aquí las correctas son la intensidad y carácter del tráfico y las condiciones de visibilidad. Las opciones 'no están obligados a considerar...' son siempre falsas: el conductor debe valorar TODOS los factores."},{"id":5881,"bg":"При тази ситуация, за да осигуря безопасността на децата, е достатъчно само да намаля скоростта.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57792.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":2,"es":"En esta situación, para garantizar la seguridad de los niños, es suficiente con solo reducir la velocidad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. En la acera DERECHA, un grupo de NIÑOS juega con un BALÓN, que ya ha rodado hacia la calzada.\n\nREDUCIR NO BASTA. Un balón en la calzada anuncia que un niño puede salir corriendo detrás de él sin mirar. Además de reducir, tienes que ir listo para frenar y, si puedes, alejarte del borde de la acera.\n\n«CORRECTO» es el cebo: la palabra «solo» (само) convierte una medida necesaria en insuficiente.\n\nCLAVE: balón en la calzada = un niño detrás. Reducir, apartarse y estar listo para frenar.\n\nMÉTODO: 1) ¿hay niños cerca? 2) ¿hay algo que los atraiga a la calzada? 3) reduzco, me aparto y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":6600,"bg":"Водачът на пътно превозно средство:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да намалява скоростта рязко, освен ако това е необходимо за предотвратяване на произшествие","ok":true,"i":null,"es":"no debe frenar bruscamente salvo para evitar un accidente"},{"t":"трябва да намали скоростта и при необходимост да спре, когато възникне опасност за движението","ok":true,"i":null,"es":"debe reducir y si es necesario parar cuando surja un peligro"},{"t":"е задължен да намали скоростта и при необходимост да спре при заслепяване","ok":true,"i":null,"es":"está obligado a reducir y parar cuando le deslumbren"},{"t":"не е задължен да намали скоростта за да предпази пешеходците от нараняване, когато на платното за движение има дребни камъни","ok":false,"i":null,"es":"no está obligado a reducir para proteger a peatones de salpicaduras"}],"f":2,"es":"El conductor de un vehículo: (3 correctas)","explain":"El conductor: no frena bruscamente salvo para evitar accidente, reduce y para ante un peligro, y reduce y para cuando le deslumbran (conducir a ciegas es inaceptable). La falsa: SÍ está obligado a reducir para no salpicar a los peatones."},{"id":6695,"bg":"Влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"видът на пътната настилка","ok":true,"i":null,"es":"el tipo de pavimento"},{"t":"видът на автомобилната гума","ok":true,"i":null,"es":"el tipo de neumático"},{"t":"разположението на двигателя","ok":false,"i":null,"es":"la posición del motor"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"f":2,"es":"El coeficiente de rozamiento está influido por: (2 correctas)","explain":"El rozamiento depende del tipo de pavimento y del tipo de neumático: las dos superficies en contacto. La posición del motor y el diámetro de las ruedas no cambian la adherencia disponible."},{"id":6697,"bg":"Как се изменя сцеплението на автомобилните гуми с пътя при заледена настилка в сравнение със суха?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалява","ok":true,"i":null,"es":"disminuye"},{"t":"увеличава се","ok":false,"i":null,"es":"aumenta"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"f":2,"es":"¿Cómo varía el rozamiento en pavimento helado respecto al seco?","explain":"Disminuye, y drásticamente: el hielo es la peor superficie posible, con una fracción mínima de la adherencia del seco. Ningún neumático convencional lo compensa: solo cadenas o clavos ayudan."},{"id":8262,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/125071123.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"движа се с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"продължавам движението, без да намалявам скоростта","ok":false,"i":null,"es":"continúo sin reducir"},{"t":"подавам сигнал, за да привлека вниманието на детето","ok":false,"i":null,"es":"toco el claxon para atraer la atención del niño"}],"f":2,"es":"¿Cómo actuarás en esta situación? (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y CIRCULO LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana con un PASO DE PEATONES (señales azules a ambos lados). A la derecha, junto al paso, un NIÑO está a punto de bajar a la calzada. Al otro lado hay más peatones.\n\nNIÑO JUNTO AL PASO = REDUCIR Y PREPARARSE. Va a cruzar, y los niños no calculan bien distancias ni velocidades.\n\n«CONTINÚO SIN REDUCIR» ignora el peligro.\n\n«TOCO EL CLAXON PARA ATRAER LA ATENCIÓN DEL NIÑO» es el cebo: puede asustarlo y provocar una reacción imprevisible.\n\nCLAVE: con niños, ni claxon ni prisa: reducir y estar listo para parar. Ver Leyes → «Niños en la vía»."},{"id":11587,"bg":"Водачът на пътно превозно средство:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да намалява скоростта рязко, освен ако това е необходимо за предотвратяване на произшествие","ok":true,"i":null,"es":"no debe frenar bruscamente salvo para evitar un accidente"},{"t":"трябва да намали скоростта и при необходимост да спре, когато възникне опасност за движението","ok":true,"i":null,"es":"debe reducir y si es necesario parar cuando surja un peligro"},{"t":"е задължен да намали скоростта и при необходимост да спре при заслепяване","ok":true,"i":null,"es":"está obligado a reducir y parar cuando le deslumbren"},{"t":"не е задължен да намали скоростта за да предпази пешеходците от изцапване, когато на платното за движение има вода или кал","ok":false,"i":null,"es":"no está obligado a reducir para no salpicar a peatones"}],"f":2,"es":"El conductor: (3 correctas)","explain":"Idéntica a su gemela: prohibido frenar bruscamente salvo emergencia, obligatorio reducir/parar ante peligro y al ser deslumbrado. Y SÍ hay obligación de reducir para no salpicar a los peatones: la opción que lo niega es la falsa."},{"id":11693,"bg":"Когато няма други ограничения, водачът на мотоциклет при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":2,"es":"Sin otras restricciones, el conductor de moto en zona urbana no debe superar:","explain":"50 km/h: en zona urbana la moto tiene el mismo límite general que el resto de vehículos de motor. Las diferencias por categoría aparecen fuera de población y en autopista."},{"id":6352,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово пътно превозно средство е длъжен да пропусне релсовите ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само когато релсовите ППС се намират от дясната му страна","ok":false,"i":null,"es":"solo cuando está a su derecha"},{"t":"само когато релсовите ППС се намира от лявата му страна","ok":false,"i":null,"es":"solo cuando está a su izquierda"},{"t":"само когато релсовите ППС са в насрещното движение","ok":false,"i":null,"es":"solo cuando viene de frente"},{"t":"винаги, независимо от местоположението им","ok":true,"i":null,"es":"siempre, independientemente de su posición"}],"f":2,"es":"En intersección de vías equivalentes, el conductor no ferroviario debe dejar pasar al tranvía:","explain":"Siempre: en cruce de vías equivalentes, el no ferroviario cede al tranvía venga de donde venga: derecha, izquierda o de frente. El tranvía no puede desviarse ni frenar como un coche: su prioridad es absoluta en este supuesto."},{"id":6377,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71276.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"¿Está permitido dar la vuelta en esta situación?","explain":"SÍ.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. El semáforo está en VERDE y encima hay una señal de borde ROJO con la flecha de giro a la izquierda TACHADA: PROHIBIDO GIRAR A LA IZQUIERDA.\n\nLA PROHIBICIÓN SOLO PROHÍBE LO QUE DIBUJA. Esta señal prohíbe el giro a la izquierda, pero en el examen búlgaro no prohíbe el cambio de sentido. Para prohibir la vuelta existe otra señal distinta (la de la flecha en U tachada).\n\n«NO» es el cebo de quien piensa que, si no se puede girar a la izquierda, tampoco se puede dar la vuelta.\n\nCLAVE: roja de prohibido girar a la izquierda = SÍ se puede dar la vuelta; azul de giro obligatorio a la izquierda = NO (compárala con la 6375). Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6409,"bg":"Разрешено ли е да предприемете изпреварване, когато автомобилът зад вас е подал сигнал за отклонение наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69437.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":2,"es":"¿Está permitido adelantar cuando el vehículo que va detrás de usted ha señalizado que se desvía a la izquierda?","explain":"NO.\n\nQUÉ VES. Delante circula un coche ROJO. En los retrovisores se ve un coche AZUL detrás de ti con el intermitente IZQUIERDO: ya ha empezado a adelantarte. A la derecha, la señal de FIN DE TODAS LAS PROHIBICIONES.\n\nANTES DE ADELANTAR, MIRA SI TE ESTÁN ADELANTANDO A TI. Si el de detrás ya ha señalizado que se desplaza a la izquierda, no puedes iniciar tu adelantamiento: os encontraríais los dos en el carril izquierdo.\n\n«SÍ» es el cebo: la señal de fin de prohibiciones te hace pensar que ya puedes adelantar, pero no te libra de comprobar lo que viene detrás.\n\nCLAVE: antes de adelantar: el de delante no adelanta, el de detrás no me adelanta, y tengo hueco para volver. Compárala con la 12051 (vídeo). Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":12007,"bg":"При тази ситуация управлявате с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":28,"a":[{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"мотоциклетиста","ok":false,"i":null,"es":"el motorista"}],"f":2,"es":"En esta situación debes circular listo para frenar por:"},{"id":12011,"bg":"При тази ситуация трябва да осигурите предимство на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":23,"a":[{"t":"трамвая","ok":true,"i":null,"es":"el tranvía"},{"t":"белия автомобил","ok":false,"i":null,"es":"el coche blanco"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"}],"f":2,"es":"En esta situación debes ceder el paso a:"},{"id":12033,"bg":"При тази ситуация кое действие на водача на автомобила от насрещното движение трябва да предвидите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":19,"a":[{"t":"да изпревари велосипедиста без да навлиза във вашата лента","ok":false,"i":null,"es":"adelantará al ciclista sin invadir tu carril"},{"t":"да изчака велосипедистът да се размине с автомобилите от насрещното движение","ok":false,"i":null,"es":"esperará al ciclista"},{"t":"да изпревари велосипедиста, като навлезе частично в лентата за насрещно движение","ok":true,"i":null,"es":"adelantará al ciclista invadiendo parcialmente tu carril"}],"f":2,"es":"¿Qué acción del conductor contrario debes anticipar?"},{"id":12035,"bg":"Защо трябва да спрете при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":21,"a":[{"t":"заради велосипедиста","ok":true,"i":null,"es":"por el ciclista"},{"t":"заради зеленият автомобил","ok":false,"i":null,"es":"por el coche verde"},{"t":"заради пешеходеца","ok":false,"i":null,"es":"por el peatón"}],"f":2,"es":"¿Por qué debes parar en esta situación?"},{"id":12037,"bg":"При тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":26,"a":[{"t":"намалявам скоростта си, за да може изпреварващото превозно средство да се прибере пред мен","ok":true,"i":null,"es":"reduzco para que el adelantante pueda reincorporarse"},{"t":"ускорявам, за да може изпреварващото превозно средство да премине в дясната лента зад мен","ok":false,"i":null,"es":"acelero para que pueda pasar al derecho"},{"t":"поддържам скоростта си, защото има достатъчно безопасно разстояние","ok":false,"i":null,"es":"mantengo la velocidad porque hay distancia suficiente"}],"f":2,"es":"En esta situación:"},{"id":12044,"bg":"Позволено ли е да предприемете изпреварване при тази ситуация сега?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":36,"a":[{"t":"не, защото видимостта е ограничена","ok":true,"i":null,"es":"no, porque la visibilidad es limitada"},{"t":"да, защото при разминаването с велосипеда и мотоциклета мога да осигуря достатъчно странично разстояние","ok":false,"i":null,"es":"sí, con distancia para el ciclista y la moto"},{"t":"не, защото в лентата за насрещно движение има превозно средство","ok":true,"i":null,"es":"no, porque hay un vehículo en el carril contrario"}],"f":2,"es":"¿Está permitido adelantar ahora en esta situación? (2 correctas)"},{"id":12049,"bg":"При тази ситуация трябва да намалите скоростта си заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":41,"a":[{"t":"ограничението на скоростта","ok":false,"i":null,"es":"la limitación de velocidad"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"},{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"}],"f":2,"es":"En esta situación debes reducir la velocidad por:"},{"id":12050,"bg":"При тази ситуация не трябва да предприемате изпреварване заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":30,"a":[{"t":"превозните средства от насрещното движение","ok":true,"i":null,"es":"los vehículos del tráfico contrario"},{"t":"завоя на пътя","ok":true,"i":null,"es":"la curva de la vía"},{"t":"състоянието на пътната настилка","ok":false,"i":null,"es":"el estado del pavimento"}],"f":2,"es":"En esta situación no debes adelantar por: (2 correctas)"},{"id":6508,"bg":"При тази ситуация преминавам преди товарния автомобил, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63096.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":2,"es":"En esta situación paso antes que el camión porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por esa rama derecha llega un CAMIÓN azul con el intermitente puesto.\n\nLOS DOS ESTÁIS EN LA VÍA CON PRIORIDAD, y entre vosotros decide la regla de la derecha. El camión te llega por la derecha: pasa él primero.\n\n«PORQUE VOY RECTO» es la razón falsa: ir recto no da prioridad. Basta con que la razón sea falsa para que el enunciado sea неправилно.\n\nCLAVE: en los enunciados con «porque…», si la razón es «porque voy recto», casi siempre es falso. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6516,"bg":"При тази ситуация трябва да пропусна червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63275.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":2,"explain":"CORRECTO.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO viene de ARRIBA y gira hacia un lado; tú vienes por una rama fina y vas recto. De frente, por la rama gruesa, viene un coche ROJO con el intermitente.\n\nEL ROJO VA POR LA PREFERENTE Y TÚ LLEVAS CEDA EL PASO. Le cedes, aunque tú vayas recto y él gire.\n\n«INCORRECTO» es el cebo de quien aplica «el que gira cede al que va recto»: eso vale entre vehículos de la misma vía, no cuando una señal os separa.\n\nCLAVE: compárala con la 6514 (misma señal, tú girando a la izquierda): en las dos cedes por la señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección».","es":"En esta situación debo ceder el paso al rojo. Esto es:"},{"id":5593,"bg":"При тази ситуация, преминавайки покрай спрелия на спирката трамвай, трябва да се съобразявам:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39320.png","v":null,"a":[{"t":"с пешеходците, които са на острова на платното за движение","ok":true,"i":null,"es":"con los peatones que están en la isleta de la calzada"},{"t":"с пешеходците, които слизат от трамвая или са на тротоара","ok":true,"i":null,"es":"con los peatones que bajan del tranvía o están en la acera"},{"t":"с пешеходците, които пресичат платното за движение пред или зад трамвая","ok":true,"i":null,"es":"con los peatones que cruzan la calzada por delante o por detrás del tranvía"},{"t":"с превозните средства, които се движат зад мен","ok":false,"i":null,"es":"con los vehículos que circulan detrás de mí"}],"f":2,"es":"En esta situación, al pasar junto al tranvía parado en la parada, debo tener en cuenta: (3 correctas)","explain":"LOS PEATONES DE LA ISLETA, LOS QUE BAJAN DEL TRANVÍA O ESTÁN EN LA ACERA Y LOS QUE CRUZAN POR DELANTE O POR DETRÁS DEL TRANVÍA. Tres correctas.\n\nQUÉ VES. Un TRANVÍA detenido en su parada con una ISLETA entre las vías y tu carril; en ella hay una mujer. En la acera derecha hay más gente junto a la señal de parada.\n\nALREDEDOR DE UNA PARADA, LOS PEATONES ESTÁN EN TODAS PARTES: en la isleta, en la acera, bajando y cruzando. Pasas despacio y vigilándolos a todos.\n\n«LOS VEHÍCULOS QUE VAN DETRÁS DE MÍ» es el cebo: no son el peligro de esta situación.\n\nCLAVE: compárala con la 5589 (la misma escena)."},{"id":5635,"bg":"Разрешено ли е водачът на двуколесно МПС да се държи за друго превозно средство с цел придвижване по пътя?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"да, но само когато двуколесното МПС е повредено","ok":false,"i":null,"es":"sí, pero solo cuando el vehículo de dos ruedas está averiado"},{"t":"да, но само ако това превозно средство се движи в дясната пътна лента","ok":false,"i":null,"es":"sí, pero solo si ese vehículo circula por el carril derecho"}],"f":2,"es":"¿Está permitido que el conductor de un vehículo de dos ruedas se agarre a otro vehículo para desplazarse por la vía?","explain":"No: agarrarse a otro vehículo para desplazarse está prohibido siempre para los de dos ruedas: sin excepciones por avería ni por carril. Un tirón, un bache, y el remolcado humano cae bajo las ruedas."},{"id":5672,"bg":"На водача на двуколесно моторно превозно средство е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи по пътния банкет","ok":false,"i":null,"es":"circular por el arcén"},{"t":"да се движи в непосредствена близост до друго пътно превозно средство","ok":true,"i":null,"es":"circular muy cerca de otro vehículo"},{"t":"да се държи за друго пътно превозно средство с цел придвижване по пътя","ok":true,"i":null,"es":"agarrarse a otro vehículo para desplazarse por la vía"},{"t":"да превозва предмети, които създават опасност за другите участници в движението","ok":true,"i":null,"es":"transportar objetos que crean peligro para los demás usuarios de la vía"}],"f":2,"es":"Al conductor de un vehículo de motor de dos ruedas le está prohibido: (3 correctas)","explain":"Prohibido a las motos: pegarse a otro vehículo, remolcarse agarrándose y llevar objetos peligrosos para los demás. Circular por el arcén está permitido a ciclomotores (y es la opción no marcada): la moto en calzada, el matiz de esta variante."},{"id":5700,"bg":"При теглене през деня на повредено МПС теглещото превозно средство трябва да бъде с включени:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"къси светлини","ok":true,"i":null,"es":"luces cortas"},{"t":"авариен сигнал","ok":true,"i":null,"es":"las luces de emergencia"},{"t":"дълги светлини","ok":false,"i":null,"es":"luces largas"},{"t":"само габаритни светлини","ok":false,"i":null,"es":"solo luces de posición"}],"f":2,"es":"Al remolcar de día un vehículo averiado, el vehículo que remolca debe llevar encendidas: (2 correctas)","explain":"El REMOLCADOR de día lleva: luces cortas + luces de emergencia: anuncia el convoy anómalo y lento. Las largas de día no aportan y solo posición es insuficiente: la combinación cortas+emergencia es la fórmula."},{"id":5730,"bg":"При теглене с твърда връзка:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"тегличът трябва да е с дължина от 2 до 4 метра","ok":true,"i":null,"es":"la barra debe tener entre 2 y 4 metros"},{"t":"тегличът трябва да е оцветен напречно с червени и бели ивици","ok":true,"i":null,"es":"la barra debe estar pintada en franjas rojas y blancas"},{"t":"тегленото МПС трябва да бъде с изправна кормилна уредба","ok":true,"i":null,"es":"el vehículo remolcado debe tener la dirección en buen estado"},{"t":"тегленото МПС трябва да е с изправна спирачна уредба","ok":false,"i":null,"es":"el vehículo remolcado debe tener los frenos en buen estado"}],"f":2,"es":"Al remolcar con barra rígida: (3 correctas)","explain":"Barra rígida: de 2 a 4 m, pintada en franjas rojas y blancas (visible para terceros) y el remolcado con la DIRECCIÓN en buen estado. Los frenos del remolcado NO son requisito con barra: la barra transmite el frenado: esa es la clave física."},{"id":5733,"bg":"При теглене с гъвкава връзка:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"дължинатана връзката трябва да бъде от 4 до 6 метра","ok":true,"i":null,"es":"la longitud del enganche debe ser de 4 a 6 metros"},{"t":"връзката трябва да бъде сигнализирана с червен флаг поне на две места","ok":true,"i":null,"es":"el enganche debe estar señalizado con bandera roja al menos en dos puntos"},{"t":"тегленото МПС трябва да е с изправна кормилна уредба","ok":true,"i":null,"es":"el vehículo remolcado debe tener la dirección en buen estado"},{"t":"водачът на теглещото МПС трябва да има не по-малко от две години стаж","ok":false,"i":null,"es":"el conductor del vehículo que remolca debe tener al menos dos años de experiencia"}],"f":2,"es":"Al remolcar con enganche flexible: (3 correctas)","explain":"Cable flexible: de 4 a 6 m, señalizado con bandera roja en al menos dos puntos, y el remolcado con dirección en buen estado (con cable, también necesita frenos: aquí preguntan la dirección). La 'experiencia de dos años' del conductor no existe como requisito."},{"id":5742,"bg":"При теглене на повредено МПС с гъвкава връзка то трябва да бъде:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с изправна кормилна уредба","ok":true,"i":null,"es":"la dirección en buen estado"},{"t":"с изправна спирачна уредба","ok":true,"i":null,"es":"los frenos en buen estado"},{"t":"с изправен двигател","ok":false,"i":null,"es":"el motor en buen estado"},{"t":"с изправна осветителна уредба","ok":false,"i":null,"es":"el sistema de iluminación en buen estado"}],"f":2,"es":"Al remolcar con cable flexible el vehículo remolcado debe tener: (2 correctas)","explain":"Con cable FLEXIBLE el remolcado necesita: dirección Y frenos en buen estado: el cable no transmite frenado (solo tira), así que el remolcado debe frenar por sí mismo para no embestir. El motor y las luces no son los requisitos preguntados."},{"id":5747,"bg":"Разрешено ли е тегленето с твърда връзка на автомобил с повредена кормилна уредба?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":2,"es":"¿Está permitido remolcar con enganche rígido un automóvil con la dirección averiada?","explain":"No: con la dirección averiada no se remolca ni con barra rígida: el remolcado debe poder seguir la trayectoria. Dirección rota = solo grúa de plataforma."},{"id":5758,"bg":"Разрешено ли е тегленето на мотоциклет с кош?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":2,"es":"¿Está permitido remolcar una motocicleta con sidecar?","explain":"No: las motocicletas con sidecar no se remolcan: su geometría asimétrica las hace incontrolables a remolque. Moto averiada = transporte en plataforma."},{"id":5770,"bg":"В кой от изброените случаи тегленето е забранено?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"теглене при намалена видимост под 50 метра","ok":true,"i":null,"es":"remolcar con visibilidad inferior a 50 metros"},{"t":"теглене с едно превозно средство на два повредени автомобила","ok":true,"i":null,"es":"remolcar con un solo vehículo dos automóviles averiados"},{"t":"теглене на повреден товарен автомобил","ok":false,"i":null,"es":"remolcar un camión averiado"},{"t":"теглене на повреден автомобил през нощта","ok":false,"i":null,"es":"remolcar un automóvil averiado de noche"}],"f":2,"es":"¿En cuál de los casos indicados está prohibido el remolcado? (2 correctas)","explain":"Prohibido: remolcar bajo 50 m de visibilidad y remolcar dos averiados con un solo vehículo. El camión averiado y el remolcado nocturno son legales: los distractores fijos de esta familia."},{"id":5774,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"теглене с едно превозно средство на два повредени автомобила","ok":true,"i":null,"es":"remolcar con un solo vehículo dos automóviles averiados"},{"t":"теглене, когато теглещият автомобил е с ремарке","ok":true,"i":null,"es":"remolcar cuando el automóvil que remolca lleva un remolque"},{"t":"теглене, когато тегленият автомобил е с ремарке","ok":true,"i":null,"es":"remolcar cuando el automóvil remolcado lleva un remolque"},{"t":"теглене на повреден автомобил през нощта","ok":false,"i":null,"es":"remolcar un automóvil averiado de noche"}],"f":2,"es":"Al remolcar un automóvil averiado está prohibido: (3 correctas)","explain":"Prohibido remolcar cuando hay remolque en CUALQUIERA de los dos: ni el remolcador con remolque, ni el remolcado con remolque, ni dos averiados a la vez: nada de trenes improvisados de tres unidades. De noche, permitido con señalización."},{"id":5803,"bg":"При тази ситуация водачът на жълтия автомобил:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29209.png","v":null,"a":[{"t":"трябва да пропусне автомобила на спешната медицинска помощ, защото той е с включен сигнал","ok":true,"i":null,"es":"debe ceder el paso al automóvil de urgencias médicas, porque lleva la señal encendida"},{"t":"не е задължен да пропусне автомобила на спешната медицинска помощ, защото е от дясната му страна","ok":false,"i":null,"es":"no está obligado a ceder el paso al automóvil de urgencias médicas, porque está a su derecha"},{"t":"има разрешаващ сигнал и преминава преди автомобила на спешната медицинска помощ","ok":false,"i":null,"es":"tiene señal permisiva y pasa antes que el automóvil de urgencias médicas"}],"f":2,"es":"En esta situación, el conductor del automóvil amarillo:","explain":"DEBE CEDER EL PASO A LA AMBULANCIA PORQUE LLEVA LA SEÑAL ENCENDIDA. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE para el coche AMARILLO. Por la izquierda llega una AMBULANCIA con luces azules.\n\nUN VEHÍCULO EN RÉGIMEN ESPECIAL (con las señales luminosas y acústicas encendidas) pasa por delante de las reglas de prioridad, de las señales y del semáforo: se le cede siempre. Ni el verde te da paso por delante de ella.\n\n«ESTÁ A SU DERECHA» es falso y además irrelevante. «TIENE VERDE Y PASA ANTES» es el cebo principal.\n\nCLAVE: régimen especial > semáforo. Ver Leyes → «Quién manda sobre quién»."},{"id":11589,"bg":"На водача на МПС със специален режим на движение:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"е разрешено да преминава, без да спира, при наличие на пътен знак, който изисква това","ok":true,"i":null,"es":"tiene permitido pasar sin detenerse cuando hay una señal que lo exige"},{"t":"е разрешено да надвишава разрешената максимална скорост на движение","ok":true,"i":null,"es":"tiene permitido superar la velocidad máxima autorizada"},{"t":"е забранено да преминава при забраняващ сигнал на светофара","ok":false,"i":null,"es":"tiene prohibido pasar con la señal prohibitiva del semáforo"},{"t":"е забранено да паркира на места, където има забрана за паркиране","ok":false,"i":null,"es":"tiene prohibido estacionar en lugares donde hay prohibición de estacionar"}],"f":2,"es":"Al conductor de un vehículo con régimen especial de circulación: (2 correctas)","explain":"El régimen especial PUEDE: pasar sin detenerse ante señales que lo exigen y superar la velocidad. Las dos opciones 'prohibido' son falsas: también puede pasar en rojo y estacionar donde está prohibido: el régimen cubre todo eso (nunca la conducción insegura)."},{"id":5542,"bg":"Този пътен знак забранява:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41950.png","v":null,"a":[{"t":"спирането за престой","ok":true,"i":null,"es":"la parada breve"},{"t":"паркирането","ok":true,"i":null,"es":"el aparcamiento"},{"t":"изпреварването","ok":false,"i":null,"es":"el adelantamiento"},{"t":"движението назад","ok":false,"i":null,"es":"ir marcha atrás"}],"f":2,"es":"Esta señal de tráfico prohíbe: (2 correctas)","explain":"LA PARADA BREVE Y EL APARCAMIENTO. Dos correctas.\n\nLA SEÑAL. Círculo AZUL con borde ROJO y DOS barras rojas EN ASPA.\n\nEL ASPA PROHÍBE LAS DOS COSAS: ni detenerse ni aparcar.\n\n«ADELANTAR» y «MARCHA ATRÁS» son cebos: tienen otras señales.\n\nCLAVE: una barra = solo aparcar; aspa = parar y aparcar. Compárala con la 5546. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5663,"bg":"При движение през нощта МПС трябва да бъдат:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси или дълги светлини","ok":true,"i":null,"es":"con las luces de cruce o de carretera encendidas"},{"t":"с включени габаритни светлини","ok":true,"i":null,"es":"con las luces de posición encendidas"},{"t":"с включен светлина за осветяване на задната табела с регистрационния номер","ok":true,"i":null,"es":"con la luz de la placa de matrícula trasera encendida"},{"t":"с включен авариен сигнал","ok":false,"i":null,"es":"con la señal de avería activada (luces de emergencia)"}],"f":2,"es":"Al circular de noche, los vehículos de motor deben ir: (3 correctas)","explain":"De noche se circula con: cruce o carretera + luces de posición + luz de placa trasera: el conjunto completo de alumbrado de marcha. Las luces de emergencia NO son para circular: señalizan avería o peligro."},{"id":11632,"bg":"Кои от посочените светлини на автомобила се използват при движение през деня?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"светлини за движение през деня","ok":true,"i":null,"es":"luces de circulación diurna"},{"t":"къси светлини","ok":true,"i":null,"es":"luces cortas"},{"t":"дълги светлини","ok":false,"i":null,"es":"luces largas"},{"t":"габаритни светлини","ok":false,"i":null,"es":"luces de posición"}],"f":2,"es":"¿Cuáles de las luces indicadas del automóvil se usan al circular de día? (2 correctas)","explain":"De día se circula con luces DIURNAS o CORTAS: las dos opciones legales. Las largas de día no aportan y las de posición solas no son luces de circulación: son de estacionamiento y presencia."},{"id":11635,"bg":"Разрешено ли е при движение в мъгла да използвате дългите светлини?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, но е неправилно","ok":true,"i":null,"es":"sí, pero es incorrecto"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"¿Está permitido usar las luces largas al circular con niebla?","explain":"Sí, pero es incorrecto: las largas con niebla no están prohibidas por la ley, pero la luz rebota en las gotas y te deslumbras a ti mismo: técnica pésima. La distinción legal/técnico se pregunta con niebla y con nevada: misma respuesta."},{"id":5738,"bg":"Какъв съвет ще дадете на водач, който е употребил алкохол?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да се придвижи с такси или друг обществен транспорт","ok":true,"i":null,"es":"desplazarse en taxi u otro transporte público"},{"t":"да изчака да премине действието на алкохола","ok":true,"i":null,"es":"esperar a que pase el efecto del alcohol"},{"t":"да изпие чаша силно кафе и след това да управлява","ok":false,"i":null,"es":"tomarse un café fuerte y después conducir"},{"t":"да управлява внимателно и да се движи с ниска скорост","ok":false,"i":null,"es":"conducir con cuidado y a baja velocidad"}],"f":2,"es":"¿Qué consejo le dará a un conductor que ha consumido alcohol? (2 correctas)","explain":"A quien bebió: taxi o transporte público, o esperar a que el alcohol se elimine: las dos únicas salidas reales. El café fuerte no acelera la eliminación (solo despeja la sensación) y 'despacio y con cuidado' sigue siendo conducir ebrio."},{"id":5740,"bg":"Има ли лекарства, след приемането на които е забранено управлението на МПС?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"¿Hay medicamentos tras cuya toma está prohibido conducir?","explain":"Sí: hay medicamentos que prohíben conducir: sedantes, algunos antihistamínicos, opiáceos: reducen reflejos y atención. Por eso el prospecto y el farmacéutico son parada obligatoria antes de tomar algo y conducir."},{"id":6117,"bg":"Какво влияние оказва алкохолът върху поведението на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забавя реакциите","ok":true,"i":null,"es":"ralentiza las reacciones"},{"t":"намалява концентрацията","ok":true,"i":null,"es":"reduce la concentración"},{"t":"подобрява координацията на движенията","ok":false,"i":null,"es":"mejora la coordinación de los movimientos"},{"t":"намалява увереността","ok":false,"i":null,"es":"reduce la seguridad en uno mismo"}],"f":2,"es":"¿Qué influencia tiene el alcohol sobre el comportamiento del conductor? (2 correctas)","explain":"El alcohol ralentiza las reacciones y reduce la concentración. Ojo a la trampa doble: 'mejora la coordinación' es falsa evidente, pero 'reduce la seguridad en uno mismo' también es falsa: el alcohol AUMENTA la falsa seguridad: ese es su mayor peligro."},{"id":6123,"bg":"Минималното време, необходимо на организма, за да отдели от кръвта 0,5 промили алкохол, е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"от 1 до 2 часа","ok":false,"i":null,"es":"de 1 a 2 horas"},{"t":"от 2 до 3 часа","ok":false,"i":null,"es":"de 2 a 3 horas"},{"t":"не по-малко от 4 часа","ok":true,"i":null,"es":"no menos de 4 horas"}],"f":2,"es":"El tiempo mínimo que necesita el organismo para eliminar de la sangre 0,5 por mil de alcohol es:","explain":"No menos de 4 horas: eliminar 0,5‰ lleva ese mínimo (el hígado procesa a ritmo fijo, ~0,1-0,15‰ por hora). Las opciones de 1-3 horas alimentan el clásico 'ya se me pasó': no, no se pasó."},{"id":6124,"bg":"Употребата на тонизиращи напитки (силни дози кафе или чай) ускорява ли разграждането на алкохола в кръвта на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":2,"es":"El consumo de bebidas estimulantes (dosis fuertes de café o té), ¿acelera la descomposición del alcohol en la sangre del conductor?","explain":"No: el café y el té no aceleran la descomposición del alcohol: el hígado va a su ritmo, tomes lo que tomes. El estimulante te DESPIERTA, pero sigues igual de ebrio: un borracho despierto."},{"id":6128,"bg":"Приемането на различни освежителни напитки, като силно кафе или чай има продължителен ободрителен ефект върху водача.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":false,"i":null,"es":"correcto"},{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"}],"f":2,"es":"Tomar distintas bebidas refrescantes, como café fuerte o té, tiene un efecto estimulante duradero sobre el conductor.","explain":"INCORRECTO: el efecto del café o té fuerte es de CORTA duración, no duradero. Pasado el pico, la fatiga vuelve con más fuerza: confiar en la cafeína para un viaje largo es una trampa."},{"id":6137,"bg":"Влияе ли възрастта на водачите на способността им да виждат през нощта?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, при водачите на възраст под 30 години","ok":false,"i":null,"es":"sí, en conductores menores de 30 años"},{"t":"да, при водачите на възраст над 50 години","ok":true,"i":null,"es":"sí, en conductores mayores de 50 años"},{"t":"възрастта е без значение","ok":false,"i":null,"es":"la edad no tiene importancia"}],"f":2,"es":"¿Afecta la edad a la capacidad de ver de noche?","explain":"Sí, en mayores de 50 años: con la edad el ojo pierde capacidad de adaptación a la oscuridad y sensibilidad al contraste. Los menores de 30 son precisamente los que mejor ven de noche."},{"id":6143,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"намаляване на бдителността","ok":true,"i":null,"es":"la disminución de la atención (vigilancia)"},{"t":"понижаване на устойчивостта на вниманието","ok":true,"i":null,"es":"la disminución de la estabilidad de la atención"},{"t":"повишаване на концентрацията на вниманието","ok":false,"i":null,"es":"el aumento de la concentración de la atención"},{"t":"проблеми с обработването на информацията","ok":true,"i":null,"es":"problemas para procesar la información"}],"f":2,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Fatiga: cae la atención, cae su estabilidad (te 'vas' a ratos) y cuesta procesar la información. El 'aumento de la concentración' es el distractor invertido de rigor en esta serie."},{"id":6148,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"ускоряване на реакциите","ok":false,"i":null,"es":"la aceleración de las reacciones"},{"t":"чувство на неспокойство","ok":true,"i":null,"es":"sensación de inquietud"},{"t":"поява на раздразнителност","ok":true,"i":null,"es":"aparición de irritabilidad"},{"t":"отпадналост","ok":true,"i":null,"es":"decaimiento (debilidad)"}],"f":2,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Fatiga también es: inquietud, irritabilidad y decaimiento: el estado de ánimo avisa antes que el sueño. La 'aceleración de las reacciones' sería lo contrario: descarte inmediato."},{"id":6149,"bg":"Кой от изброените факти е признак за умора на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"честото прозяване","ok":true,"i":null,"es":"bostezar con frecuencia"},{"t":"парене в очите","ok":true,"i":null,"es":"escozor en los ojos"},{"t":"зрението започва да се замъглява","ok":true,"i":null,"es":"la vista empieza a nublarse"},{"t":"ускоряване на реакциите","ok":false,"i":null,"es":"la aceleración de las reacciones"}],"f":2,"es":"¿Cuál de los hechos indicados es un signo de fatiga del conductor? (3 correctas)","explain":"Signos físicos de fatiga: bostezos frecuentes, escozor de ojos y vista que se nubla: el cuerpo pidiendo parar. Las 'reacciones aceleradas' vuelven a ser el espejo falso de la serie."},{"id":6019,"bg":"Движещите се по пътя три- и четириколесни моторни превозни средства трябва да бъдат оборудвани:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"със светлоотразителна жилетка","ok":true,"i":null,"es":"chaleco reflectante"},{"t":"с обезопасителен триъгълник","ok":true,"i":null,"es":"triángulo de seguridad"},{"t":"с въже за теглене","ok":false,"i":null,"es":"con cuerda de remolque"},{"t":"с пожарогасител","ok":true,"i":null,"es":"con extintor"}],"f":2,"es":"Los vehículos de motor de tres y cuatro ruedas que circulan por la vía deben estar equipados: (3 correctas)","explain":"Equipamiento obligatorio de los de tres y cuatro ruedas: chaleco reflectante, triángulo y extintor (más el botiquín). La cuerda de remolque es opcional: útil, pero la ley no la exige."},{"id":5459,"bg":"Извършва ли нарушение водач, който управлява МПС с неизправно устройство за подаване на звуков сигнал?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":2,"es":"¿Comete infracción el conductor que conduce un vehículo con el dispositivo de señal acústica averiado?","explain":"Sí: el claxon averiado es infracción: es un dispositivo obligatorio de seguridad (tu única forma de aviso sonoro de emergencia). Igual que las luces, debe funcionar siempre."},{"id":5478,"bg":"Водач на МПС, който при движение наруши правилата за използване на светлините, се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"във всички случаи","ok":true,"i":null,"es":"en todos los casos"},{"t":"само ако в резултат на това е настъпило ПТП","ok":false,"i":null,"es":"solo si como consecuencia se ha producido un accidente"},{"t":"само ако е създадена непосредствена опасност за движението","ok":false,"i":null,"es":"solo si se ha creado un peligro inmediato para el tráfico"}],"f":2,"es":"El conductor que durante la marcha infringe las normas de uso de las luces se sanciona:","explain":"En todos los casos: infringir las normas de uso de las luces se sanciona por sí mismo, sin esperar accidente ni peligro inmediato. Las luces son visibilidad: la norma castiga el riesgo, no el resultado."},{"id":5488,"bg":"Контролните органи временно отнемат свидетелството за управление на МПС на водач:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за когото видимо се установи, че не отговаря на медицинските изисквания","ok":true,"i":null,"es":"de quien se aprecie visiblemente que no cumple los requisitos médicos"},{"t":"за когото видимо се установи, че не отговаря на психологическите изисквания","ok":true,"i":null,"es":"de quien se aprecie visiblemente que no cumple los requisitos psicológicos"},{"t":"когато водачът паркира автомобила на място, където това е забранено","ok":false,"i":null,"es":"cuando el conductor estaciona el automóvil en un lugar donde está prohibido"},{"t":"когато не е заплатена необходимата винетна такса","ok":false,"i":null,"es":"cuando no se ha pagado la viñeta obligatoria"}],"f":2,"es":"Las autoridades de control retiran temporalmente el permiso de conducción al conductor: (2 correctas)","explain":"Retirada temporal del permiso a quien VISIBLEMENTE no cumple los requisitos médicos o psicológicos: no está en condiciones de conducir ahora mismo. El mal estacionamiento y la viñeta impagada se multan, pero no tocan el permiso."},{"id":11407,"bg":"Контролните органи не допускат управлението на моторно превозно средство от водач, който:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не е заплатил задължителната застраховка „Гражданска отговорност“ на автомобилиста","ok":false,"i":null,"es":"no ha pagado el seguro obligatorio de responsabilidad civil del automovilista"},{"t":"откаже да му бъде извършена проверка с техническо средство за установяване употребата на алкохол","ok":true,"i":null,"es":"se niegue al control con dispositivo técnico para detectar el consumo de alcohol"},{"t":"не изпълни предписанието за медицинско изследване за употребата на наркотични вещества","ok":true,"i":null,"es":"no cumpla la orden de someterse a un examen médico de consumo de drogas"}],"f":2,"es":"Las autoridades de control no permiten la conducción del vehículo de motor por un conductor que: (2 correctas)","explain":"No permiten seguir conduciendo a quien se niega al control de alcohol o incumple la orden del examen de drogas: la negativa se trata como positivo y el conductor no sigue. El seguro impagado se sanciona, pero no impide físicamente continuar en ese momento."},{"id":11415,"bg":"Водач, който ползва пътищата, отворени за обществено ползване за други цели, освен в съответствие с тяхното предназначение се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"}],"f":2,"es":"El conductor que usa las vías públicas para fines distintos a la circulación es sancionado con:","explain":"Usar las vías para fines ajenos a la circulación (carreras, pruebas, exhibiciones): multa Y privación del permiso: sanción combinada, como todas las infracciones que convierten la vía pública en pista."},{"id":11503,"bg":"Контролните органи прекратяват регистрацията на пътно превозно средство на собственик:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"който, като водач откаже да му бъде извършена проверка с техническо средство за установяване употребата на алкохол","ok":true,"i":null,"es":"que, como conductor, se niegue al control con dispositivo técnico para detectar el consumo de alcohol"},{"t":"чието МПС е управлявано от лице, непритежаващо съответното свидетелство за управление","ok":true,"i":null,"es":"cuyo vehículo sea conducido por una persona sin el permiso de conducción correspondiente"},{"t":"превиши максимално разрешената скорост в населено място над 50 km/h","ok":false,"i":null,"es":"supere la velocidad máxima permitida en poblado en más de 50 km/h"},{"t":"участва в нерегламентирани състезания по пътищата, отворени за обществено ползване","ok":false,"i":null,"es":"participe en carreras ilegales en vías abiertas al uso público"}],"f":2,"es":"Las autoridades de control dan de baja la matriculación del vehículo del propietario: (2 correctas)","explain":"Baja de matriculación: cuando el propietario-conductor se niega al control de alcohol, y también cuando SU vehículo lo conduce alguien sin el permiso correspondiente: el dueño responde de a quién presta el coche. Velocidad y carreras tienen otras sanciones."},{"id":5346,"bg":"При ПТП, в което е участник, водачът:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"трябва да спре, за да установи какви са последиците от произшествието","ok":true,"i":null,"es":"debe detenerse para comprobar cuáles son las consecuencias del accidente"},{"t":"не е задължен да спира, ако прецени, че щетите не са големи","ok":false,"i":null,"es":"no está obligado a detenerse si considera que los daños no son grandes"},{"t":"може да продължи движението си, ако на мястото на произшествието е забранено паркирането","ok":false,"i":null,"es":"puede continuar la marcha si en el lugar del accidente está prohibido estacionar"}],"f":2,"es":"En un accidente en el que está implicado, el conductor:","explain":"Implicado en accidente: DEBES detenerte y comprobar las consecuencias, siempre. Ni 'los daños parecen pequeños' ni 'aquí está prohibido estacionar' te eximen: seguir sin parar es fuga del lugar del accidente."},{"id":6199,"bg":"Кой от пътните знаци означава път с еднопосочно движение след знака?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334698.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334694.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45988.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45968.png","es":""}],"f":2,"es":"¿Cuál de las señales indica vía de sentido único después de ella?","explain":"LA PRIMERA: CUADRADO AZUL CON UNA FLECHA HACIA ARRIBA. Una sola correcta.\n\nQUÉ VES. Cuatro señales azules: 1) CUADRADO con una flecha hacia arriba; 2) CÍRCULO con una flecha hacia arriba; 3) cuadrado con tres flechas, la tercera nace de la segunda (empieza un carril); 4) cuadrado con tres carriles y una señal de prohibido camiones en uno.\n\nEL CUADRADO AZUL CON UNA FLECHA informa de que la calle es de SENTIDO ÚNICO.\n\n«EL CÍRCULO» es el cebo fino: OBLIGA a seguir recto, pero no dice que la calle sea de sentido único (compárala con la 6187).\n\nCLAVE: cuadrado azul = información; círculo azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6285,"bg":"Кой знак сигнализира за забрана?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55794.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42087.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55796.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55797.png","es":""}],"f":2,"es":"¿Qué señal señaliza una prohibición? (2 correctas)","explain":"Las senales de prohibicion son circulos rojos. Las informativas son azules."},{"id":5976,"bg":"Кой от пътните знаци забранява навлизането на товарни автомобили след него?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"334703","es":""},{"t":"","ok":false,"i":"334736","es":""},{"t":"","ok":false,"i":"51669","es":""},{"t":"","ok":true,"i":"334705","es":""}],"f":2,"es":"¿Cuál de las señales prohíbe la entrada de camiones después de ella? (2 correctas)","explain":"LA PRIMERA Y LA CUARTA: LA DIRECCIÓN PROHIBIDA Y EL COCHE EN EL CÍRCULO. Dos correctas.\n\nQUÉ VES. Cuatro señales: 1) círculo ROJO con barra BLANCA; 2) círculo con un camión rojo y un coche (prohibido adelantar a los camiones); 3) círculo con un vehículo con remolque; 4) círculo con la silueta de un COCHE.\n\nLAS DOS PROHÍBEN ENTRAR AL CAMIÓN: la barra blanca prohíbe la entrada a todos en ese sentido, y el coche en el círculo, a todos los vehículos de motor (salvo motos sin sidecar y ciclomotores).\n\n«EL CAMIÓN ADELANTANDO» prohíbe adelantar, no entrar. «EL REMOLQUE» solo prohíbe a quien lleve remolque.\n\nCLAVE: el coche dibujado representa a todos los vehículos de motor, camiones incluidos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6284,"bg":"Кой знак сигнализира за забрана?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334715.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55742.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55743.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55744.png","es":""}],"f":2,"es":"¿Qué señal señaliza una prohibición? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA: PROHIBIDO ADELANTAR Y ADUANA. Dos correctas.\n\nQUÉ VES. Cuatro señales: 1) círculo con borde ROJO y dos coches (prohibido adelantar); 2) círculo con borde ROJO y «МИТНИЦА / DOUANE» (prohibido pasar sin detenerse); 3) cuadrado azul con una T (calle sin salida); 4) círculo AZUL con «30» tachado (fin de la velocidad mínima obligatoria).\n\nLAS PROHIBICIONES SON CÍRCULOS CON BORDE ROJO: las dos primeras.\n\n«LA T AZUL» es información. «EL 30 AZUL TACHADO» es el fin de una OBLIGACIÓN (velocidad mínima), no una prohibición.\n\nCLAVE: borde rojo = prohibición; fondo azul = obligación o información. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5523,"bg":"С кой от опознавателните знаци се обозначава бавнодвижещо се МПС?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"i":"23615","es":""},{"t":"","ok":false,"i":"334737","es":""},{"t":"","ok":false,"i":"23614","es":""},{"t":"","ok":true,"i":"334738","es":""}],"f":2,"es":"¿Con cuál de los signos distintivos se identifica un vehículo lento?","explain":"LA ÚLTIMA: EL TRIÁNGULO ROJO. Una sola correcta.\n\nQUÉ VES. Cuatro distintivos: 1) círculo amarillo con tres puntos negros; 2) panel NARANJA «33 / 1088»; 3) placa vertical de franjas rojas y amarillas; 4) TRIÁNGULO ROJO fluorescente con borde reflectante.\n\nEL TRIÁNGULO ROJO lo lleva detrás el vehículo LENTO (tractores, máquinas, vehículos que no pueden ir rápido).\n\n«EL PANEL NARANJA» es el de la mercancía peligrosa. «EL CÍRCULO AMARILLO DE TRES PUNTOS» es el distintivo «Глух или глухоням водач» («conductor sordo o sordomudo»). «LA PLACA DE FRANJAS» es de vehículo largo o pesado.\n\nCLAVE: compárala con la 5526 (los mismos distintivos)."},{"id":5288,"bg":"Кой от пътните знаци предупреждава за приближаване към железопътен прелез с бариери?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334680.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334679.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334681.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21411.png","es":""}],"f":2,"es":"¿Cuál de las señales advierte de la proximidad de un paso a nivel con barreras?","explain":"LA PRIMERA: TRIÁNGULO CON UNA VALLA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) triángulo con una VALLA (barrera); 2) triángulo con una LOCOMOTORA; 3) cruz de San Andrés doble; 4) signo de exclamación.\n\nLA BARRERA DIBUJADA = PASO A NIVEL CON BARRERAS.\n\n«LA LOCOMOTORA» es el paso a nivel SIN barreras. «LA CRUZ DOBLE» va en el propio paso sin barreras de dos o más vías.\n\nCLAVE: compárala con la 5286 y la 5287. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5482,"bg":"При светване на кой от символите върху арматурното табло има опасност от сериозна повреда в двигателя, ако не преустановите движението?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"334684"},{"t":"","ok":false,"es":"","i":"334683"},{"t":"","ok":true,"es":"","i":"29975"},{"t":"","ok":false,"es":"","i":"29956"}],"f":2,"es":"¿Con el encendido de cuál de los símbolos del cuadro de instrumentos existe peligro de avería grave del motor si no detiene la marcha? (2 correctas)","explain":"LA ACEITERA Y EL TERMÓMETRO. Dos correctas.\n\nQUÉ VES. Cuatro testigos rojos: 1) una ACEITERA (presión de aceite); 2) una BATERÍA (carga); 3) un TERMÓMETRO sumergido en ondas (temperatura del refrigerante); 4) un símbolo con tres flechas verticales y líneas onduladas.\n\nLOS DOS QUE PUEDEN ROMPER EL MOTOR: sin presión de aceite se gripa; con el refrigerante sobrecalentado, se deforma la culata y se daña la junta. En los dos casos, paras y apagas.\n\n«LA BATERÍA» indica que no carga: el coche acabará parándose, pero el motor no se rompe por ello.\n\nCLAVE: compárala con la 5480 y la 5483."},{"id":11609,"bg":"Кой от пътните знаци сигнализира за болница със звено за спешна медицинска помощ?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123581411.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086161515.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086161516.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086161517.png","es":""}],"f":2,"es":"¿Cuál de las señales señaliza un hospital con servicio de urgencias?","explain":"LA PRIMERA: «H» CON EL TELÉFONO «112». Una sola correcta.\n\nQUÉ VES. Cuatro señales azules: 1) «H» con un teléfono rojo y «112» debajo; 2) una CRUZ ROJA; 3) una «H» sola; 4) una CAMA.\n\nLA «H» + 112 = HOSPITAL CON SERVICIO DE URGENCIAS.\n\n«LA H SOLA» es un hospital, sin indicar urgencias (compárala con la 11681). «LA CRUZ ROJA» es un puesto de primeros auxilios. «LA CAMA» es un hotel o motel.\n\nCLAVE: 112 = urgencias. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6189,"bg":"На кой от пътните знаци значението е “Движение само надясно след знака”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45433.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45434.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45435.png","es":""}],"f":2,"es":"¿En cuál de las señales el significado es 'Circulación obligatoria solo a la derecha después de la señal'?","explain":"LA PRIMERA: CÍRCULO AZUL CON FLECHA QUE GIRA A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Tres círculos azules: 1) flecha que sube y GIRA a la derecha; 2) flecha HORIZONTAL a la derecha; 3) flecha OBLICUA hacia abajo a la derecha.\n\nLA FLECHA QUE GIRA obliga a girar a la derecha DESPUÉS de la señal, en el cruce siguiente.\n\n«LA FLECHA HORIZONTAL» obliga a girar ANTES de la señal (compárala con la 6190).\n\n«LA FLECHA OBLICUA» indica por qué lado rodear un obstáculo.\n\nCLAVE: compárala con la 6188 y la 6190. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6281,"bg":"Коя от допълнителните табели указва посока към обект и разстояние до него?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55666.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55667.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55668.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55669.png","es":""}],"f":2,"es":"¿Cuál de las tablillas adicionales indica dirección hacia un objeto y distancia hasta él?","explain":"LA PRIMERA: FLECHA HORIZONTAL CON «100 m». Una sola correcta.\n\nQUÉ VES. Cuatro señales con placa: 1) «i» (información) con una placa con una flecha a la IZQUIERDA y «100 m»; 2) estrechamiento con «↑ 200 m ↑»; 3) prohibido estacionar con una flecha vertical y «10 m»; 4) prohibida la parada y el estacionamiento con una flecha horizontal sola.\n\nLA FLECHA DICE HACIA DÓNDE y LA CIFRA, A QUÉ DISTANCIA: el punto de información está a 100 m a la izquierda.\n\n«↑ 200 m ↑» indica la LONGITUD del tramo peligroso. «LA FLECHA VERTICAL CON 10 m» y «LA FLECHA HORIZONTAL» indican la zona en la que vale la prohibición.\n\nCLAVE: flecha lateral + cifra = dirección y distancia. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5977,"bg":"Кой от пътните знаци забранява навлизането на товарни автомобили след него?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"334705","es":""},{"t":"","ok":false,"i":"334708","es":""},{"t":"","ok":true,"i":"334704","es":""},{"t":"","ok":false,"i":"51687","es":""}],"f":2,"es":"¿Cuál de las señales prohíbe la entrada de camiones después de ella? (2 correctas)","explain":"LA PRIMERA Y LA TERCERA: EL COCHE EN EL CÍRCULO Y EL CÍRCULO VACÍO. Dos correctas.\n\nQUÉ VES. Cuatro señales: 1) círculo con la silueta de un COCHE; 2) círculo con un vehículo con REMOLQUE; 3) círculo BLANCO sin dibujo; 4) círculo con una MOTOCICLETA.\n\nLAS DOS PROHÍBEN ENTRAR AL CAMIÓN: el coche (todos los vehículos de motor salvo motos sin sidecar y ciclomotores) y el círculo vacío (todos los vehículos).\n\n«EL REMOLQUE» solo afecta a quien lo lleva. «LA MOTO» solo a motos y ciclomotores.\n\nCLAVE: compárala con la 5976. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5329,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"129037"},{"t":"","ok":false,"es":"","i":"129040"},{"t":"","ok":true,"es":"","i":"129039"},{"t":"","ok":false,"es":"","i":"129038"}],"f":2,"es":"¿Cuál de los vehículos mostrados es un automóvil? (2 correctas)","explain":"EL CAMIÓN HORMIGONERA Y EL TURISMO. Dos correctas.\n\nQUÉ VES. Cuatro vehículos: 1) un camión HORMIGONERA; 2) un TRACTOR agrícola; 3) un TURISMO; 4) una máquina cargadora con un brazo y una pinza.\n\n«AUTOMÓVIL» ES CUALQUIER VEHÍCULO DE MOTOR PARA TRANSPORTAR PERSONAS O MERCANCÍAS O PARA REMOLCAR: el camión y el turismo lo son, sean del tamaño que sean.\n\n«EL TRACTOR» es el cebo: para la ley es una categoría propia, no un automóvil.\n\n«LA MÁQUINA CARGADORA» es una máquina autopropulsada de trabajo, tampoco un automóvil.\n\nCLAVE: compárala con la 5324."},{"id":5954,"bg":"На кой от пътните знаци значението е “Двупосочно движение!”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42719.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42720.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42721.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42722.png","es":""}],"f":2,"es":"¿En cuál de las señales el significado es 'Circulación en doble sentido'?","explain":"LA PRIMERA: TRIÁNGULO CON DOS FLECHAS NEGRAS. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) TRIÁNGULO con flechas negras arriba y abajo; 2) CÍRCULO con flecha negra hacia abajo y roja hacia arriba; 3) CUADRADO AZUL con flecha roja hacia abajo y blanca hacia arriba; 4) panel blanco con tres flechas (dos hacia arriba y una hacia abajo: carriles por sentido).\n\nLAS SEÑALES DE FLECHAS ENFRENTADAS, QUE SE CONFUNDEN:\n• TRIÁNGULO con dos flechas negras = «Circulación en ambos sentidos» (aviso: se acaba la calzada de sentido único);\n• CÍRCULO con borde rojo, flecha NEGRA hacia abajo y ROJA hacia arriba = «Cede el paso a los que vienen de frente»;\n• CUADRADO AZUL, flecha ROJA hacia abajo y BLANCA hacia arriba = «Pasa si la vía está libre»: en un paso estrecho tienes preferencia, pero solo entras si no hay ya nadie dentro.\n\n«EL PANEL DE TRES FLECHAS» indica cuántos carriles hay en cada sentido.\n\nCLAVE: triángulo = aviso. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5960,"bg":"На кой от пътните знаци значението е “Премини, ако пътят е свободен!”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46322.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46285.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46324.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334693.png","es":""}],"f":2,"es":"¿En cuál de las señales el significado es 'Pasa si el camino está libre'?","explain":"LA PRIMERA: CUADRADO AZUL CON FLECHA ROJA HACIA ABAJO Y BLANCA HACIA ARRIBA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) CUADRADO AZUL con flecha roja hacia abajo y blanca hacia arriba; 2) CÍRCULO con flecha negra hacia abajo y roja hacia arriba; 3) TRIÁNGULO con dos flechas negras; 4) triángulo invertido (ceda el paso).\n\nLAS SEÑALES DE FLECHAS ENFRENTADAS, QUE SE CONFUNDEN:\n• TRIÁNGULO con dos flechas negras = «Circulación en ambos sentidos» (aviso: se acaba la calzada de sentido único);\n• CÍRCULO con borde rojo, flecha NEGRA hacia abajo y ROJA hacia arriba = «Cede el paso a los que vienen de frente»;\n• CUADRADO AZUL, flecha ROJA hacia abajo y BLANCA hacia arriba = «Pasa si la vía está libre»: en un paso estrecho tienes preferencia, pero solo entras si no hay ya nadie dentro.\n\n«EL CÍRCULO» es su pareja al revés: el que lo ve cede. «EL TRIÁNGULO» solo avisa del doble sentido. «EL TRIÁNGULO INVERTIDO» es ceder a la vía con prioridad.\n\nCLAVE: la flecha de tu sentido (hacia arriba) es la BLANCA = tú pasas primero, pero solo si el paso está libre. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5472,"bg":"Светването на този символ върху арматурното табло означава, че са включени:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29459.png","v":null,"a":[{"t":"дългите светлини","ok":true,"i":null,"es":"las luces largas"},{"t":"аварийните светлини","ok":false,"i":null,"es":"las luces de emergencia"},{"t":"габаритните светлини","ok":false,"i":null,"es":"las luces de posición"},{"t":"късите светлини","ok":false,"i":null,"es":"las luces cortas (de cruce)"}],"f":1,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que están encendidas:","explain":"LAS LUCES LARGAS. Una sola correcta.\n\nQUÉ VES. Un testigo AZUL con un faro y rayos HORIZONTALES rectos.\n\nAZUL CON RAYOS RECTOS = LUCES LARGAS (de carretera).\n\n«LUCES DE EMERGENCIA» es un triángulo rojo. «LUCES DE POSICIÓN» y «LUCES CORTAS» tienen testigos verdes; las cortas, con los rayos inclinados hacia abajo.\n\nCLAVE: el único testigo de luces que es azul es el de las largas."},{"id":5484,"bg":"Проверката на нивото на маслото в картера на двигателя се извършва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при неработещ двигател","ok":true,"i":null,"es":"con el motor apagado"},{"t":"при работещ двигател в режим на средни натоварвания","ok":false,"i":null,"es":"con el motor en marcha a carga media"},{"t":"при работещ двигател, без натоварване","ok":false,"i":null,"es":"con el motor en marcha, sin carga"}],"f":1,"es":"La comprobación del nivel de aceite del cárter del motor se realiza:","explain":"Con el motor APAGADO (y en llano, tras unos minutos de reposo): la varilla mide el aceite asentado en el cárter. Con el motor en marcha el aceite está circulando: la lectura sería falsa y las piezas móviles, un peligro."},{"id":5486,"bg":"При техническото обслужване на автомобила опасност представляват:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"проводниците за високо напрежение","ok":true,"i":null,"es":"los cables de alta tensión"},{"t":"проводниците, с които се подава напрежение към фаровете","ok":false,"i":null,"es":"los cables que llevan tensión a los faros"},{"t":"проводниците, с които се подава напрежение към стоп-светлините","ok":false,"i":null,"es":"los cables que llevan tensión a las luces de freno"},{"t":"проводниците с червен цвят","ok":false,"i":null,"es":"los cables de color rojo"}],"f":1,"es":"En el mantenimiento técnico del automóvil, un peligro son:","explain":"Los cables de ALTA TENSIÓN (sistema de encendido: bobina, bujías): dan descargas de miles de voltios incluso con el motor parado. Los cables de faros o frenos llevan 12 V inofensivos, y el color no indica peligro."},{"id":5176,"bg":"Кои от изброените пътни превозни средства са моторни?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"мотопедите","ok":true,"i":null,"es":"los ciclomotores"},{"t":"велосипедите","ok":false,"i":null,"es":"las bicicletas"},{"t":"тракторите","ok":true,"i":null,"es":"los tractores"},{"t":"тролейбусите","ok":true,"i":null,"es":"los trolebuses"}],"f":1,"es":"¿Cuáles de los siguientes vehículos de carretera son vehículos de motor? (3 correctas)","explain":"Vehículos de MOTOR: ciclomotores, tractores y trolebuses: tienen motor propio y no van sobre raíles. La bicicleta no tiene motor: es vehículo, pero no de motor."},{"id":5177,"bg":"Кои от изброените пътни превозни средства са моторни?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"мотопедите","ok":true,"i":null,"es":"los ciclomotores"},{"t":"автомобилите","ok":true,"i":null,"es":"los automóviles"},{"t":"тракторите","ok":true,"i":null,"es":"los tractores"},{"t":"трамваите","ok":false,"i":null,"es":"los tranvías"}],"f":1,"es":"¿Cuáles de los siguientes vehículos de carretera son vehículos de motor? (3 correctas)","explain":"De motor: ciclomotores, automóviles y tractores. El TRANVÍA no: circula sobre raíles y la ley lo equipara a los vehículos (ППС) pero lo excluye de los de motor (МПС): la distinción estrella de este bloque."},{"id":5178,"bg":"Кои от изброените пътни превозни средства са моторни?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"автомобилите","ok":true,"i":null,"es":"los automóviles"},{"t":"тракторите","ok":true,"i":null,"es":"los tractores"},{"t":"велосипедите","ok":false,"i":null,"es":"las bicicletas"},{"t":"трамваите","ok":false,"i":null,"es":"los tranvías"}],"f":1,"es":"¿Cuáles de los siguientes vehículos de carretera son vehículos de motor? (2 correctas)","explain":"De motor: automóviles y tractores. La bicicleta no tiene motor y el tranvía va por raíles: los dos excluidos de siempre, juntos en la misma pregunta."},{"id":5232,"bg":"Пътният банкет е част от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътното платно","ok":true,"i":null,"es":"la plataforma vial (calzada + arcenes)"},{"t":"платното за движение","ok":false,"i":null,"es":"la calzada"},{"t":"най-дясната пътна лента","ok":false,"i":null,"es":"el carril más a la derecha"},{"t":"разделителната ивица","ok":false,"i":null,"es":"la franja divisoria (mediana)"}],"f":1,"es":"El arcen forma parte de:","explain":"El arcén forma parte de la PLATAFORMA VIAL (calzada + arcenes): está construido, pero no es calzada (no es para circular) ni carril ni mediana. La jerarquía calzada ⊂ plataforma ⊂ firme resuelve toda esta familia."},{"id":5298,"bg":"Видимостта е намалена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"здрач","ok":true,"i":null,"es":"el crepúsculo"},{"t":"запрашеност","ok":true,"i":null,"es":"polvo en suspensión"},{"t":"стръмни наклони","ok":false,"i":null,"es":"pendientes pronunciadas"},{"t":"завои","ok":false,"i":null,"es":"curvas"}],"f":1,"es":"La visibilidad esta reducida en: (2 correctas)","explain":"Visibilidad REDUCIDA: crepúsculo y polvo en suspensión: condiciones de luz y aire. Las pendientes y las curvas son visibilidad LIMITADA: geometría. El par de conceptos más rentable del examen, una vez más."},{"id":7848,"bg":"Автомобил, с допустима максимална маса над 3,5 т, е разрешено да се управлява с правоспособност за категория В, ако броят на местата за сядане, без мястото на водача, не надвишават 8.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":1,"es":"Un automóvil con masa máxima admisible superior a 3.5 t se puede conducir con permiso B si el número de asíentos, sin contar el del conductor, no supera 8.","explain":"INCORRECTO: la afirmación mezcla los dos límites del B. El permiso B exige AMBOS: masa máxima hasta 3,5 t Y hasta 8 plazas. Superada la masa, da igual cuántos asientos tenga: ya no es B."},{"id":8226,"bg":"Водач с правоспособност за управление на МПС от категория А1 има право да управлява и МПС от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"категория АМ","ok":true,"i":null,"es":"categoría AM"},{"t":"категория Ткт","ok":false,"i":null,"es":"categoría Ткт (tractor de ruedas)"},{"t":"категория А2","ok":false,"i":null,"es":"categoría A2"},{"t":"категория А","ok":false,"i":null,"es":"categoría A"}],"f":1,"es":"El conductor con permiso categoría A1 tiene derecho a conducir vehículos de:","explain":"El A1 incluye la categoría AM (la inferior de las dos ruedas). No da acceso a A2 ni A (superiores) ni a tractores: las categorías incluyen hacia abajo, nunca hacia arriba."},{"id":8231,"bg":"Водач с правоспособност за управление на МПС от категория В има право да управлява и МПС от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"категория АМ","ok":true,"i":null,"es":"categoría AM"},{"t":"категория В1","ok":true,"i":null,"es":"categoría B1"},{"t":"категория Ткт","ok":false,"i":null,"es":"categoría Ткт (tractor de ruedas)"},{"t":"категория А1","ok":false,"i":null,"es":"categoría A1"}],"f":1,"es":"El conductor con permiso categoría B tiene derecho a conducir también vehículos de: (2 correctas)","explain":"El permiso B incluye AM y B1: sus categorías inferiores. No incluye A1 (las motos son otra rama: B no habilita motocicletas) ni Ткт (tractores, rama aparte)."},{"id":11575,"bg":"Коя част от пътя на показаната схема е означена с буквата „А”?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086155016.png","v":null,"a":[{"t":"пътна лента","ok":true,"i":null,"es":"carril"},{"t":"пътното платно","ok":false,"i":null,"es":"la plataforma vial (calzada + arcenes)"},{"t":"платното за движение","ok":false,"i":null,"es":"la calzada"}],"f":1,"es":"¿Qué parte de la carretera del esquema está indicada con la letra 'А'?","explain":"CARRIL. Una sola correcta.\n\nQUÉ VES. Una carretera con un esquema de tres medidas debajo: «А» va desde la línea central hasta el borde derecho de la calzada; «В» abarca toda la calzada; «С», la más ancha, incluye también las franjas oscuras de los lados.\n\nLAS TRES PARTES, SEGÚN EL BANCO:\n• «А» = un CARRIL («пътна лента»): la franja por la que circula una fila de vehículos;\n• «В» = la CALZADA («платно за движение»): la parte por la que circulan los vehículos, entre las líneas de borde;\n• «С» = la PLATAFORMA («пътно платно»): la calzada más las franjas laterales (arcenes).\n\n«LA CALZADA» es «В». «ПЪТНО ПЛАТНО» es «С».\n\nCLAVE: compárala con la 11579 y la 11580."},{"id":11812,"bg":"Към МПС от категория В принадлежат товарните автомобили с допустима максимална маса не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"3500 kg","ok":true,"i":null,"es":"3500 kg"},{"t":"2500 kg","ok":false,"i":null,"es":"2500 kg"},{"t":"4500 kg","ok":false,"i":null,"es":"4500 kg"},{"t":"7500 kg","ok":false,"i":null,"es":"7500 kg"}],"f":1,"es":"Los automóviles categoría B tienen una masa máxima admisible no superior a:","explain":"3.500 kg: la masa máxima admisible que define el techo de la categoría B. 7.500 es el techo del C1: el par 3.500/7.500 delimita las categorías de camión ligero."},{"id":11865,"bg":"Разрешено ли е водач с правоспособност за категория В да управлява товарен автомобил?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да, когато допустимата му максимална маса не надвишава 3,5 t","ok":true,"i":null,"es":"sí, cuando la masa máxima autorizada no supera 3.5 t"},{"t":"да, когато масата му с товар не надвишава 3,5 t","ok":false,"i":null,"es":"sí, cuando la masa CON CARGA no supera 3.5 t"},{"t":"да, когато масата на товара не надвишава 3,5 t","ok":false,"i":null,"es":"sí, cuando la carga no supera 3.5 t"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":1,"es":"¿Está permitido al titular del permiso B conducir un camión?","explain":"Sí, con masa máxima AUTORIZADA hasta 3,5 t: el criterio es la cifra del permiso de circulación, no el peso real con carga ni el peso de la carga. Un 'camión' pequeño de 3,5 t MMA es territorio B."},{"id":5191,"bg":"При движение на превозното средство в завой, с висока скорост, най-опасно е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"възможното странично хлъзгане на автомобила","ok":true,"i":null,"es":"el posible deslizamiento lateral del automóvil"},{"t":"ускореното неправилно износване на протектора на гумите","ok":false,"i":null,"es":"el desgaste acelerado e irregular de la banda de rodadura de los neumáticos"},{"t":"ускореното износване на кормилната уредба","ok":false,"i":null,"es":"el desgaste acelerado de la dirección"},{"t":"ускореното износване на окачването","ok":false,"i":null,"es":"el desgaste acelerado de la suspensión"}],"f":1,"es":"Al circular en curva a alta velocidad, el peligro principal es:","explain":"El peligro principal de la curva rápida es el DESLIZAMIENTO LATERAL: la fuerza centrífuga vence a la adherencia y el coche se va de trayectoria. Los desgastes (neumáticos, dirección, suspensión) son costes a largo plazo, no el peligro inmediato."},{"id":5213,"bg":"При тази ситуация пътните знаци сигнализират, че:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22948.png","v":null,"a":[{"t":"следва участък от пътя с концентрация на пътнотранспортни произшествия","ok":true,"i":null,"es":"sigue un tramo de vía con concentración de accidentes de tráfico"},{"t":"следва участък от пътя в ремонт","ok":false,"i":null,"es":"sigue un tramo de vía en obras"},{"t":"съществува опасност от паднали камъни на пътя","ok":false,"i":null,"es":"existe peligro de piedras caídas en la vía"},{"t":"след завоя пътят навлиза в тунел","ok":false,"i":null,"es":"después de la curva la vía entra en un túnel"}],"f":1,"es":"En esta situación las señales indican que:","explain":"SIGUE UN TRAMO DE VÍA CON CONCENTRACIÓN DE ACCIDENTES DE TRÁFICO. Una sola correcta.\n\nQUÉ VES. Carretera de montaña con una curva. A AMBOS LADOS de la calzada, dos triángulos con fondo AMARILLO fluorescente y un gran PUNTO NEGRO.\n\nEL PUNTO NEGRO ES EL «PUNTO NEGRO» DE LA CARRETERA: un tramo donde se producen muchos accidentes. Se pone a los dos lados para que no pase desapercibido.\n\n«OBRAS» lleva un trabajador con pala. «PIEDRAS CAÍDAS» lleva una ladera con piedras. «TÚNEL» lleva la boca de un túnel.\n\nCLAVE: compárala con la 5210 (la misma señal sola). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5292,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334682.png","v":null,"a":[{"t":"сигнализира, че железопътният прелез е с един коловоз","ok":true,"i":null,"es":"indica que el paso a nivel tiene UNA vía"},{"t":"забранява навлизането срещу знака","ok":false,"i":null,"es":"prohíbe entrar en dirección contraria"},{"t":"предупреждава за кръстовище на равнозначни пътища","ok":false,"i":null,"es":"advierte de intersección de vías equivalentes"},{"t":"сигнализира, че железопътният прелез е с два или повече коловоза","ok":false,"i":null,"es":"indica que el paso a nivel tiene DOS O MÁS vías"}],"f":1,"es":"Esta señal:","explain":"INDICA QUE EL PASO A NIVEL TIENE UNA SOLA VÍA. Una sola correcta.\n\nLA SEÑAL. Cruz de San Andrés SIMPLE, roja y blanca.\n\nLA CRUZ SIMPLE se coloca en el paso a nivel sin barreras de una sola vía.\n\n«DOS O MÁS VÍAS» es la cruz doble. «PROHIBIDA LA ENTRADA» es el círculo rojo con barra blanca. «CRUCE DE VÍAS IGUALES» es la X dentro de un triángulo.\n\nCLAVE: compárala con la 5290 y la 5293. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5522,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23594.png","v":null,"a":[{"t":"бавнодвижещи се МПС","ok":true,"i":null,"es":"vehículos lentos"},{"t":"извънгабаритни МПС","ok":false,"i":null,"es":"vehículos de motor de dimensiones excepcionales"},{"t":"МПС, превозващи опасни товари","ok":false,"i":null,"es":"vehículos que transportan mercancías peligrosas"},{"t":"МПС превозващи насипни товари","ok":false,"i":null,"es":"vehículos de motor que transportan cargas a granel"}],"f":1,"es":"Con este signo distintivo se identifican:","explain":"VEHÍCULOS LENTOS. Una sola correcta.\n\nQUÉ VES. Un TRIÁNGULO ROJO fluorescente con borde reflectante, el que va en la parte trasera de un vehículo.\n\nEL TRIÁNGULO ROJO identifica a los VEHÍCULOS LENTOS: los que, por construcción, no pueden ir rápido (tractores, máquinas).\n\n«DIMENSIONES EXCEPCIONALES», «MERCANCÍAS PELIGROSAS» (panel naranja) y «CARGAS A GRANEL» son cebos con otros distintivos o ninguno.\n\nCLAVE: compárala con la 5523. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6063,"bg":"Разрешено ли е при извършване на маневра да подавате допълнителен сигнал чрез кратковременно включване на светлините?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":1,"es":"¿Esta permitido al hacer una maniobra dar señal adicional con el encendido breve de las luces?","explain":"Sí: el destello breve de las luces es una señal adicional permitida al maniobrar (típicamente para avisar del adelantamiento). Complementa al intermitente: nunca lo sustituye."},{"id":12024,"bg":"Какъв е правилният начин на действие?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":8,"a":[{"t":"изпреварвам синия автомобил и преминавам в дясната лента","ok":true,"i":null,"es":"adelanto al azul y paso al carril derecho"},{"t":"намалявам скоростта, за да подканя превозното средство, което се движи след мен, да спазва необходимата дистанция","ok":false,"i":null,"es":"reduzco la velocidad para invitar al vehículo que circula detrás de mí a mantener la distancia necesaria"},{"t":"изпреварвам червения автомобил и се придвижвам в дясната лента","ok":false,"i":null,"es":"adelanto al rojo y paso al carril derecho"}],"f":1,"es":"¿Cuál es la actuación correcta?"},{"id":5941,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41308.png","v":null,"a":[{"t":"че е възможно изхвърляне на малки камъни","ok":true,"i":null,"es":"que es posible la proyección de gravilla"},{"t":"за неукрепен пътен банкет","ok":false,"i":null,"es":"de un arcén sin consolidar"},{"t":"за хлъзгав участък от пътя","ok":false,"i":null,"es":"de un tramo de vía deslizante"},{"t":"за неравности по платното за движение","ok":false,"i":null,"es":"de irregularidades (baches) en la calzada"}],"f":1,"es":"Esta señal advierte:","explain":"QUE ES POSIBLE LA PROYECCIÓN DE GRAVILLA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un coche que levanta y lanza PIEDRECITAS al pasar.\n\nAVISA DE GRAVILLA SUELTA en la calzada, que los vehículos proyectan al pasar. Reduces y aumentas la distancia con el de delante.\n\n«ARCÉN SIN CONSOLIDAR» es el coche inclinado sobre el borde. «TRAMO DESLIZANTE» es el coche derrapando. «IRREGULARIDADES» es el perfil con bultos.\n\nCLAVE: piedras saltando = gravilla proyectada. Compárala con la 5248. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5975,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334705.png","v":null,"a":[{"t":"мотоциклети с кош","ok":true,"i":null,"es":"motos con sidecar"},{"t":"мотоциклети без кош","ok":false,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":false,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":false,"i":null,"es":"bicicletas"}],"f":1,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal?","explain":"MOTOS CON SIDECAR. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y la silueta de un COCHE: prohibida la entrada a los vehículos de motor, excepto motos SIN sidecar y ciclomotores.\n\nLA MOTO CON SIDECAR NO ESTÁ EXCEPTUADA: se trata como un coche, así que no puede entrar.\n\n«MOTOS SIN SIDECAR» y «CICLOMOTORES» son justo las excepciones. «BICICLETAS» no tienen motor.\n\nCLAVE: compárala con la 5973 y la 5974. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5989,"bg":"Задължително ли е спирането при този пътен знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51930.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":1,"es":"¿Es obligatoria la parada ante esta señal?","explain":"SÍ.\n\nLA SEÑAL. Círculo BLANCO con borde ROJO, una barra negra y «МИТНИЦА / DOUANE» (aduana).\n\nES «PROHIBIDO PASAR SIN DETENERSE»: tienes que parar en ese punto, aunque no veas a nadie.\n\n«NO» es el cebo de quien la toma por un simple aviso de que hay una aduana.\n\nCLAVE: compárala con la 5990 (la misma señal). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6175,"bg":"Този пътен знак забранява влизането на пътни превозни средства:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52215.png","v":null,"a":[{"t":"с височина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con altura, incluyendo carga, superior a la indicada"},{"t":"с дължина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"с широчина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"}],"f":1,"es":"Esta señal prohíbe la entrada de vehículos:","explain":"CON ALTURA, INCLUIDA LA CARGA, SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con «3,5 m» y dos triángulos negros, uno ARRIBA y otro ABAJO, apuntando al número.\n\nLAS SEÑALES DE TONELADAS Y METROS:\n• solo «3 t» = masa total con carga;\n• «t» sobre un EJE = carga por eje;\n• «m» con flechas ARRIBA y ABAJO = altura; a los LADOS = anchura; con un camión y flechas delante y detrás = longitud.\n\nLAS PUNTAS ARRIBA Y ABAJO = ALTURA: no pueden pasar los vehículos de más de 3,5 m de alto, contando la carga (típica antes de un puente o un túnel bajo).\n\n«LONGITUD», «ANCHURA» y «DISTANCIA ENTRE VEHÍCULOS» tienen las flechas en otra posición o un dibujo distinto.\n\nCLAVE: mira hacia dónde apuntan las puntas. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6182,"bg":"Този пътен знак означава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53426.png","v":null,"a":[{"t":"забрана за движение на дистанция, по-малка от означената","ok":true,"i":null,"es":"prohibición de circular a distancia INFERIOR a la indicada"},{"t":"разстояние между автомобилите при паркиране","ok":false,"i":null,"es":"distancia entre vehículos al aparcar"},{"t":"забрана за движение на дистанция, по-голяма от означената","ok":false,"i":null,"es":"prohibición de circular a distancia SUPERIOR a la indicada"}],"f":1,"es":"Esta señal significa:","explain":"PROHIBICIÓN DE CIRCULAR A UNA DISTANCIA INFERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con dos coches, uno detrás de otro, y «70 m» entre ellos.\n\nPROHÍBE IR MÁS CERCA DE 70 m del vehículo de delante (habitual en puentes y túneles).\n\n«DISTANCIA AL APARCAR» es el cebo: la señal es de circulación, no de estacionamiento.\n\n«DISTANCIA SUPERIOR» es el cebo al revés: lo peligroso es ir demasiado cerca, no demasiado lejos.\n\nCLAVE: cifra entre dos coches = distancia mínima de seguridad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6191,"bg":"Този пътен знак задължава водачите да продължат движението наляво:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46305.png","v":null,"a":[{"t":"пред знака","ok":true,"i":null,"es":"antes de la señal"},{"t":"след знака","ok":false,"i":null,"es":"después de la señal"}],"f":1,"es":"Esta señal obliga a los conductores a continuar la circulación hacia la izquierda:","explain":"ANTES DE LA SEÑAL.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca HORIZONTAL hacia la izquierda.\n\nLA FLECHA HORIZONTAL se coloca delante de ti (al fondo de un cruce en T): tienes que girar a la izquierda ANTES de llegar a ella.\n\n«DESPUÉS DE LA SEÑAL» es el significado de la flecha que sube y GIRA a la izquierda.\n\nCLAVE: horizontal = antes; flecha que gira = después. Compárala con la 6190 (la misma hacia la derecha). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6201,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334698.png","v":null,"a":[{"t":"еднопосочно движение след знака","ok":true,"i":null,"es":"tráfico de SENTIDO ÚNICO después de la señal"},{"t":"забранено е завиването наляво и надясно","ok":false,"i":null,"es":"prohibido girar a la izquierda y a la derecha"},{"t":"задължителна посока за движение","ok":false,"i":null,"es":"dirección OBLIGATORIA"},{"t":"движение само направо след знака","ok":false,"i":null,"es":"solo ir recto después"}],"f":1,"es":"El significado de esta señal es:","explain":"SENTIDO ÚNICO DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. CUADRADO AZUL con una flecha blanca hacia arriba.\n\nEL CUADRADO AZUL INFORMA: la calle que empieza es de sentido único; todos circulan en la dirección de la flecha.\n\n«DIRECCIÓN OBLIGATORIA» y «SOLO RECTO» son el CÍRCULO azul con la misma flecha (6186). «PROHIBIDO GIRAR» serían señales circulares rojas.\n\nCLAVE: compárala con la 6199. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6202,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334699.png","v":null,"a":[{"t":"е указател за предварително престрояване","ok":true,"i":null,"es":"es un indicador de preselección de carril"},{"t":"указва началото на пътна лента","ok":false,"i":null,"es":"indica el inicio de un carril"},{"t":"указва броя на лентите за движение по пътя","ok":false,"i":null,"es":"indica el número de carriles de circulación de la vía"},{"t":"указва, че пътят е с еднопосочно движение след знака","ok":false,"i":null,"es":"indica que la vía es de sentido único después de la señal"}],"f":1,"es":"Esta señal:","explain":"ES UN INDICADOR DE PRESELECCIÓN DE CARRIL. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con dos carriles por sentido: en uno la flecha se abre hacia la IZQUIERDA y en el otro hay una flecha recta y otra que se abre a la DERECHA.\n\nTE DICE QUÉ CARRIL TOMAR ANTES DEL CRUCE según adónde vayas: el izquierdo para girar a la izquierda; el derecho para seguir recto o girar a la derecha.\n\n«INICIO DE UN CARRIL» es la flecha que nace de otra. «NÚMERO DE CARRILES» es el panel de flechas rectas. «SENTIDO ÚNICO» es un cuadrado con una sola flecha.\n\nCLAVE: flechas que se abren por carril = colócate antes del cruce. Ver Leyes → «Adelantar y colocarse antes de una maniobra». Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6214,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46743.png","v":null,"a":[{"t":"край на пътна лента","ok":true,"i":null,"es":"fin de carril"},{"t":"пътна лента в ремонт","ok":false,"i":null,"es":"carril en obras"},{"t":"средна лента за изпреварване в указаната посока","ok":false,"i":null,"es":"carril central para adelantar en el sentido indicado"},{"t":"изход от крайпътен обект","ok":false,"i":null,"es":"salida de un establecimiento junto a la vía"}],"f":1,"es":"Esta señal señaliza:","explain":"FIN DE CARRIL. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con dos flechas hacia arriba: la de la derecha se dobla y se une a la otra.\n\nLA FLECHA QUE SE UNE es un carril que se acaba: los que van por él tienen que incorporarse al de al lado.\n\n«CARRIL EN OBRAS» sería una señal amarilla. «CARRIL CENTRAL PARA ADELANTAR» tiene otro dibujo. «SALIDA DE UN ESTABLECIMIENTO» no es esta señal.\n\nCLAVE: flecha que se une = carril que acaba; flecha que se abre = carril que empieza. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6215,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46796.png","v":null,"a":[{"t":"пътна лента със съоръжение за аварийно спиране","ok":true,"i":null,"es":"carril con dispositivo de frenado de emergencia (lecho de frenado)"},{"t":"пътна лента за бавнодвижещи се ППС","ok":false,"i":null,"es":"carril para vehículos lentos"},{"t":"място за паркиране извън пътното платно","ok":false,"i":null,"es":"lugar de estacionamiento fuera de la plataforma vial"},{"t":"край на пътна лента","ok":false,"i":null,"es":"fin de carril"}],"f":1,"es":"Esta señal señaliza:","explain":"CARRIL CON DISPOSITIVO DE FRENADO DE EMERGENCIA (LECHO DE FRENADO). Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un carril que se separa a la derecha y termina en una zona a CUADROS ROJOS Y BLANCOS.\n\nES UN CARRIL DE ESCAPE para vehículos que se quedan sin frenos, sobre todo en bajadas largas: termina en un lecho de grava o arena que los detiene.\n\n«CARRIL PARA LENTOS» lleva un número de velocidad. «APARCAMIENTO» lleva una «P». «FIN DE CARRIL» es la flecha que se une.\n\nCLAVE: cuadros rojos y blancos al final = escape de emergencia. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6220,"bg":"Пътният знак с допълнителна табела предупреждават че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53872.png","v":null,"a":[{"t":"разстоянието до участъка с последователни опасни завои е 50 м","ok":true,"i":null,"es":"la DISTANCIA hasta el tramo de curvas sucesivas es 50 m"},{"t":"дължината на участъка с последователни опасни завои е 50 м","ok":false,"i":null,"es":"la LONGITUD del tramo de curvas sucesivas es 50 m"},{"t":"разстоянието от знака до края на участъка с последователни завои е 50 м","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo es 50 m"}],"f":1,"es":"La señal y tablilla advierten que:","explain":"LA DISTANCIA HASTA EL TRAMO DE CURVAS SUCESIVAS ES 50 m. Una sola correcta.\n\nQUÉ VES. Carretera con curvas balizadas. A la derecha, el triángulo de CURVAS SUCESIVAS con una placa debajo: «50 m», sin flechas (ampliada en la imagen).\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA LONGITUD ES 50 m» es el cebo: llevaría las flechas (compárala con la 6238).\n\nCLAVE: cifra sola = cuánto falta. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6241,"bg":"Допълнителната табела указва, че забраната, въведена с този знак, важи само:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54125.png","v":null,"a":[{"t":"в неработни дни","ok":true,"i":null,"es":"en días NO laborables"},{"t":"в работни дни","ok":false,"i":null,"es":"en días laborables"}],"f":1,"es":"La tablilla complementaria indica que la prohibición introducida por la señal aplica solo:","explain":"EN DÍAS NO LABORABLES.\n\nQUÉ VES. Señal de PROHIBIDA LA PARADA Y EL ESTACIONAMIENTO con una placa debajo con un MARTILLO Y UNA LLAVE cruzados, TACHADOS con una raya roja.\n\nEL MARTILLO Y LA LLAVE SIMBOLIZAN LOS DÍAS DE TRABAJO. Tachados = días NO laborables: la prohibición solo vale los fines de semana y festivos.\n\n«EN DÍAS LABORABLES» sería la misma placa sin tachar.\n\nCLAVE: herramientas = días laborables; herramientas tachadas = no laborables. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6255,"bg":"Задължителната посока за движение въведена с този пътен знак с допълнителна табела, се отнася за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54554.png","v":null,"a":[{"t":"леките автомобили","ok":true,"i":null,"es":"los turismos"},{"t":"мотоциклетите","ok":true,"i":null,"es":"las motocicletas"},{"t":"автобусите","ok":true,"i":null,"es":"los autobuses"},{"t":"товарните автомобили","ok":false,"i":null,"es":"los camiones"}],"f":1,"es":"La dirección obligatoria introducida por esta señal con tablilla adicional se refiere a: (3 correctas)","explain":"LOS TURISMOS, LAS MOTOCICLETAS Y LOS AUTOBUSES. Tres correctas.\n\nQUÉ VES. Señal circular AZUL de dirección obligatoria RECTO con una placa debajo con un CAMIÓN TACHADO.\n\nCAMIÓN TACHADO = LA OBLIGACIÓN ES PARA TODOS MENOS LOS CAMIONES.\n\n«LOS CAMIONES» es el cebo: son los únicos exceptuados.\n\nCLAVE: compárala con la 6253 y la 6710 (el mismo truco de la placa tachada). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6258,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54709.png","v":null,"a":[{"t":"край на участъка, в който са забранени престоят и паркирането","ok":true,"i":null,"es":"fin del tramo donde están prohibidas la parada y el estacionamiento"},{"t":"начало на участъка, в който е забранено спирането","ok":false,"i":null,"es":"inicio del tramo donde está prohibida la detención"}],"f":1,"es":"La tablilla adicional indica:","explain":"FIN DEL TRAMO DONDE ESTÁN PROHIBIDAS LA PARADA Y EL ESTACIONAMIENTO.\n\nQUÉ VES. Señal de PROHIBIDA LA PARADA Y EL ESTACIONAMIENTO con una placa con una flecha VERTICAL de una sola punta, hacia ABAJO.\n\nLA FLECHA HACIA ABAJO (hacia ti, hacia atrás) dice que la prohibición estaba DETRÁS de la señal: ahí se acaba.\n\n«INICIO DEL TRAMO» llevaría la flecha hacia ARRIBA (hacia delante).\n\nCLAVE: flecha hacia delante = empieza; hacia atrás = termina; dos puntas = sigues dentro (6275). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6260,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54746.png","v":null,"a":[{"t":"край на участъка, в който са забранени престоят и паркирането","ok":true,"i":null,"es":"fin del tramo donde están prohibidas la parada y el estacionamiento"},{"t":"начало на участъка, в който е забранено спирането","ok":false,"i":null,"es":"inicio del tramo donde está prohibida la detención"}],"f":1,"es":"La tablilla adicional indica:","explain":"FIN DEL TRAMO DONDE ESTÁN PROHIBIDAS LA PARADA Y EL ESTACIONAMIENTO.\n\nQUÉ VES. Señal de PROHIBIDA LA PARADA Y EL ESTACIONAMIENTO con una placa con una flecha HORIZONTAL de una sola punta, hacia la DERECHA.\n\nES LA VERSIÓN DE LA 6258 para una señal colocada en paralelo a la calzada. Según el banco, aquí marca el FIN del tramo prohibido.\n\n«INICIO DEL TRAMO» es el cebo: se marca con la flecha en el otro sentido.\n\nCLAVE: compárala con la 6258 y la 6276. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6293,"bg":"При тази ситуация, на какво разстояние след пътния знак се намира пешеходната пътека?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56031.png","v":null,"a":[{"t":"от 50 до 100 м","ok":true,"i":null,"es":"entre 50 y 100 m"},{"t":"до 50 м","ok":false,"i":null,"es":"hasta 50 m"},{"t":"от 100 до 150 м","ok":false,"i":null,"es":"entre 100 y 150 m"},{"t":"на 200 м","ok":false,"i":null,"es":"a 200 m"}],"f":1,"es":"En esta situación, ¿a qué distancia después de la señal está el paso de peatones?","explain":"ENTRE 50 Y 100 m. Una sola correcta.\n\nQUÉ VES. Calle urbana de varios carriles con un coche rojo y un camión delante. A la derecha, el triángulo de PASO DE PEATONES.\n\nEN POBLACIÓN, LAS SEÑALES DE PELIGRO van de 50 a 100 m antes del peligro.\n\n«HASTA 50 m» no deja tiempo para frenar. «100-150 m» es la distancia fuera de población. «200 m» no es la regla.\n\nCLAVE: compárala con la 6288 y la 11888. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6296,"bg":"При тази ситуация забраната за изпреварване, е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56246.png","v":null,"a":[{"t":"до края на стеснения участък от пътя","ok":true,"i":null,"es":"hasta el FIN del tramo estrecho"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"до края на пътя","ok":false,"i":null,"es":"hasta el final de la vía"}],"f":1,"es":"En esta situación la prohibición de adelantamiento es válida:","explain":"HASTA EL FINAL DEL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, un triángulo de ESTRECHAMIENTO y, debajo, la señal de PROHIBIDO ADELANTAR.\n\nLA PROHIBICIÓN VA COLGADA DEL TRIÁNGULO: no se puede adelantar porque la calzada se estrecha, así que la prohibición dura lo que dura el estrechamiento.\n\n«HASTA LA SEÑAL QUE LA CANCELA» y «HASTA LA PRÓXIMA INTERSECCIÓN» son la regla general para una prohibición que va sola. «HASTA EL FINAL DE LA VÍA» la alarga sin motivo.\n\nCLAVE: compárala con la 6297, la 6300 y la 6302. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":12078,"bg":"Освен за трактори, забраната за влизане след този пътен знак се отнася и за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173459315.png","v":null,"a":[{"t":"самоходни машини","ok":true,"i":null,"es":"máquinas autopropulsadas"},{"t":"мотоциклети с кош","ok":false,"i":null,"es":"motos con sidecar"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"},{"t":"автомобили със специално предназначение","ok":false,"i":null,"es":"automóviles de uso especial"}],"f":1,"es":"Además de los tractores, la prohibición de entrar después de esta señal afecta también a:","explain":"MÁQUINAS AUTOPROPULSADAS. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y un TRACTOR.\n\nLA PROHIBICIÓN DEL TRACTOR se extiende a las máquinas autopropulsadas (de obra o agrícolas), igual de lentas.\n\n«MOTOS CON SIDECAR», «CAMIONES» y «VEHÍCULOS DE USO ESPECIAL» tienen sus propias señales.\n\nCLAVE: compárala con la 5986 (la misma señal). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5838,"bg":"За стабилно и сигурно движение на превозното средство, стойността на коефициента на сцепление на автомобилните гуми с пътя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да е възможно по-голяма","ok":true,"i":null,"es":"lo más GRANDE posible"},{"t":"трябва да е възможно по-малка","ok":false,"i":null,"es":"lo más PEQUEÑO posible"},{"t":"е без значение","ok":false,"i":null,"es":"no tiene importancia"}],"f":1,"es":"Para una circulación estable y segura, el coeficiente de rozamiento debe ser:","explain":"Lo más GRANDE posible: a más rozamiento, más agarre: frenas antes, giras mejor, aceleras sin patinar. El rozamiento pequeño es el hielo: el enemigo. En neumáticos, el rozamiento es tu amigo."},{"id":5866,"bg":"За безопасно движение при сух път и добра видимост, интервалът между леките автомобили трябва да бъде не по-малък от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 секунди","ok":true,"i":null,"es":"2 segundos"},{"t":"дължината на един автомобил","ok":false,"i":null,"es":"la longitud de un coche"},{"t":"2 метра","ok":false,"i":null,"es":"2 metros"}],"f":1,"es":"Para circular con seguridad en vía seca y buena visibilidad, el intervalo entre turismos debe ser:","explain":"2 SEGUNDOS: el intervalo se mide en tiempo, no en metros ni en coches: 2 segundos valen a cualquier velocidad (a más velocidad, automáticamente más metros). 'Dos metros' a 90 km/h es un choque en cadena esperando."},{"id":5877,"bg":"Движението със съобразена скорост позволява на водача:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да владее превозното средство в конкретната пътна обстановка","ok":true,"i":null,"es":"dominar el vehículo en la situación concreta"},{"t":"при необходимост безопасно да намали скоростта","ok":true,"i":null,"es":"si es necesario, reducir la velocidad con seguridad"},{"t":"при необходимост безопасно да спре","ok":true,"i":null,"es":"si es necesario, parar con seguridad"},{"t":"да предотврати настъпването на произшествие след употребата на алкохол","ok":false,"i":null,"es":"prevenir un accidente después de consumir alcohol"}],"f":1,"es":"Circular a velocidad adecuada permite al conductor: (3 correctas)","explain":"La velocidad adecuada te permite: dominar el vehículo, reducir con seguridad y parar con seguridad: control en los tres tiempos. Lo que ninguna velocidad puede es compensar el alcohol: ese distractor es imposible por definición."},{"id":6266,"bg":"При тази ситуация задължени ли сте да пропуснете червения автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":1,"es":"¿Está obligado a dejar pasar al coche rojo en esta situación?","explain":"SÍ.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«NO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: girar a la izquierda = ceder a lo que viene de frente, siga recto o gire a su derecha. Ver Leyes → «Giro a la izquierda»."},{"id":12034,"bg":"При тази ситуация трябва да предвидите, че товарният автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":20,"a":[{"t":"ще остане в дясната лента","ok":false,"i":null,"es":"permanecerá en el carril derecho"},{"t":"ще навлезе още повече в съседната лява лента","ok":true,"i":null,"es":"invadirá aún más el carril izquierdo adyacente"},{"t":"ще спре","ok":true,"i":null,"es":"parará"}],"f":1,"es":"En esta situación debes anticipar que el camión: (2 correctas)"},{"id":12045,"bg":"Какъв е правилният начин на действие в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":37,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да увелича скоростта си","ok":false,"i":null,"es":"aumento la velocidad"},{"t":"да продължа движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"}],"f":1,"es":"¿Cuál es la actuación correcta en esta situación?"},{"id":12046,"bg":"Какво трябва да направите в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":38,"a":[{"t":"продължавам движението си в заеманата лента","ok":true,"i":null,"es":"continúo en mi carril"},{"t":"отклонявам се наляво","ok":false,"i":null,"es":"me desvío a la izquierda"},{"t":"рязко намалявам скоростта/аварийно спиране","ok":true,"i":null,"es":"freno de emergencia/reduzco bruscamente"}],"f":1,"es":"¿Qué debes hacer en esta situación? (2 correctas)"},{"id":6527,"bg":"При тази ситуация трябва да пропусна само червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57449.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":1,"es":"En esta situación debo ceder el paso solo al rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. Por la IZQUIERDA, por la vía principal, viene una MOTO. De frente viene un coche ROJO.\n\nNO SOLO AL ROJO: TAMBIÉN A LA MOTO. La moto circula por la vía principal, y tu ceda el paso te obliga a dejarla pasar aunque venga por tu izquierda. Al rojo también le cedes (vas a girar a la izquierda y viene de frente).\n\n«CORRECTO» es el cebo de quien se olvida de la moto porque llega por la izquierda y aplica la regla de la derecha.\n\nCLAVE: con ceda el paso, la regla de la derecha no te salva: cedes a todos los de la principal, vengan por donde vengan. Compárala con la 6528. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":5617,"bg":"Значението на този пътен знак е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39733.png","v":null,"a":[{"t":"начало на жилищна зона","ok":true,"i":null,"es":"inicio de zona residencial"},{"t":"начало на населено място","ok":false,"i":null,"es":"inicio de poblado"},{"t":"начало на жилищен комплекс","ok":false,"i":null,"es":"inicio de un complejo residencial"},{"t":"площадка за игра на деца","ok":false,"i":null,"es":"zona de juegos infantiles"}],"f":1,"es":"¿Cuál es el significado de esta señal?","explain":"INICIO DE ZONA RESIDENCIAL. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una persona, un niño jugando con una pelota, un coche y una casa.\n\nZONA RESIDENCIAL: los peatones pueden usar toda la calzada, los niños pueden jugar en ella y se circula muy despacio.\n\n«INICIO DE POBLADO» es un cartel con el nombre del pueblo. «COMPLEJO RESIDENCIAL» y «ZONA DE JUEGOS» son cebos que se fijan en un solo elemento del dibujo.\n\nCLAVE: compárala con la 5619 (cuándo termina). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5701,"bg":"Какви са изискванията към водача, който управлява тегленото МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да бъде правоспособен за категорията на тегленото МПС","ok":true,"i":null,"es":"debe tener permiso para la categoría del vehículo REMOLCADO"},{"t":"трябва да бъде правоспособен за категорията на теглещото МПС","ok":false,"i":null,"es":"debe tener permiso para la categoría del vehículo REMOLCADOR"},{"t":"не е задължително да бъде правоспособен водач","ok":false,"i":null,"es":"no es obligatorio que sea conductor autorizado"},{"t":"достатъчно е да бъде правоспособен водач, независимо за коя категория","ok":false,"i":null,"es":"basta con ser conductor habilitado, sin importar la categoría"}],"f":1,"es":"¿Qué requisito debe cumplir el conductor del vehículo REMOLCADO?","explain":"El conductor del REMOLCADO necesita permiso para la categoría del vehículo REMOLCADO (el que él gobierna): sigue dirigiendo y frenando un vehículo real en la vía. 'Cualquier categoría' o 'sin permiso' convertirían el remolcado en conducción sin habilitación."},{"id":5745,"bg":"Разрешено ли е при теглене с твърда връзка тегленото превозно средство да бъде с неизправна спирачна уредба?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":1,"es":"Al remolcar con enganche rígido, ¿está permitido que el vehículo remolcado tenga el sistema de frenos averiado?","explain":"Sí: con enganche RÍGIDO se permite remolcar con los frenos averiados: la barra transmite la frenada del remolcador directamente. Es la ventaja clave de la barra sobre el cable (que exige frenos operativos)."},{"id":5805,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29243.png","v":null,"a":[{"t":"да пропусне автомобила със специален режим на движение","ok":true,"i":null,"es":"ceder el paso al automóvil con régimen especial de circulación"},{"t":"да пропусне двата автомобила","ok":false,"i":null,"es":"ceder el paso a los dos automóviles"},{"t":"да премине преди двата автомобила","ok":false,"i":null,"es":"pasar antes que los dos automóviles"}],"f":1,"es":"En esta situación, el conductor del automóvil verde debe:","explain":"CEDER EL PASO AL AUTOMÓVIL CON RÉGIMEN ESPECIAL DE CIRCULACIÓN. Una sola correcta.\n\nQUÉ VES. Un cruce sin señales. Vas recto en el coche VERDE. Por la izquierda llega una AMBULANCIA con luces azules; de frente, un coche AZUL va a girar a su izquierda (cruzando tu trayectoria).\n\nUN VEHÍCULO EN RÉGIMEN ESPECIAL (con las señales luminosas y acústicas encendidas) pasa por delante de las reglas de prioridad, de las señales y del semáforo: se le cede siempre.\n\nAL AZUL NO LE CEDES: gira a la izquierda, así que es él quien te cede a ti, que vas recto de frente.\n\n«CEDER A LOS DOS» y «PASAR ANTES QUE LOS DOS» son los cebos.\n\nCLAVE: compárala con la 5811. Ver Leyes → «Quién manda sobre quién»."},{"id":11628,"bg":"Моторни превозни средства със специален режим на движение са автомобилите и мотоциклетите, които при движението си подават едновременно:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"светлинен сигнал с проблясваща синя и/или червена светлина и специален звуков сигнал","ok":true,"i":null,"es":"señal luminosa de luz azul y/o roja parpadeante Y señal acústica especial"},{"t":"авариен сигнал и специален звуков сигнал","ok":false,"i":null,"es":"señal de emergencia Y señal acústica"},{"t":"светлинен сигнал с жълта пробляскваща светлина и специален звуков сигнал","ok":false,"i":null,"es":"señal luminosa amarilla Y señal acústica"}],"f":1,"es":"Los vehículos con régimen especial de circulación son los que usan:","explain":"Régimen especial = luz azul y/o roja parpadeante + señal acústica especial: la combinación completa. Ni la señal de emergencia (los cuatro intermitentes) ni la luz amarilla (vehículos-obstáculo) identifican régimen especial."},{"id":5746,"bg":"Управление на МПС след употреба на упойващо вещество е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено, без ограничение","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, когато се взема по лекарско предписание","ok":false,"i":null,"es":"permitido, cuando se toma por prescripción médica"}],"f":1,"es":"Conducir un vehículo tras consumir una sustancia estupefaciente está:","explain":"Prohibido: conducir tras consumir estupefacientes está vetado sin excepciones: la prescripción médica no legaliza conducir drogado. Si el tratamiento afecta a la conducción, no se conduce."},{"id":6114,"bg":"При управление на автомобил под въздействие на алкохол:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"съществува опасност от загуба на контрола над превозното средство от водача","ok":true,"i":null,"es":"existe el peligro de que el conductor pierda el control del vehículo"},{"t":"повишава се риска от попадане в ПТП","ok":true,"i":null,"es":"aumenta el riesgo de verse implicado en un accidente"},{"t":"водачът има по-бързи реакции","ok":false,"i":null,"es":"el conductor tiene reacciones más rápidas"},{"t":"водачът отделя по-голямо внимание на опасностите на пътя","ok":false,"i":null,"es":"el conductor presta más atención a los peligros de la vía"}],"f":1,"es":"Al conducir un automóvil bajo los efectos del alcohol: (2 correctas)","explain":"Con alcohol: riesgo de perder el control del vehículo y más probabilidad de accidente: las dos consecuencias directas. Las 'reacciones más rápidas' y la 'mayor atención' son los mitos espejo de siempre."},{"id":6116,"bg":"Какво влияние оказва алкохолът върху поведението на водача на МПС?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава възможността за правилна оценка на скоростта","ok":true,"i":null,"es":"empeora la capacidad de evaluar correctamente la velocidad"},{"t":"намалява концентрацията","ok":true,"i":null,"es":"reduce la concentración"},{"t":"подобрява координацията на движенията","ok":false,"i":null,"es":"mejora la coordinación de los movimientos"},{"t":"забавя реакциите","ok":true,"i":null,"es":"ralentiza las reacciones"}],"f":1,"es":"¿Qué influencia tiene el alcohol sobre el comportamiento del conductor? (3 correctas)","explain":"El alcohol: empeora la evaluación de la velocidad, reduce la concentración y ralentiza las reacciones: triple golpe (juicio, atención, respuesta). Solo 'mejora la coordinación' es falsa: nada mejora con alcohol."},{"id":6122,"bg":"Какво влияние оказва алкохолът върху поведението на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"намалява концентрацията","ok":true,"i":null,"es":"reduce la concentración"},{"t":"влошава възможността за правилна оценка на скоростта","ok":true,"i":null,"es":"empeora la capacidad de evaluar correctamente la velocidad"},{"t":"подобрява координацията","ok":false,"i":null,"es":"mejora la coordinación"},{"t":"намалява времето за реакция","ok":false,"i":null,"es":"reduce el tiempo de reacción"}],"f":1,"es":"¿Qué influencia tiene el alcohol sobre el comportamiento del conductor? (2 correctas)","explain":"Variante de la serie: reduce la concentración y empeora el juicio de la velocidad. Las falsas son las mejoras imposibles: ni coordina mejor ni acorta el tiempo de reacción: el alcohol solo resta."},{"id":6135,"bg":"Затрудненията на водача при управлението през нощта са в резултат на:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"понижената физиологична активност на водача","ok":true,"i":null,"es":"la actividad fisiológica reducida del conductor"},{"t":"намалената видимост","ok":true,"i":null,"es":"la visibilidad reducida"},{"t":"намалената интензивност на движението","ok":false,"i":null,"es":"la menor intensidad del tráfico"}],"f":1,"es":"Las dificultades del conductor al conducir de noche son resultado de: (2 correctas)","explain":"Conducir de noche cuesta por: la actividad fisiológica REDUCIDA (el cuerpo pide dormir: es su hora biológica) y la visibilidad reducida. El menor tráfico sería una ventaja, no una dificultad: distractor invertido."},{"id":6011,"bg":"При движение през деня, товарът, който излиза с повече от 1 м отпред или отдзад на най-издадената част на превозното средство, се обозначава:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен флаг","ok":true,"i":null,"es":"con bandera roja"},{"t":"с червена светлина","ok":false,"i":null,"es":"con luz ROJA"},{"t":"с бяла светлина","ok":false,"i":null,"es":"con luz BLANCA"},{"t":"с червен светлоотразител","ok":false,"i":null,"es":"con reflectante ROJO"}],"f":1,"es":"De día, la carga que sobresale más de 1m por DELANTE debe señalizarse con:","explain":"De DÍA, saliente por DELANTE: bandera ROJA: la señal diurna universal de carga. Las luces y reflectantes son señalización nocturna, y el rojo detrás/blanco delante rige para ellas: de día manda la bandera."},{"id":6014,"bg":"Товарът не се обозначава, ако излиза отзад на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 1 м","ok":true,"i":null,"es":"hasta 1 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"до 3 м","ok":false,"i":null,"es":"hasta 3 m"}],"f":1,"es":"La carga no necesita señalizarse si sobresale por DETRÁS:","explain":"Por DETRÁS: hasta 1 m sin señalizar: el mismo margen que por delante. Grábate el trío: 1 m delante, 1 m detrás, 0,2 m laterales: tres números que resuelven toda la familia de cargas salientes."},{"id":6015,"bg":"Кой от изброените документи е задължен да носи водачът, когато управлява МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"свидетелство за управление валидно за категорията на МПС, което управлява","ok":true,"i":null,"es":"permiso de conducción válido para la categoría del vehículo que conduce"},{"t":"свидетелство за регистрация на МПС","ok":true,"i":null,"es":"permiso de circulación del vehículo"},{"t":"документ за сключена застраховка „Гражданска отговорност”","ok":true,"i":null,"es":"documento del seguro de responsabilidad civil contratado"},{"t":"документ за платен данък МПС","ok":false,"i":null,"es":"documento del impuesto de vehículos pagado"}],"f":1,"es":"¿Cuál de los documentos indicados está obligado a llevar el conductor cuando conduce? (3 correctas)","explain":"A bordo siempre: permiso de conducción de la categoría, permiso de circulación del vehículo y documento del seguro obligatorio. El justificante del impuesto de vehículos NO se exige en el control: es asunto tributario, no vial."},{"id":5485,"bg":"Контролните органи временно отнемат свидетелството за управление на МПС на водач:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"който откаже да бъде проверен от контролните органи за наличие на алкохол в кръвта","ok":true,"i":null,"es":"que se niegue a ser sometido por los agentes al control de alcohol en sangre"},{"t":"който поради незнание е извършил немаловажно нарушение на правилата за движение","ok":true,"i":null,"es":"que por desconocimiento haya cometido una infracción no menor de las normas de circulación"},{"t":"който управлява МПС без застраховка &quot;Гражданска отговорност&quot; на автомобилистите","ok":true,"i":null,"es":"que conduzca un vehículo sin el seguro de responsabilidad civil de los automovilistas"},{"t":"когато не е заплатена необходимата винетна такса","ok":false,"i":null,"es":"cuando no se ha pagado la viñeta obligatoria"}],"f":1,"es":"Las autoridades de control retiran temporalmente el permiso de conducción al conductor: (3 correctas)","explain":"Retirada temporal del permiso: negarse al control de alcohol, cometer por desconocimiento una infracción no menor y conducir SIN el seguro de responsabilidad civil. La viñeta impagada es sanción económica: no toca el permiso."},{"id":5341,"bg":"Задължение за запазване на следите при ПТП имат:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"всички участници в ПТП","ok":true,"i":null,"es":"todos los implicados en el accidente"},{"t":"свидетелите на ПТП","ok":false,"i":null,"es":"los testigos del accidente"},{"t":"само виновните участници в ПТП","ok":false,"i":null,"es":"solo los culpables del accidente"},{"t":"всички участници в движението","ok":false,"i":null,"es":"todos los participantes en el tráfico"}],"f":1,"es":"La obligación de preservar las huellas en un accidente corresponde a:","explain":"Preservar las huellas corresponde a TODOS los implicados: no solo al culpable (que aún no está determinado) ni a los testigos (que no tienen obligaciones sobre la escena). Implicado = responsable de la evidencia."},{"id":5961,"bg":"На кой от пътните знаци значението е “Пропусни насрещно движещите се ППС!”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46285.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46322.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46324.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334693.png","es":""}],"f":1,"es":"¿En cuál de las señales el significado es 'Cede el paso a los vehículos que vienen de frente'?","explain":"LA PRIMERA: CÍRCULO CON FLECHA NEGRA HACIA ABAJO Y ROJA HACIA ARRIBA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) círculo con borde ROJO, flecha NEGRA hacia abajo y ROJA hacia arriba; 2) cuadrado AZUL con flecha ROJA hacia abajo y BLANCA hacia arriba; 3) triángulo con dos flechas negras; 4) triángulo invertido.\n\nLAS SEÑALES DE FLECHAS ENFRENTADAS, QUE SE CONFUNDEN:\n• TRIÁNGULO con dos flechas negras = «Circulación en ambos sentidos» (aviso);\n• CÍRCULO con borde rojo, flecha NEGRA hacia abajo y ROJA hacia arriba = «Cede el paso a los que vienen de frente»;\n• CUADRADO AZUL, flecha ROJA hacia abajo y BLANCA hacia arriba = «Pasa si la vía está libre» (preferencia en un paso estrecho).\n\nTU SENTIDO ES LA FLECHA DE ARRIBA. En el círculo es la roja: te dice que cedes. En el cuadrado azul es la blanca: pasas tú.\n\n«EL TRIÁNGULO INVERTIDO» es ceder a la vía con prioridad, no a los de frente.\n\nCLAVE: compárala con la 5960. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6174,"bg":"Значението на кой от пътните знаци е „Забранено е влизането на ППС с натоварване, на която и да е от осите, по-голямо от означеното”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334710.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52193.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52194.png","es":""}],"f":1,"es":"¿Cuál de las señales significa 'Prohibida la entrada de vehículos con carga por eje superior a la indicada'?","explain":"La senal de carga por eje (numeros con 't' y aspa) restringe vehiculos segun la presion sobre el firme."},{"id":5269,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"334673"},{"t":"","ok":false,"es":"","i":"27189"},{"t":"","ok":true,"es":"","i":"334676"},{"t":"","ok":true,"es":"","i":"23809"}],"f":1,"es":"¿Cuál de las señales advierte de la proximidad de una intersección? (3 correctas)","explain":"LA PRIMERA, LA TERCERA Y LA CUARTA: TRAZO GRUESO CON FINO A LA DERECHA, ROTONDA Y TRAZO GRUESO CON FINOS A AMBOS LADOS. Tres correctas.\n\nQUÉ VES. Cuatro señales: 1) triángulo con trazo grueso y trazo fino a la DERECHA; 2) cuadrado AZUL con un peatón sobre un paso; 3) triángulo con flechas en círculo; 4) triángulo con trazo grueso y trazos finos a AMBOS lados.\n\nLOS TRES TRIÁNGULOS AVISAN DE UN CRUCE: con una vía sin prioridad (por la derecha o por ambos lados) y con circulación giratoria.\n\n«EL CUADRADO AZUL» es el cebo: marca el lugar exacto de un paso de peatones, no un cruce de vías.\n\nCLAVE: compárala con la 5271 y la 5272. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6210,"bg":"Кой от пътните знаци указва, че пътят е без изход?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46180.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46181.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46182.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46183.png","es":""}],"f":1,"es":"¿Cuál de las señales indica que el camino no tiene salida?","explain":"LA PRIMERA: CUADRADO AZUL CON UNA T DE EXTREMO ROJO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) cuadrado azul con una T cuyo extremo superior es ROJO; 2) cuadrado azul con una flecha en U; 3) panel negro con el esquema de un desvío; 4) panel amarillo con carriles desviados.\n\nLA T CON EL EXTREMO ROJO es la calle sin salida: el rojo marca dónde se corta.\n\n«LA U» es un lugar para cambiar de sentido. «EL PANEL NEGRO» y «EL AMARILLO» indican cómo se desvía el tráfico.\n\nCLAVE: rojo en el dibujo = ahí se corta la vía. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5958,"bg":"На кой от пътните знаци значението е “Пропусни движещите се по пътя с предимство!”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46282.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46283.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46284.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46285.png","es":""}],"f":1,"es":"¿En cuál de las señales el significado es 'Cede el paso a los que circulan por la vía con prioridad'?","explain":"LA PRIMERA: EL TRIÁNGULO INVERTIDO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) TRIÁNGULO INVERTIDO blanco con borde rojo; 2) rombo amarillo tachado (fin de la vía con prioridad); 3) triángulo con una X (cruce de vías iguales); 4) círculo con flecha negra hacia abajo y roja hacia arriba.\n\nEL TRIÁNGULO INVERTIDO ES EL CEDA EL PASO: cedes a los que van por la vía con prioridad.\n\n«EL ROMBO TACHADO» indica que TU vía deja de ser prioritaria, no que tengas que ceder ya. «LA X» avisa de un cruce sin prioridad para nadie.\n\n«EL CÍRCULO DE FLECHAS» es el cebo fino: también es ceder, pero a los que vienen de frente (compárala con la 5961).\n\nCLAVE: compárala con la 5957. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5559,"bg":"Кой от тези пътни знаци сигнализира за спирка на превозни средства за обществен превоз на пътници?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334688.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334687.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38922.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38923.png","es":""}],"f":1,"es":"¿Cuál de estas señales indica una parada de vehículos de transporte público de pasajeros? (3 correctas)","explain":"LA PRIMERA, LA SEGUNDA Y LA TERCERA: TRANVÍA, AUTOBÚS Y TROLEBÚS. Tres correctas.\n\nQUÉ VES. Cuatro cuadrados azules: 1) recuadro blanco con un TRANVÍA; 2) recuadro blanco con un AUTOBÚS; 3) recuadro blanco con un TROLEBÚS; 4) un COCHE blanco sin recuadro.\n\nLAS TRES PRIMERAS SON PARADAS de transporte público.\n\n«EL COCHE BLANCO» es el cebo: es la señal de vía rápida (compárala con la 5334).\n\nCLAVE: vehículo en recuadro blanco = parada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6206,"bg":"Кой от пътните знаци указва, че преминавате покрай болница?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334700.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46140.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46141.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46142.png","es":""}],"f":1,"es":"¿Cuál de las señales indica que pasas junto a un hospital?","explain":"LA PRIMERA: CUADRADO AZUL CON UNA «H». Una sola correcta.\n\nQUÉ VES. Cuatro señales azules: 1) una «H» grande; 2) una «i» (información); 3) una CRUZ ROJA (primeros auxilios); 4) una CAMA (hotel o motel).\n\nLA «H» ES HOSPITAL: pasas junto a uno, y conduces sin hacer ruido.\n\n«LA CRUZ ROJA» es el cebo fino: es un puesto de primeros auxilios, no un hospital.\n\nCLAVE: compárala con la 11609 y la 11681. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":9842,"bg":"Кой от пътните знаци сигнализира за начало на пътна лента?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043361.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043362.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043363.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043364.png","es":""}],"f":1,"es":"¿Cuál de las señales señaliza el inicio de un carril?","explain":"LA PRIMERA: TRES FLECHAS, LA TERCERA NACE DE LA SEGUNDA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) cuadrado AZUL con tres flechas, la tercera nace de la segunda; 2) panel BLANCO con tres flechas negras rectas; 3) cuadrado azul con carriles que se separan en distintas direcciones; 4) cuadrado azul con un carril nuevo a la derecha y un círculo «40».\n\nLA FLECHA QUE SE ABRE ES UN CARRIL QUE EMPIEZA.\n\n«EL PANEL BLANCO» indica el número de carriles. «LOS CARRILES QUE SE SEPARAN» son de preselección. «EL DEL 40» es el cebo fino: también empieza un carril, pero es específicamente el de vehículos lentos (9848).\n\nCLAVE: compárala con la 6211. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5284,"bg":"Кой от пътните знаци обозначава точното място на пешеходната пътека?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334678.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334677.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27190.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27243.png","es":""}],"f":1,"es":"¿Cuál de las señales indica la ubicación exacta de un paso de peatones?","explain":"LA PRIMERA: CUADRADO AZUL CON UN PEATÓN SOBRE EL PASO. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) CUADRADO AZUL con un triángulo blanco y un peatón sobre las franjas; 2) TRIÁNGULO rojo con el mismo peatón; 3) cuadrado azul con dos peatones (zona peatonal); 4) círculo azul con un peatón (vía solo para peatones).\n\nLA CUADRADA AZUL ESTÁ JUSTO EN EL PASO: marca su lugar exacto.\n\n«EL TRIÁNGULO» es el cebo fino: avisa de que te ACERCAS a un paso, colocado antes de él.\n\n«ZONA PEATONAL» y «VÍA SOLO PARA PEATONES» no son pasos.\n\nCLAVE: compárala con la 5283 y la 5280. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6172,"bg":"Значението на кой от пътните знаци е „Забранено е влизането на ППС, с маса с товар, по-голяма от означената”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52120.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52121.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52122.png","es":""}],"f":1,"es":"¿Cuál de las señales significa 'Prohibida la entrada de vehículos cuya masa con carga supere la indicada'?","explain":"La senal de masa total (numero con 't' en circulo rojo) limita el acceso por peso total del vehiculo cargado."},{"id":5317,"bg":"На показаната фигура видимостта е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20591.png","v":null,"a":[{"t":"ограничена","ok":true,"i":null,"es":"limitada"},{"t":"намалена","ok":false,"i":null,"es":"reducida"}],"es":"En la figura mostrada la visibilidad está:","explain":"LIMITADA. Una sola correcta.\n\nQUÉ VES. Carretera de montaña en un día claro que entra en una curva cerrada entre árboles: no se ve lo que viene después de la curva.\n\nLO QUE IMPIDE VER ES LA PROPIA CARRETERA (la curva y los árboles), no el tiempo:\n• visibilidad LIMITADA = por la vía o el entorno (curvas, cambios de rasante, obstáculos);\n• visibilidad REDUCIDA = por el tiempo o la luz (niebla, lluvia, nieve, polvo).\n\n«REDUCIDA» es el cebo: el aire está limpio.\n\nCLAVE: compárala con la 5312 (niebla = reducida)."},{"id":8215,"bg":"Кои от изброените лица се считат за пешеходци?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"които бутат пътно превозно средство без двигател и с широчина, по-малка от 1 метър","ok":true,"i":null,"es":"que empujan un vehículo sin motor de menos de 1 metro de ancho"},{"t":"които бутат велосипед","ok":true,"i":null,"es":"que empujan una bicicleta"},{"t":"които бутат мотопед или мотоциклет","ok":true,"i":null,"es":"que empujan un ciclomotor o una motocicleta"},{"t":"които водят ездитни животни по пътищата","ok":false,"i":null,"es":"que llevan animales de montura por las vías"}],"es":"¿Cuáles de las personas se consideran peatones? (3 correctas)","explain":"Son peatones quienes empujan: un vehículo sin motor de menos de 1 m de ancho, una bicicleta o un ciclomotor/motocicleta (a pie, junto al vehículo). Quien lleva animales de MONTURA se rige por las normas de los conductores: esa es la excepción."},{"id":8227,"bg":"Водач с правоспособност за управление на МПС от категория А има право да управлява и МПС от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"категория АМ","ok":true,"i":null,"es":"categoría AM"},{"t":"категория А1","ok":true,"i":null,"es":"categoría A1"},{"t":"категория В1","ok":false,"i":null,"es":"categoría B1"},{"t":"категория Ткт","ok":false,"i":null,"es":"categoría Ткт (tractor de ruedas)"}],"es":"El conductor con permiso categoría A tiene derecho a conducir vehículos de: (2 correctas)","explain":"El permiso A (motos plenas) incluye AM y A1: toda la rama de dos ruedas hacia abajo (y A2). No incluye B1 (rama de cuadriciclos/automóviles) ni tractores: las ramas no se cruzan."},{"id":11580,"bg":"Коя част от пътя на показаната схема е означена с буквата „C”?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086155016.png","v":null,"a":[{"t":"пътното платно","ok":true,"i":null,"es":"la plataforma vial (calzada + arcenes)"},{"t":"платното за движение","ok":false,"i":null,"es":"la calzada"},{"t":"пътна лента","ok":false,"i":null,"es":"carril"}],"es":"¿Qué parte de la carretera del esquema está indicada con la letra 'С'?","explain":"LA PLATAFORMA VIAL («ПЪТНО ПЛАТНО»). Una sola correcta.\n\nQUÉ VES. Una carretera con un esquema de tres medidas debajo: «А» va desde la línea central hasta el borde derecho de la calzada; «В» abarca toda la calzada; «С», la más ancha, incluye también las franjas oscuras de los lados.\n\nLAS TRES PARTES, SEGÚN EL BANCO:\n• «А» = un CARRIL («пътна лента»): la franja por la que circula una fila de vehículos;\n• «В» = la CALZADA («платно за движение»): la parte por la que circulan los vehículos, entre las líneas de borde;\n• «С» = la PLATAFORMA («пътно платно»): la calzada más las franjas laterales (arcenes).\n\n«LA CALZADA» es «В» y «CARRIL» es «А»: los dos quedan dentro de «С».\n\nCLAVE: «пътно платно» (plataforma) ≠ «платно за движение» (calzada). Compárala con la 11579."},{"id":12071,"bg":"Тракторът принадлежи към групата на:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните превозни средства","ok":true,"i":null,"es":"los vehículos"},{"t":"моторните превозни средства","ok":true,"i":null,"es":"los vehículos de motor"},{"t":"товарните автомобили","ok":false,"i":null,"es":"los camiones"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"}],"es":"El tractor pertenece al grupo de: (2 correctas)","explain":"El tractor es VEHÍCULO y VEHÍCULO DE MOTOR: tiene motor propio y circula por la vía. No es camión (no está destinado a transportar carga en caja) ni 'vehículo especial': categoría propia dentro de los de motor."},{"id":5202,"bg":"Допълнителният контур с жълтозелен флуоресцентен светлоотразителен фон около пътния знак значава, че:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21456.png","v":null,"a":[{"t":"пешеходната пътека се намира в участък от пътя, на който често стават произшествия","ok":true,"i":null,"es":"el paso de peatones está en un tramo de vía donde ocurren accidentes con frecuencia"},{"t":"пешеходната пътека не е осветена","ok":false,"i":null,"es":"el paso de peatones no está iluminado"},{"t":"след пешеходната пътека следва участък от пътя в ремонт","ok":false,"i":null,"es":"después del paso de peatones sigue un tramo de vía en obras"},{"t":"има интензивно движение на пешеходци","ok":false,"i":null,"es":"hay un paso intenso de peatones"}],"es":"El contorno adicional con fondo fluorescente reflectante amarillo-verde alrededor de la señal significa que:","explain":"EL PASO DE PEATONES ESTÁ EN UN TRAMO DONDE OCURREN ACCIDENTES CON FRECUENCIA. Una sola correcta.\n\nLA SEÑAL. La cuadrada AZUL de paso de peatones con un marco AMARILLO-VERDE fluorescente alrededor.\n\nEL CONTORNO AMARILLO-VERDE FLUORESCENTE no cambia el significado de la señal: solo la hace más visible porque ese tramo es un PUNTO NEGRO, con accidentes frecuentes.\n\n«NO ESTÁ ILUMINADO», «SIGUEN OBRAS» y «MUCHOS PEATONES» son cebos que inventan un significado para el marco.\n\nCLAVE: compárala con la 5205 y la 5207 (el mismo fondo detrás de otras señales). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5205,"bg":"Допълнителният контур с жълтозелен флуоресцентен светлоотразителен фон около пътния знак значава, че:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21477.png","v":null,"a":[{"t":"в този участък от пътя често стават произшествия","ok":true,"i":null,"es":"en ese tramo de vía ocurren accidentes con frecuencia"},{"t":"знакът е валиден само при мокър път","ok":false,"i":null,"es":"la señal es válida solo con la vía mojada"},{"t":"следва участък от пътя в ремонт","ok":false,"i":null,"es":"sigue un tramo de vía en obras"},{"t":"ограничението се отнася само за товарните автомобили","ok":false,"i":null,"es":"la restricción se aplica solo a los camiones"}],"es":"El contorno adicional con fondo fluorescente reflectante amarillo-verde alrededor de la señal significa que:","explain":"EN ESE TRAMO OCURREN ACCIDENTES CON FRECUENCIA. Una sola correcta.\n\nLA SEÑAL. Límite de velocidad «50» con un anillo AMARILLO-VERDE fluorescente alrededor.\n\nEL CONTORNO AMARILLO-VERDE FLUORESCENTE no cambia el significado de la señal: solo la hace más visible porque ese tramo es un PUNTO NEGRO, con accidentes frecuentes.\n\n«SOLO CON LA VÍA MOJADA» y «SOLO PARA CAMIONES» serían placas complementarias, no un contorno de color.\n\n«TRAMO EN OBRAS» confunde el amarillo-verde con el amarillo de las señales temporales.\n\nCLAVE: compárala con la 5202 y la 5207. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5229,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23174.png","v":null,"a":[{"t":"предупреждава за място, където на пътя излизат велосипедисти","ok":true,"i":null,"es":"advierte de un lugar donde salen ciclistas a la vía"},{"t":"сигнализира участък от пътя, по който е забранено движението на велосипедисти","ok":false,"i":null,"es":"señaliza un tramo de vía donde está prohibida la circulación de ciclistas"},{"t":"указва начало на велосипедна алея","ok":false,"i":null,"es":"indica el inicio de un carril bici"},{"t":"указва начало на път само за велосипедисти","ok":false,"i":null,"es":"indica el inicio de una vía solo para ciclistas"}],"es":"Esta señal:","explain":"ADVIERTE DE UN LUGAR DONDE SALEN CICLISTAS A LA VÍA. Una sola correcta.\n\nLA SEÑAL. TRIÁNGULO de peligro con un CICLISTA.\n\nES UN TRIÁNGULO: AVISA de que pueden aparecer ciclistas cruzando o incorporándose (por ejemplo, desde un carril bici).\n\n«PROHIBIDA LA CIRCULACIÓN DE CICLISTAS» sería un círculo rojo con una bicicleta. «INICIO DE UN CARRIL BICI» y «VÍA SOLO PARA CICLISTAS» serían señales azules.\n\nCLAVE: la misma bicicleta cambia de significado según la forma: triángulo = aviso, círculo rojo = prohibido, azul = para ellos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5273,"bg":"На пътя пешеходни пътеки са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"продълженията на тротоарите и пътните банкети върху платното за движение","ok":true,"i":null,"es":"las prolongaciones de las aceras y los arcenes sobre la calzada"},{"t":"очертаните с пътна маркировка места за преминаване на пешеходците през платното за движение","ok":true,"i":null,"es":"los lugares marcados con marcas viales para el cruce de peatones por la calzada"},{"t":"сигнализираните с пътен знак места за преминаване на пешеходците","ok":true,"i":null,"es":"los lugares señalizados con señal de tráfico para el cruce de peatones"},{"t":"само местата обозначени с пътна маркировка тип „Зебра”","ok":false,"i":null,"es":"solo los lugares marcados con marca vial tipo \"cebra\""}],"es":"En la carretera los pasos de peatones son: (3 correctas)","explain":"Son pasos de peatones: las prolongaciones de aceras y arcenes sobre la calzada (¡aunque no estén pintadas!), los lugares marcados y los señalizados con señal. 'Solo la cebra' es falso: el paso existe por definición legal, no solo por pintura."},{"id":5799,"bg":"При тази ситуация при преминаване покрай каруцата:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24744.png","v":null,"a":[{"t":"има опасност каруцата да промени внезапно посоката си на движение, поради подплашване на животното","ok":true,"i":null,"es":"existe el peligro de que el carro cambie bruscamente de dirección si el animal se asusta"},{"t":"има опасност от поява на друго домашно животно на платното за движение, което придружава каруцата","ok":true,"i":null,"es":"existe el peligro de que aparezca en la calzada otro animal doméstico que acompaña al carro"},{"t":"има опасност каруцата да навлезе на платното за движение поради препятствие на пътния банкет","ok":true,"i":null,"es":"existe el peligro de que el carro entre en la calzada por un obstáculo en el arcén"},{"t":"няма опасност, защото каруцата се движи по пътния банкет","ok":false,"i":null,"es":"no hay peligro, porque el carro circula por el arcén"}],"es":"En esta situación, al pasar junto a la carreta: (3 correctas)","explain":"EL CARRO PUEDE CAMBIAR DE DIRECCIÓN SI EL ANIMAL SE ASUSTA, PUEDE APARECER OTRO ANIMAL QUE LO ACOMPAÑA Y EL CARRO PUEDE ENTRAR EN LA CALZADA POR UN OBSTÁCULO EN EL ARCÉN. Tres correctas.\n\nQUÉ VES. Carretera fuera de población. Delante va un autobús y, a la derecha, por el arcén, un carro de madera cargado y conducido por un hombre.\n\nQUE VAYA POR EL ARCÉN NO LO SACA DEL PELIGRO: el animal puede asustarse y desviarse, puede haber otro animal suelto que lo acompaña, y cualquier obstáculo en el arcén lo obligará a meterse en la calzada.\n\n«NO HAY PELIGRO PORQUE VA POR EL ARCÉN» es el cebo.\n\nCLAVE: compárala con la 5802 (el carro de paja)."},{"id":6054,"bg":"При движение извън населено място, водачът може да използва звуковия сигнал:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"за предупреждаване на участниците в движението за възможна опасност","ok":true,"i":null,"es":"para advertir a los usuarios de la vía de un posible peligro"},{"t":"като допълнителен сигнал при извършване на маневра","ok":true,"i":null,"es":"como señal adicional al realizar una maniobra"},{"t":"в случаите за предотвратяване на ПТП","ok":true,"i":null,"es":"en los casos necesarios para evitar un accidente de tráfico"},{"t":"за да си осигури предимство","ok":false,"i":null,"es":"para asegurarse la prioridad"}],"es":"Al circular fuera de población, el conductor puede usar el claxon: (3 correctas)","explain":"Fuera de poblado el claxon vale para: advertir de un peligro, señal adicional de maniobra y evitar un accidente: uso amplio. Lo único vetado en todas partes: usarlo para EXIGIR prioridad: la prioridad no se reclama con bocina."},{"id":11815,"bg":"При коя от посочените стойности на допустимата максимална маса, товарните автомобили с дължина над 7 метра, задължително се обозначават с този опознавателен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828378.png","v":null,"a":[{"t":"6000 kg","ok":true,"i":null,"es":"6000 kg"},{"t":"5000 kg","ok":true,"i":null,"es":"5000 kg"},{"t":"4000 kg","ok":true,"i":null,"es":"4000 kg"},{"t":"3000 kg","ok":false,"i":null,"es":"3000 kg"}],"es":"¿A partir de qué valor de masa máxima admisible los camiones con longitud superior a 7 metros deben llevar obligatoriamente este signo distintivo? (3 correctas)","explain":"6000 kg, 5000 kg Y 4000 kg. Tres correctas.\n\nQUÉ VES. La misma trasera que la 11814: placas verticales de FRANJAS DIAGONALES rojas y amarillas.\n\nEL LÍMITE ES MÁS DE 3500 kg (con más de 7 m de largo). Cualquier masa por encima de 3500 kg obliga a llevarlas: 4000, 5000 y 6000 kg.\n\n«3000 kg» es el cebo: está por debajo del límite.\n\nCLAVE: no busques una cifra exacta; busca todas las que superan 3500 kg."},{"id":12006,"bg":"При тази ситуация трябва да намалите скоростта и да управлявате с готовност за спиране, защото:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"белият автомобил ще се отклони наляво и ще се включи в движението","ok":false,"i":null,"es":"el automóvil blanco se desviará a la izquierda y se incorporará al tráfico"},{"t":"автомобилът пред вас подава десен пътепоказател","ok":true,"i":null,"es":"el automóvil de delante señaliza con el intermitente derecho"},{"t":"на пътното платно има деца","ok":true,"i":null,"es":"hay niños en la plataforma vial"}],"es":"En esta situación debes reducir la velocidad y circular con disposicion de frenar porque: (2 correctas)","explain":"Reduce y prepárate para frenar por DOS señales de peligro: el de delante señaliza con el intermitente derecho (va a maniobrar) y hay NIÑOS en la plataforma vial: imprevisibles por definición. Nota: el coche blanco incorporándose NO es la razón marcada: no anticipes maniobras que nadie ha señalizado."},{"id":6171,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52103.png","v":null,"a":[{"t":"„Забранено е влизането на ППС, с маса с товар, по-голяма от означената”","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos con masa con carga superior a la indicada'"},{"t":"„Забранено е влизането на ППС, с товар е по-голям от означения”","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos cuya carga supere lo indicado'"},{"t":"„Забранено е влизането на ППС с товароносимост по-голяма от означената”","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos con capacidad de carga superior'"},{"t":"„Забранено е влизането на ППС с натоварване, на която и да е от осите по-голямо от означеното”","ok":false,"i":null,"es":"'Prohibida la entrada si la carga por eje supera lo indicado'"}],"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE VEHÍCULOS CON MASA CON CARGA SUPERIOR A LA INDICADA». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y solo «3 t», sin ningún dibujo.\n\nLAS SEÑALES DE TONELADAS Y METROS:\n• solo «3 t» = masa total con carga;\n• «t» sobre un EJE = carga por eje;\n• «m» con flechas ARRIBA y ABAJO = altura; a los LADOS = anchura; con un camión y flechas delante y detrás = longitud.\n\n«CARGA SUPERIOR» y «CAPACIDAD DE CARGA» son cebos de vocabulario: la señal limita lo que pesa el vehículo entero con su carga.\n\n«CARGA POR EJE» es la señal con el eje dibujado (6173).\n\nCLAVE: compárala con la 5979 y la 6173. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6196,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46479.png","v":null,"a":[{"t":"„Задължителен път само за пешеходци”","ok":true,"i":null,"es":"\"Vía obligatoria solo para peatones\""},{"t":"„Пешеходна пътека”","ok":false,"i":null,"es":"\"Paso de peatones\""},{"t":"„Забранено е движението на пешеходци”","ok":false,"i":null,"es":"\"Prohibida la circulación de peatones\""},{"t":"„Пешеходна алея”","ok":false,"i":null,"es":"\"Senda peatonal\""}],"es":"El significado de esta señal es:","explain":"«VÍA OBLIGATORIA SOLO PARA PEATONES». Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con un PEATÓN blanco caminando.\n\nCÍRCULO AZUL = OBLIGACIÓN: esa vía es solo para peatones; los vehículos no entran.\n\n«PASO DE PEATONES» es la cuadrada azul con el peatón sobre las franjas. «PROHIBIDA LA CIRCULACIÓN DE PEATONES» sería un círculo con borde rojo. «SENDA PEATONAL» es el término cebo, más vago.\n\nCLAVE: la misma figura cambia de significado con la forma: círculo azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6238,"bg":"Пътният знак с допълнителна табела предупреждават че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53982.png","v":null,"a":[{"t":"дължината на участъка с последователни опасни завои е 1000 м","ok":true,"i":null,"es":"la LONGITUD del tramo de curvas peligrosas es 1000 m"},{"t":"разстоянието до участъка с последователни опасни завои е 1000 м","ok":false,"i":null,"es":"la DISTANCIA hasta el tramo es 1000 m"},{"t":"разстоянието от знака до края на участъка с последователни завои е 1000 м","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo es 1000 m"}],"es":"La señal y tablilla advierten que:","explain":"LA LONGITUD DEL TRAMO DE CURVAS PELIGROSAS ES 1000 m. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6225: triángulo de CURVAS SUCESIVAS con la placa «↑ 1000 m ↑».\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA DISTANCIA HASTA EL TRAMO» sería la cifra sola (compárala con la 6220).\n\nCLAVE: compárala con la 6225 y la 6224. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":12076,"bg":"На кои от изброените превозни средства е разрешено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173456689.png","v":null,"a":[{"t":"автомобили със специален режим на движение","ok":true,"i":null,"es":"automóviles con régimen especial de circulación"},{"t":"превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"vehículos de líneas regulares de transporte público"},{"t":"автомобили със специално предназначение","ok":false,"i":null,"es":"automóviles de uso especial"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"}],"es":"¿A cuáles de los vehículos les está permitido entrar después de esta señal? (2 correctas)","explain":"AUTOMÓVILES CON RÉGIMEN ESPECIAL DE CIRCULACIÓN Y VEHÍCULOS DE LÍNEAS REGULARES DE TRANSPORTE PÚBLICO. Dos correctas.\n\nLA SEÑAL. Círculo BLANCO con borde ROJO, sin dibujo: PROHIBIDA LA CIRCULACIÓN EN AMBOS SENTIDOS.\n\nLA PROHIBICIÓN ES PARA TODOS, CON DOS EXCEPCIONES: los vehículos con régimen especial (ambulancia, bomberos, policía de servicio) y los de las líneas regulares de transporte público.\n\n«USO ESPECIAL» es el cebo de vocabulario: una grúa o una barredora no tienen excepción. «AUTOBUSES» en general tampoco: solo los de línea regular.\n\nCLAVE: compárala con la 5971 y la 12077. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6318,"bg":"При тази ситуация разрешено ли е пресичането на маркировката, за да се извърши указаната със стрелка маневра?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60067.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación, ¿está permitido cruzar la marca vial para realizar la maniobra indicada por la flecha?","explain":"NO.\n\nQUÉ VES. Calle de varios carriles con un pórtico de SEÑALES LUMINOSAS sobre cada carril: sobre el carril IZQUIERDO, una X ROJA; sobre los otros, una flecha VERDE hacia abajo. El coche AZUL, en el carril central, lleva el intermitente IZQUIERDO y la flecha dibuja que quiere pasarse al carril de la izquierda.\n\nLA X ROJA CIERRA ESE CARRIL para tu sentido: no puedes entrar en él, así que no puedes cruzar la marca para pasarte allí.\n\n«SÍ» es el cebo de quien solo mira si la línea es discontinua.\n\nCLAVE: X roja = carril cerrado; flecha verde = carril abierto. Compárala con la 6319. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6319,"bg":"При тази ситуация разрешено ли е пресичането на маркировката, за да извършите указаната със стрелка маневра?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60117.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación, ¿está permitido cruzar la marca vial para realizar la maniobra indicada por la flecha?","explain":"SÍ.\n\nQUÉ VES. El mismo pórtico de SEÑALES LUMINOSAS que la 6318: X ROJA sobre el carril izquierdo y flechas VERDES sobre los otros. Llevas el intermitente DERECHO y la flecha dibuja que te pasas a un carril de la derecha.\n\nEL CARRIL AL QUE VAS TIENE FLECHA VERDE: está abierto para tu sentido. Puedes cruzar la marca discontinua para pasarte a él.\n\n«NO» es el cebo de quien cree que la X roja cierra todos los carriles.\n\nCLAVE: compárala con la 6318."},{"id":11694,"bg":"Когато няма други ограничения, водачът на мотоциклет при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"80 km/h","ok":true,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de moto fuera de población no debe superar:","explain":"80 km/h: las motocicletas fuera de población tienen límite inferior al de los turismos (90). El escalón moto-80/coche-90 fuera de poblado es pregunta fija."},{"id":11695,"bg":"Когато няма други ограничения, водачът на триколесно МПС от категория А при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"80 km/h","ok":true,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de vehículo de tres ruedas categoría A fuera de población no debe superar:","explain":"80 km/h también para el triciclo de categoría A fuera de población: sigue el límite de las motocicletas, no el de los turismos. Tres ruedas de la rama A = régimen de moto."},{"id":11700,"bg":"Когато няма други ограничения, водачът на автомобил от категория В1 при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"}],"es":"Sin otras restricciones, el conductor de turismo categoría B1 fuera de población no debe superar:","explain":"90 km/h: el B1 (cuadriciclo pesado 'turismo') fuera de población sigue el límite de los turismos. A diferencia de las motos (80), los B1 van con los coches en esta tabla."},{"id":11702,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"70 km/h","ok":true,"i":null,"es":"70 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de convoy categoría BE fuera de población no debe superar:","explain":"70 km/h: el conjunto BE fuera de población: el remolque recorta 20 km/h respecto al turismo solo (90). La serie BE es: 70 fuera de poblado, 90 en vía rápida, 100 en autopista."},{"id":11705,"bg":"След този пътен знак разрешената максимална скорост за движение извън населено място е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54016.png","v":null,"a":[{"t":"в зависимост от категорията на превозното средство","ok":true,"i":null,"es":"según la categoría del vehículo"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Después de esta señal la velocidad máxima permitida fuera de población es:","explain":"SEGÚN LA CATEGORÍA DEL VEHÍCULO. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, la señal de FIN DE LA LIMITACIÓN de 40 km/h. De frente viene un camión.\n\nDESPUÉS DE LA SEÑAL VUELVE EL LÍMITE GENERAL, y ese límite depende del tipo de vehículo: no es el mismo para un turismo que para un camión o un autobús.\n\n«90 km/h» es el cebo más tentador: es el límite general fuera de población para un TURISMO, pero la pregunta habla de cualquier vehículo.\n\n«130 km/h» y «60 km/h» no corresponden a esta vía.\n\nCLAVE: fin de limitación = vuelve el límite general de cada categoría. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11707,"bg":"Каква трябва да бъде скоростта на движение, когато широчината на пътя не позволява разминаване без допълнителни мерки за сигурност?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"такава, че водачът да може да спре на половината от дължината на пътя, който вижда","ok":true,"i":null,"es":"tal que el conductor pueda parar en la MITAD de la distancia que ve"},{"t":"не по-голяма от 50 km/h","ok":false,"i":null,"es":"no superior a 50 km/h"},{"t":"такава, че водачът да може да спре в зоната на пътя, който вижда","ok":false,"i":null,"es":"tal que pueda parar en toda la distancia que ve"}],"es":"¿Qué velocidad usar cuando la anchura de la vía no permite el cruce sin retroceder?","explain":"Poder parar en la MITAD de la distancia visible: en vía estrecha el que viene de frente necesita la otra mitad para frenar él. Si cada uno solo pudiera parar en TODA su distancia visible, chocarían en el centro: la mitad es la matemática del cruce."},{"id":6250,"bg":"Коя линия указва правилната траектория за движение при завиване наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69851.png","v":null,"a":[{"t":"синята","ok":true,"i":null,"es":"la azul"},{"t":"червената","ok":false,"i":null,"es":"la roja"},{"t":"и двете","ok":false,"i":null,"es":"las dos"}],"es":"¿Qué línea indica la trayectoria correcta para girar a la izquierda?"},{"id":6265,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70084.png","v":null,"a":[{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":true,"i":null,"es":"correcto"}],"es":"En esta situación debo dejar pasar al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha. El semáforo da VERDE con flechas (izquierda; recto y derecha). En la calle a la que vas a entrar, una PEATONA está cruzando. De frente viene un coche rojo.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS. El verde te deja girar, pero no pasar por delante de quien cruza.\n\n«INCORRECTO» es el cebo de quien cree que el verde le da paso libre.\n\nCLAVE: es la misma escena que la 13509. Ver Leyes → «Paso de peatones»."},{"id":6362,"bg":"Когато при недостатъчна широчина на платното за движение завиването в обратна посока започва от дясната пътна лента, водачът на завиващото ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"трябва да пропусне насрещно движещите се ППС","ok":true,"i":null,"es":"debe ceder el paso a los vehículos que vienen de frente"},{"t":"трябва да пропусне попътно движещите се от лявата му страна ППС","ok":true,"i":null,"es":"debe ceder el paso a los que circulan en su mismo sentido por su izquierda"},{"t":"е с предимство пред насрещно движещите се ППС","ok":false,"i":null,"es":"tiene prioridad sobre el tráfico de frente"},{"t":"е с предимство пред попътно движещите се от лявата му страна ППС","ok":false,"i":null,"es":"tiene prioridad sobre el que viene por su izquierda"}],"es":"Cuando, por anchura insuficiente de la calzada, el cambio de sentido comienza desde el carril derecho, el conductor del vehículo que gira: (2 correctas)","explain":"CEDER AL TRÁFICO DE FRENTE Y CEDER AL TRÁFICO QUE VIENE POR SU IZQUIERDA EN SU MISMO SENTIDO. Dos correctas.\n\nQUÉ VES. Un CAMIÓN en el carril DERECHO con el intermitente IZQUIERDO: por falta de anchura, va a dar la vuelta (cambio de sentido) empezando desde el carril derecho. Por el carril izquierdo, en su mismo sentido, va un coche ROJO.\n\nEL QUE HACE EL CAMBIO DE SENTIDO CEDE A TODOS. Al dar la vuelta desde la derecha atraviesa el carril de su izquierda (por donde va el rojo) y luego el carril contrario. Tiene que ceder a los que van en su sentido por la izquierda y a los que vienen de frente.\n\n«TIENE PRIORIDAD SOBRE LOS DE FRENTE» y «TIENE PRIORIDAD SOBRE LOS DE SU IZQUIERDA» son los cebos: el cambio de sentido no da prioridad sobre nadie.\n\nCLAVE: cambio de sentido = la maniobra que más cruza, y la que más cede. Compárala con la 6363 (la misma escena). Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6363,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el conductor del turismo"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el conductor del camión"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL TURISMO. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6362: un CAMIÓN en el carril derecho, con el intermitente izquierdo, va a dar la vuelta desde ese carril; por el carril izquierdo, en el mismo sentido, va un turismo ROJO.\n\nEL QUE DA LA VUELTA CEDE. El camión, para cambiar de sentido, tiene que cruzar el carril del turismo. El turismo sigue recto por su carril: tiene preferencia.\n\n«EL CAMIÓN» es el cebo de quien piensa que el camión, por estar a la derecha o por haber señalizado, pasa primero.\n\nCLAVE: cambio de sentido = cede a todos. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6423,"bg":"При тази ситуация, когато пешеходецът напуска платното за движение и имам видимост към пешеходната пътека, е разрешено да продължа изпреварването.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71919.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación, cuando el peatón abandona la calzada y tengo visibilidad, puedo adelantar. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. Llevas el intermitente IZQUIERDO y estás adelantando a un coche ROJO. Delante hay un PASO DE PEATONES. Un peatón está terminando de cruzar por la derecha.\n\nQUE ESE PEATÓN SALGA NO CAMBIA LA REGLA. ANTES DE UN PASO DE PEATONES NO SE ADELANTA. Está prohibido adelantar sobre el paso de peatones e inmediatamente antes de él: el vehículo al que adelantas puede estar tapándote a alguien que cruza. Aunque el peatón que ves ya esté saliendo y tengas visibilidad, la prohibición sigue en pie.\n\n«CORRECTO» es el cebo: la frase suena razonable («ya no hay nadie, ya veo»), pero la norma no depende de eso.\n\nCLAVE: compárala con la 6421: la prohibición de adelantar junto al paso de peatones es absoluta. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6424,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71954.png","v":null,"a":[{"t":"прекратявам изпреварването","ok":true,"i":null,"es":"abandono el adelantamiento"},{"t":"продължавам изпреварването, за да премина преди пешеходците да са навлезли в лявата лента","ok":false,"i":null,"es":"continúo para pasar antes que los peatones entren en el carril izquierdo"},{"t":"продължавам изпреварването, като предупреждавам пешеходците със звуков сигнал","ok":false,"i":null,"es":"continúo avisando a los peatones con el claxon"}],"es":"En esta situación:","explain":"ABANDONO EL ADELANTAMIENTO. Una sola correcta.\n\nQUÉ VES. Calle urbana. Llevas el intermitente IZQUIERDO y estás adelantando a un coche AZUL. Delante hay un PASO DE PEATONES y dos personas están cruzando.\n\nANTES DE UN PASO DE PEATONES NO SE ADELANTA. Está prohibido adelantar sobre el paso de peatones e inmediatamente antes de él: el vehículo al que adelantas puede estar tapándote a alguien que cruza. Con peatones ya cruzando, lo único correcto es renunciar a la maniobra y volver detrás del azul.\n\n«CONTINÚO PARA PASAR ANTES DE QUE LOS PEATONES LLEGUEN AL CARRIL IZQUIERDO» es el cebo de la carrera contra el peatón.\n\n«CONTINÚO AVISANDO CON EL CLAXON» es el otro cebo: el claxon no da preferencia sobre los peatones.\n\nCLAVE: peatones en el paso = se cancela el adelantamiento. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":12043,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"изпреварвам трактора, защото свободното разстояние пред него е достатъчно за изпреварване","ok":false,"i":null,"es":"adelanto al tractor porque hay espacio delante de él"},{"t":"изпреварвам внимателно, защото тракторът ми сигнализира за това","ok":false,"i":null,"es":"adelanto con cuidado porque el tractor me señaliza para ello"},{"t":"не предприемам изпреварване, защото тракторът иска да премине наляво","ok":true,"i":null,"es":"no adelanto porque el tractor quiere girar a la izquierda"}],"es":"¿Cuál es la actuación correcta?","explain":"No adelantes: el tractor quiere girar a la IZQUIERDA: cruzaría justo tu trayectoria de adelantamiento. El 'espacio delante de él' es la trampa clásica (ese hueco es para su giro), y un tractor jamás te 'autoriza' a adelantar: esa lectura de sus señales es un mito letal."},{"id":11619,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи или спира в лентата за принудително спиране, освен при повреда на пътното превозно средство, както и при здравословни проблеми на водача или пътниците в превозното средство","ok":true,"i":null,"es":"circular o detenerse en el carril de parada de emergencia, salvo avería del vehículo o problemas de salud del conductor o de los pasajeros"},{"t":"да спира пътното превозно средство за престой или за паркиране извън специално обозначените за това места","ok":true,"i":null,"es":"detener el vehículo para parada o estacionamiento fuera de los lugares especialmente señalizados"},{"t":"да управлява моторно превозно средство с прикачено ремарке","ok":false,"i":null,"es":"conducir un vehículo de motor con remolque enganchado"}],"es":"Al circular por autopista al conductor le está prohibido: (2 correctas)","explain":"En autopista está prohibido: usar el carril de emergencia salvo avería o problema de salud, y parar o estacionar fuera de los lugares señalizados. Circular CON remolque está permitido (a 100 km/h): el distractor eterno de esta familia."},{"id":11708,"bg":"Когато няма други ограничения, водачът на МПС от категория “В” при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"140 km/h","ok":true,"i":null,"es":"140 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"}],"es":"Cuando no hay otras restricciones, el conductor de categoría B en autopista no debe superar:","explain":"140 km/h: turismos categoría B en autopista búlgara. La escalera del B: 50 poblado, 90 fuera, 120 vía rápida, 140 autopista: cuatro números que hay que recitar dormido."},{"id":11710,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ, при движение по скоростен път не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"}],"es":"Cuando no hay otras restricciones, el conductor de un tren de vehículos BE en vía rápida no debe superar:","explain":"90 km/h: el conjunto BE en vía rápida. Su escalera propia: 70 fuera de poblado, 90 en vía rápida, 100 en autopista: siempre por debajo del turismo solo."},{"id":11713,"bg":"Когато няма други ограничения, водачът на мотоциклет при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"100 km/h","ok":true,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"}],"es":"Cuando no hay otras restricciones, el conductor de motocicleta en autopista no debe superar:","explain":"100 km/h: las motocicletas en autopista: 40 menos que los turismos (140). La escalera de la moto: 50 poblado, 80 fuera, 90 vía rápida, 100 autopista."},{"id":11714,"bg":"Когато няма други ограничения, на водача на мотоциклет, при движение извън населено място, по автомобилен път, е забранено да се движи със скорост по-висока от:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"80 km/h","ok":true,"i":null,"es":"80 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Cuando no hay otras restricciones, al conductor de motocicleta fuera de población por carretera de automóviles le está prohibido superar:","explain":"80 km/h: 'carretera de automóviles' aquí se refiere al régimen general fuera de población para la moto, cuyo límite es 80. Aprende la respuesta literal del banco: moto fuera de poblado = 80."},{"id":11715,"bg":"Когато няма други ограничения, водачът на МПС от категория А при движение по скоростен път не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"}],"es":"Cuando no hay otras restricciones, el conductor de categoría A en vía rápida no debe superar:","explain":"90 km/h: la categoría A (motos) en vía rápida. Un escalón por debajo de su límite de autopista (100) y uno por encima del de fuera de poblado (80): la escalera de la moto sube de 10 en 10."},{"id":11716,"bg":"Навлизането по автомагистрала е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при теглене на МПС с гъвкава връзка","ok":true,"i":null,"es":"cuando se remolca con cable FLEXIBLE"},{"t":"когато поради повреда МПС не може да се движи със скорост по-висока от 50 km/h","ok":true,"i":null,"es":"cuando por avería el vehículo no puede superar 50 km/h"},{"t":"при превоз на животни","ok":false,"i":null,"es":"al transportar animales"},{"t":"при теглене с твърда връзка","ok":false,"i":null,"es":"cuando se remolca con barra RÍGIDA"}],"es":"La entrada en autopista está PROHIBIDA: (2 correctas)","explain":"Entrada en autopista prohibida: remolcando con cable FLEXIBLE (sin control a esa velocidad) y cuando la avería no deja superar 50 km/h (obstáculo móvil letal). La barra rígida y los animales están permitidos: los distractores de siempre."},{"id":11717,"bg":"Какво трябва да предприемете, ако при движение по автомагистрала в превозното средство възникне повреда и то не може да се движи със скорост по-висока от 50 km/h?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да напусна автомагистралата на най-близкото разрешено място","ok":true,"i":null,"es":"debo abandonar la autopista en el lugar permitido más cercano"},{"t":"мога да продължа движението в лентата за принудително спиране","ok":false,"i":null,"es":"puedo continuar la marcha por el carril de parada de emergencia"},{"t":"задължен съм да спра в лентата за принудително спиране","ok":false,"i":null,"es":"estoy obligado a detenerme en el carril de parada de emergencia"}],"es":"¿Qué debes hacer si al circular por autopista el vehículo sufre una averia y no puede superar los 50 km/h?","explain":"Si la avería no te deja superar 50 km/h: abandona la autopista por el lugar permitido más cercano. El carril de emergencia no es un carril lento (ni para circular ni de parada obligatoria si aún puedes salir): es para emergencias detenidas."},{"id":11721,"bg":"На автомобилен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"automóviles con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотоциклети с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"motocicletas con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"леки автомобили с ремаркета","ok":false,"i":null,"es":"turismos con remolque"}],"es":"En carretera de automóviles esta prohibida la circulación de: (3 correctas)","explain":"En carretera de automóviles no circulan: automóviles ni motos que por construcción no superan 50 km/h, ni ciclomotores (45 km/h de fábrica). Los turismos con remolque sí: el remolque no convierte al coche en lento."},{"id":11722,"bg":"На скоростен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"automóviles con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотоциклети с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"motocicletas con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"съчленени пътни превозни средства","ok":false,"i":null,"es":"vehículos articulados"}],"es":"En vía rápida esta prohibida la circulación de: (3 correctas)","explain":"En vía rápida, misma tríada prohibida: automóviles y motos de menos de 50 km/h constructivos y ciclomotores. Los vehículos articulados circulan legalmente: tamaño no es lentitud."},{"id":11723,"bg":"На автомобилен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"automóviles con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотоциклети с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"motocicletas con velocidad máxima por construcción inferior a 50 km/h"},{"t":"съчленени пътни превозни средства","ok":false,"i":null,"es":"vehículos articulados"},{"t":"автомобили с товар над 10 t","ok":false,"i":null,"es":"automóviles con carga superior a 10 t"}],"es":"En carretera de automóviles esta prohibida la circulación de: (2 correctas)","explain":"Variante de la misma regla: prohibidos los de velocidad constructiva inferior a 50 km/h (coches y motos). Ni los articulados ni la carga de 10 t están vetados: el criterio es VELOCIDAD, nunca tamaño o peso."},{"id":11724,"bg":"На автомобилен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"automóviles con velocidad máxima por construcción inferior a 50 km/h"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"автомобили с товар над 10 t","ok":false,"i":null,"es":"automóviles con carga superior a 10 t"},{"t":"автомобили превозващи живи животни","ok":false,"i":null,"es":"vehículos transportando animales vivos"}],"es":"En carretera de automóviles esta prohibida la circulación de: (2 correctas)","explain":"Prohibidos: los automóviles de menos de 50 km/h constructivos y los TRACTORES (lentos por definición). La carga pesada y los animales vivos viajan legalmente: el filtro de la vía rápida es solo la velocidad."},{"id":11725,"bg":"На автомагистрала е разрешено движението на автомобили и мотоциклети, чиято конструктивна максимална скорост е по-висока от:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"45 km/h","ok":false,"i":null,"es":"45 km/h"}],"es":"En autopista esta permitida la circulación de automóviles y motocicletas cuya velocidad máxima constructiva sea superior a:","explain":"Superior a 50 km/h: es el umbral constructivo de entrada a la autopista. El vehículo debe PODER mantener el ritmo del flujo: 50 es la línea que separa al tráfico rápido del obstáculo."},{"id":11726,"bg":"На автомобилен път е забранено движението на МПС с конструктивна максимална скорост по-малка от:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"es":"En carretera de automóviles esta prohibida la circulación de vehículos con velocidad máxima constructiva inferior a:","explain":"Inferior a 50 km/h: el mismo umbral formulado desde la prohibición. 50 km/h constructivos es el número mágico de acceso a autopista y carretera de automóviles: cae en ambas direcciones."},{"id":12063,"bg":"Какво трябва да направите при тази ситуация?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"веднага се отклонявам наляво и навлизам в лявата лента","ok":false,"i":null,"es":"me desvío inmediatamente a la izquierda y entro en el carril izquierdo"},{"t":"увеличавам скоростта","ok":false,"i":null,"es":"aumento la velocidad"},{"t":"пропускам синия автомобил да навлезе пред мен","ok":true,"i":null,"es":"dejo que el automóvil azul entre delante de mí"}],"es":"¿Qué debes hacer en esta situación?","explain":"Deja entrar al azul delante de ti: ceder en la confluencia evita el conflicto. Lanzarte al carril izquierdo sin más es una maniobra brusca sin comprobación, y acelerar para 'ganar' el hueco es la receta del accidente: la cortesía aquí es la norma."},{"id":12080,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"automóviles con velocidad máxima por construcción inferior a 50 km/h"},{"t":"мотоциклети с конструктивна максимална скорост по-малка от 50 km/h","ok":true,"i":null,"es":"motocicletas con velocidad máxima por construcción inferior a 50 km/h"},{"t":"автомобили със специално предназначение","ok":false,"i":null,"es":"automóviles de uso especial"},{"t":"автомобили с товар над 10 t","ok":false,"i":null,"es":"automóviles con carga superior a 10 t"}],"es":"En autopista esta prohibida la circulación de: (2 correctas)","explain":"En autopista no circulan los automóviles ni las motos con velocidad constructiva inferior a 50 km/h: el filtro universal. Los vehículos de uso especial y la carga pesada entran legalmente si alcanzan la velocidad: el criterio nunca es el tipo, siempre la velocidad."},{"id":5633,"bg":"Разрешено ли е водачите на двуколесни МПС да се движат успоредно един до друг?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, когато се вместват в една пътна лента","ok":false,"i":null,"es":"sí, cuando caben en un solo carril"},{"t":"да, но само в населени места","ok":false,"i":null,"es":"sí, pero solo dentro de poblado"},{"t":"да, но само най-вдясно на платното за движение","ok":false,"i":null,"es":"sí, pero solo lo más a la derecha de la calzada"}],"es":"¿Está permitido que los conductores de vehículos de dos ruedas circulen en paralelo uno junto a otro?","explain":"No: los vehículos de dos ruedas no circulan en paralelo uno junto a otro: la ley exige uno detrás de otro. Ni el ancho del carril ni el poblado lo permiten: el paralelo duplica el ancho y elimina el margen de escape."},{"id":5752,"bg":"Задължени ли са водачите на теглещото и тегленото МПС да съгласуват помежду си сигнали за взаимно разбиране по време на тегленето?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"},{"t":"да, но само когато ще се движат по път с интензивно движение","ok":false,"i":null,"es":"sí, pero solo cuando vayan a circular por una vía con tráfico intenso"},{"t":"да, но само при движение по автомагистрала или автомобилен път","ok":false,"i":null,"es":"sí, pero solo al circular por autopista o autovía"}],"es":"¿Están obligados los conductores del vehículo que remolca y del remolcado a acordar entre sí señales de entendimiento mutuo durante el remolcado?","explain":"Sí, en todos los casos: remolcador y remolcado deben acordar señales de entendimiento ANTES de salir (frenar, parar, girar). El convoy actúa como un solo vehículo con dos cerebros: sin protocolo común, choque asegurado."},{"id":12081,"bg":"Тегленето на повредено МПС с допустима максимална маса над 5 t е разрешено да се извършва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с твърда връзка","ok":true,"i":null,"es":"con barra RÍGIDA"},{"t":"от автомобил със специално предназначение за тази цел","ok":true,"i":null,"es":"por un vehículo con equipamiento especial para ese fin"},{"t":"с гъвкава връзка","ok":false,"i":null,"es":"con cable FLEXIBLE"},{"t":"само от автомобил със специално приспособление","ok":false,"i":null,"es":"solo por vehículo con dispositivo especial de enganche"}],"es":"Remolcar un vehículo averiado con MMA superior a 5 t está permitido: (2 correctas)","explain":"Un averiado de más de 5 t se remolca: con barra RÍGIDA o por vehículo con equipamiento especial (grúa). El cable flexible no controla esa masa, y 'solo por vehículo con dispositivo especial' es falso porque la barra rígida también vale: la opción excluyente es la trampa."},{"id":5737,"bg":"Ако водач трябва да управлява МПС, но преди това е консумирал алкохол:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"трябва да изчака да премине въздействието на алкохола","ok":true,"i":null,"es":"debe esperar a que pase el efecto del alcohol"},{"t":"трябва да спи около 2 часа","ok":false,"i":null,"es":"debe dormir unas 2 horas"},{"t":"достатъчно е да изпие едно силно кафе или силен чай без захар","ok":false,"i":null,"es":"basta con tomarse un café fuerte o un té fuerte sin azúcar"},{"t":"достатъчно е да изпие студена енергийна напитка","ok":false,"i":null,"es":"basta con tomarse una bebida energética fría"}],"es":"Si un conductor debe conducir, pero antes ha consumido alcohol:","explain":"Si bebió: esperar a que el efecto PASE: el hígado marca el tiempo y nada lo acelera. Ni dos horas de sueño (insuficiente), ni café, ni bebida energética: solo el tiempo elimina el alcohol."},{"id":5505,"bg":"Разрешено ли е използването на мобилен телефон по време на управление на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, освен при наличие на устройство, позволяващо използването на телефона без участието на ръцете","ok":true,"i":null,"es":"no, salvo que haya un dispositivo que permita usar el teléfono sin las manos"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"не, забранено е във всички случаи","ok":false,"i":null,"es":"no, está prohibido en todos los casos"},{"t":"да, извън населените места","ok":false,"i":null,"es":"sí, fuera de poblado"}],"es":"¿Está permitido usar el teléfono móvil mientras se conduce el vehículo?","explain":"El móvil solo con dispositivo MANOS LIBRES: esa es la única forma legal en marcha. Ni libertad total, ni prohibición absoluta (el manos libres existe), ni excepción fuera de poblado."},{"id":5507,"bg":"Ако няма устройство, позволяващо използването на мобилен телефон без участие на ръцете му, за да отговори на повикване по телефона водачът:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"трябва да намери безопасно място, където да спре","ok":true,"i":null,"es":"debe encontrar un lugar seguro donde detenerse"},{"t":"може да държи кормилното колело с една ръка и да разговаря","ok":false,"i":null,"es":"puede sujetar el volante con una mano y hablar"},{"t":"достатъчно е да намали скоростта, след което да използва телефона","ok":false,"i":null,"es":"basta con reducir la velocidad y después usar el teléfono"},{"t":"трябва незабавно да спре","ok":false,"i":null,"es":"debe detenerse inmediatamente"}],"es":"Si no hay un dispositivo que permita usar el teléfono móvil sin las manos, para responder una llamada el conductor:","explain":"Sin manos libres: busca un lugar SEGURO donde detenerte y entonces responde. Sujetar el volante con una mano es la infracción misma, y 'detenerse inmediatamente' donde sea crea un peligro nuevo."},{"id":11360,"bg":"Кой от изброените документи е задължен да носи водачът, когато управлява МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"знак за първоначален технически преглед или удостоверение за периодичен преглед за техническа изправност","ok":true,"i":null,"es":"el distintivo de la inspección técnica inicial o el certificado de la inspección técnica periódica"},{"t":"свидетелство за регистрация на МПС","ok":true,"i":null,"es":"permiso de circulación del vehículo"},{"t":"документ за сключена застраховка „Гражданска отговорност” на автомобилиста","ok":true,"i":null,"es":"el documento del seguro de responsabilidad civil del automovilista contratado"},{"t":"документ за платен данък МПС","ok":false,"i":null,"es":"documento del impuesto de vehículos pagado"}],"es":"¿Cuál de los documentos indicados está obligado a llevar el conductor cuando conduce? (3 correctas)","explain":"A bordo: distintivo/certificado de la inspección técnica, permiso de circulación y seguro de responsabilidad civil. El impuesto de vehículos pagado no se acredita en el control de tráfico: mismo distractor tributario de la familia."},{"id":8301,"bg":"В кои случаи компетентните органи не издават дубликат на свидетелство за управление на МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато водачът не е заплатил изцяло дължимите глоби","ok":true,"i":null,"es":"cuando el conductor no ha pagado íntegramente las multas debidas"},{"t":"когато свидетелството е загубено","ok":false,"i":null,"es":"cuando el permiso se ha perdido"},{"t":"когато свидетелството е откраднато","ok":false,"i":null,"es":"cuando el permiso ha sido robado"}],"es":"¿En qué casos las autoridades competentes no emiten un duplicado del permiso de conducción?","explain":"No emiten duplicado del permiso a quien tiene multas pendientes de pago íntegro: el duplicado se usa como palanca de cobro. La pérdida y el robo son precisamente los motivos NORMALES para pedir duplicado."},{"id":11394,"bg":"За административни нарушения, които са установени в момента на извършването им, може да бъде наложена глоба с фиш, когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за нарушението не е предвидено лишаване от право да управлява моторно превозно средство","ok":true,"i":null,"es":"para la infracción no está prevista la privación del derecho a conducir"},{"t":"за нарушението не е предвидено отнемане на контролни точки","ok":true,"i":null,"es":"no tiene previsto retirada de puntos"},{"t":"за нарушението не е предвидено служебно прекратяване на регистрацията на превозното средство","ok":false,"i":null,"es":"para la infracción no está prevista la baja de oficio de la matriculación del vehículo"},{"t":"за нарушението не е предвидено спиране от движение на превозното средство","ok":false,"i":null,"es":"para la infracción no está prevista la inmovilización del vehículo"}],"es":"Por infracciones administrativas detectadas en el momento de cometerse puede imponerse una multa con boletín cuando: (2 correctas)","explain":"La multa con boletín (procedimiento rápido) cabe cuando la infracción NO conlleva privación del permiso NI retirada de puntos: solo las leves. Las que tocan permiso o puntos exigen acta y procedimiento completo."},{"id":11413,"bg":"Водач, който oрганизира или участва в нерегламентирани състезания по пътищата, отворени за обществено ползване се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"}],"es":"El conductor que organiza o participa en carreras no autorizadas en vías públicas es sancionado con:","explain":"Carreras ilegales: multa Y privación del permiso: sanción combinada. Organizar o participar da igual: ambos convierten la vía pública en circuito y ambos pierden el permiso."},{"id":11499,"bg":"Контролните органи временно спират от движение моторно превозно средство на собственик, който:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"управлява МПС, без да притежава съответното свидетелство за управление","ok":false,"i":null,"es":"conduzca un vehículo sin poseer el permiso de conducción correspondiente"},{"t":"не изпълни предписанието за медицинско изследване на концентрацията на алкохол в кръвта му","ok":false,"i":null,"es":"no cumpla la orden de someterse al examen médico de concentración de alcohol en sangre"},{"t":"управлява МПС в участък от пътната мрежа с въведена временна забрана за движение извън населените места","ok":true,"i":null,"es":"conduzca por un tramo de la red viaria con prohibición temporal de circulación fuera de poblado"},{"t":"предоставя управлението на МПС на лице, което е с концентрация алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"ceda la conducción del vehículo a una persona con más de 0,5 por mil de alcohol en sangre"}],"es":"Las autoridades de control inmovilizan temporalmente el vehículo de motor del propietario que: (2 correctas)","explain":"Inmovilización temporal del vehículo del propietario que: circula por tramo con prohibición temporal fuera de poblado, o cede el volante a alguien con más de 0,5‰. Conducir sin permiso o negarse al examen acarrean otras medidas (contra la persona o la matrícula)."},{"id":11500,"bg":"За административно нарушение, установено и заснето с автоматизирано техническо средство може да бъде наложена глоба с електронен фиш, когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за нарушението не е предвидено лишаване от право да управлява МПС","ok":true,"i":null,"es":"no tiene previsto privación del permiso"},{"t":"за нарушението не е предвидено отнемане на контролни точки","ok":true,"i":null,"es":"no tiene previsto retirada de puntos"},{"t":"за нарушението не е предвидено служебно прекратяване на регистрацията на МПС","ok":false,"i":null,"es":"no tiene previsto cancelación del registro del vehículo"},{"t":"за нарушението не е предвидено спиране от движение на МПС","ok":false,"i":null,"es":"no tiene previsto inmovilización del vehículo"}],"es":"Una infracción captada por cámara automática puede sancionarse con multa electrónica si: (2 correctas)","explain":"La multa electrónica por cámara automática procede si la infracción NO conlleva privación del permiso NI retirada de puntos: el mismo criterio que el boletín presencial. Lo grave no se despacha por correo: exige procedimiento con el conductor identificado."},{"id":11644,"bg":"Контролните органи временно спират от движение моторно превозно средство на собственик, който:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"предоставя управлението на МПС на лице за участие в нерегламентирани състезания по пътищата, отворени за обществено ползване","ok":true,"i":null,"es":"ceda la conducción del vehículo a una persona para participar en carreras ilegales en vías abiertas al uso público"},{"t":"при управление на МПС в населено място превиши максимално разрешената скорост с повече от 50 кm/h","ok":true,"i":null,"es":"conduciendo en poblado supere la velocidad máxima permitida en más de 50 km/h"},{"t":"няма задължителната застраховка &quot;Гражданска отговорност&quot; на автомобилистите","ok":true,"i":null,"es":"no tiene el seguro obligatorio de responsabilidad civil de los automovilistas"},{"t":"който поради незнание е извършил немаловажно нарушение на правилата за движение","ok":false,"i":null,"es":"que por desconocimiento haya cometido una infracción no menor de las normas de circulación"}],"es":"Las autoridades de control inmovilizan temporalmente el vehículo de motor del propietario que: (3 correctas)","explain":"Inmovilización temporal del vehículo: ceder el coche para carreras ilegales, superar en poblado el límite en más de 50 km/h y carecer del seguro obligatorio. La infracción 'por desconocimiento' retira el PERMISO, no inmoviliza el vehículo: cada medida tiene su diana."},{"id":11645,"bg":"За административни нарушения установени в момента на извършването им, може да бъде наложена глоба с фиш, като размерът на глобата:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"е в минималния размер, или в размера, посочен в административнонаказателната разпоредба за съответното нарушение","ok":true,"i":null,"es":"es del importe mínimo, o del importe fijado en la disposición sancionadora para la infracción correspondiente"},{"t":"се определя от контролния орган","ok":false,"i":null,"es":"la determina el agente de control"},{"t":"е в максималния размер от предвидените за съответното нарушение","ok":false,"i":null,"es":"es del importe máximo de los previstos para la infracción correspondiente"},{"t":"е в осреднена стойност от предвидените за съответното нарушение","ok":false,"i":null,"es":"es de un valor medio de los previstos para la infracción correspondiente"}],"es":"Por infracciones administrativas detectadas en el momento de cometerse puede imponerse una multa con boletín, y el importe de la multa:","explain":"La multa del boletín es la MÍNIMA (o la fijada expresamente para esa infracción): el boletín es el procedimiento rápido y benigno. El agente no la 'decide' a ojo, ni se aplica el máximo ni la media: quien discute, pasa al acta."},{"id":11647,"bg":"Контролните органи временно прекратяват регистрацията на моторно превозно средство на собственик, който управлява моторно превозно средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с концентрация на алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"con una concentración de alcohol en sangre superior a 0,5 por mil"},{"t":"не изпълни предписанието за медицинско изследване за установяване на концентрацията на алкохол в кръвта или употреба на наркотични вещества или техни аналози","ok":true,"i":null,"es":"no cumpla la orden de someterse al examen médico para determinar la concentración de alcohol en sangre o el consumo de estupefacientes o sus análogos"},{"t":"откаже да му бъде извършена проверка с техническо средство за установяване на концентрацията на алкохол в кръвта или употребата на наркотични вещества или техни аналози","ok":true,"i":null,"es":"se niegue al control con dispositivo técnico para determinar la concentración de alcohol en sangre o el consumo de estupefacientes o sus análogos"},{"t":"и превиши максимално разрешената скорост в населено място с повече от 50 km/h","ok":false,"i":null,"es":"y supere la velocidad máxima permitida en poblado en más de 50 km/h"}],"es":"Las autoridades de control dan de baja temporalmente la matriculación del vehículo del propietario que conduce el vehículo de motor: (3 correctas)","explain":"Baja temporal de matriculación por: más de 0,5‰ de alcohol, incumplir la orden del examen médico o negarse al control técnico (de alcohol o drogas): el trío del alcohol/drogas golpea también al vehículo. La velocidad tiene sus propias sanciones, no esta."},{"id":5345,"bg":"Водач, който е участник в ПТП, при което има пострадали хора:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"трябва да изчака на мястото на произшествието представител на полицията","ok":true,"i":null,"es":"debe esperar en el lugar del accidente a un representante de la policía"},{"t":"трябва да вземе мерки следите от произшествието да бъдат запазени до тяхното фиксиране или описване от компетентните служби","ok":true,"i":null,"es":"debe tomar medidas para que las huellas del accidente se conserven hasta que los servicios competentes las registren o describan"},{"t":"не трябва да консумира алкохолни напитки до пристигането на контролните органи","ok":true,"i":null,"es":"no debe consumir bebidas alcohólicas hasta la llegada de las autoridades de control"},{"t":"може да напусне местопроизшествието, след като установи какви са последиците от него","ok":false,"i":null,"es":"puede abandonar el lugar del accidente después de comprobar cuáles son sus consecuencias"}],"es":"El conductor implicado en un accidente en el que hay personas heridas: (3 correctas)","explain":"Con heridos, el implicado: espera a la policía en el lugar, conserva las huellas y NO consume alcohol hasta que lleguen las autoridades (impediría el control fiable). Marcharse tras 'comprobar las consecuencias' es fuga."}]);
